// Weltweite Drohnenregeln je Land (Reise-Check): regulatorische Eckdaten und
// Kurzhinweise für 140 Länder. Verbindlich sind stets die offiziellen Stellen
// (siehe sourceUrl); keine Rechtsberatung.
// Datenquelle siehe Einstellungen → Datenquellen.

export interface CountryDroneRule {
  /** ISO-3166-1 alpha-2 Ländercode. */
  code: string;
  /** Deutscher Ländername. */
  name: string;
  /** Maximale Flughöhe über Grund in Metern (null = nicht pauschal geregelt). */
  maxAltitude: number | null;
  /** Registrierungspflicht für den Betreiber. */
  registrationRequired: boolean;
  /** Haftpflicht-/Versicherungspflicht. */
  insuranceRequired: boolean;
  /** Link zur offiziellen Quelle/Behörde. */
  sourceUrl: string;
  /** Länderspezifische Hinweise (Kurztexte). */
  rules: string[];
}

export const COUNTRY_DRONE_RULES: CountryDroneRule[] = [
  { code: "AL", name: "Albanien", maxAltitude: 120, registrationRequired: true, insuranceRequired: false, sourceUrl: "https://www.aac.gov.al/avione-pa-pilote-drone/", rules: ["In Albanien musst du deine Drohne ab 250 Gramm Startgewicht bei der Zivilluftfahrtbehörde AAC registrieren.", "Eine gesetzliche Versicherungspflicht für Freizeitpiloten ist nicht bekannt, wird aber empfohlen.", "Albanien hat aus früheren Zeiten noch viele militärische Sperrzonen, dazu einen 5-Kilometer-Sperrbereich rund um den Flughafen Tirana sowie Einschränkungen über den UNESCO-Welterbestätten Berat, Gjirokastra und Butrint. Verstöße werden mit Bußgeldern zwischen 500 und 5.000 Euro geahndet.", "In der offenen Kategorie gilt eine maximale Flughöhe von 120 Metern über Grund, bei durchgehender Sichtverbindung zur Drohne."] },
  { code: "DZ", name: "Algerien", maxAltitude: null, registrationRequired: true, insuranceRequired: false, sourceUrl: "https://drone-laws.com/drone-laws-in-algeria/", rules: ["Wichtiger Hinweis: Für Algerien gibt es kein öffentlich zugängliches, kodifiziertes Drohnenrecht für Freizeitpiloten. Die Einfuhr benötigt stattdessen eine vorherige Genehmigung des Verteidigungsministeriums – Berichten zufolge wird diese ausländischen Besuchern praktisch nicht erteilt.", "Reisende berichten übereinstimmend von Beschlagnahmungen der Drohne bei der Einreise, ohne dass es – anders als in manchen Nachbarländern – ein Verwahrsystem gäbe, über das man sein Gerät bei der Ausreise zurückbekommt.", "Eine feste Angabe zu Flughöhe oder Versicherungspflicht existiert mangels Regelwerk nicht.", "Für die Algerien-Reise gilt daher: Drohne besser gar nicht erst mitnehmen. Ein praktikabler legaler Weg für Touristen ist nicht erkennbar."] },
  { code: "AR", name: "Argentinien", maxAltitude: 122, registrationRequired: true, insuranceRequired: false, sourceUrl: "https://www.argentina.gob.ar/anac/nuevo-marco-normativo-para-la-operacion-de-drones", rules: ["Seit August 2025 gilt mit der Resolution ANAC Nr. 550/2025 ein neues dreistufiges System aus offener, spezifischer und zertifizierter Kategorie, das die früheren 20 Klassifizierungen ablöst und sich stärker an europäischen und ICAO-Standards orientiert.", "In der offenen Kategorie (Drohnen bis 25 Kilogramm) genügt eine kostenlose digitale eidesstattliche Erklärung beim Nationalen Luftfahrzeugregister; eine klassische Zulassung mit Kennzeichen ist erst ab 25 Kilogramm in der spezifischen Kategorie vorgeschrieben.", "Der Flug ist unter anderem über Flughäfen, Militär- und Sicherheitseinrichtungen, Nationalparks sowie in unmittelbarer Nähe von Regierungsgebäuden wie der Casa Rosada und ausländischen Botschaften untersagt; auch entlang von Autobahnen, Bahnlinien und Stromleitungen gelten Mindestabstände.", "Eine Haftpflichtversicherung ist für die spezifische und zertifizierte Kategorie vorgeschrieben; ob sie auch für rein private Freizeitflüge im offenen Bereich unter 25 Kilogramm zwingend ist, lässt sich aus den verfügbaren Quellen nicht eindeutig klären, weshalb vor der Reise eine Rückfrage bei ANAC sinnvoll ist.", "Gesonderte Regeln speziell für ausländische Touristen sind in den verfügbaren Quellen nicht dokumentiert."] },
  { code: "AZ", name: "Aserbaidschan", maxAltitude: null, registrationRequired: true, insuranceRequired: false, sourceUrl: "https://caa.gov.az", rules: ["Aserbaidschan hat sein Drohnenrecht erst im August 2026 grundlegend überarbeitet – vorher gab es kaum einheitliche Regeln, Freizeitpiloten mussten sich im Einzelfall bei mehreren Sicherheitsbehörden abstimmen.", "Für den Betrieb brauchst du zunächst eine Sondergenehmigung, danach die eigentliche staatliche Registrierung innerhalb von zehn Werktagen – zuständig ist die staatliche Zivilluftfahrtbehörde.", "Verlässliche, öffentlich einsehbare Angaben zu Flughöhen-Grenzen oder einer Versicherungspflicht gibt es aktuell nicht. Wegen der jungen und sich noch entwickelnden Rechtslage lohnt sich vor einem Flug in Aserbaidschan eine direkte Nachfrage bei der Behörde."] },
  { code: "AU", name: "Australien", maxAltitude: 120, registrationRequired: false, insuranceRequired: false, sourceUrl: "https://www.casa.gov.au/knowyourdrone/drone-rules", rules: ["In Australien ist aktuell keine Registrierung für reine Freizeitdrohnen nötig – eine für 2023 geplante Registrierungspflicht ab 250 Gramm wurde von der Regierung auf unbestimmte Zeit ausgesetzt. Auch die separate \"Operator Accreditation\" (ein kostenloser Online-Test) ist für Hobbyflieger nicht verpflichtend, nur für kommerzielle Piloten. Eine Versicherung ist ebenfalls nicht vorgeschrieben, wird aber empfohlen.", "Die maximale Flughöhe liegt bei 120 Metern (400 Fuß), Mindestabstand zu Personen sind 30 Meter, zu Flugplätzen 5,5 Kilometer. Geflogen werden darf nur bei Tageslicht mit durchgehender Sichtverbindung.", "Wichtiger Vorbehalt für Reisende: Die Regeln für Nationalparks unterscheiden sich stark je Bundesstaat. In New South Wales braucht jeder Start oder jede Landung in einem Park eine Genehmigung, in Victoria sind Freizeitdrohnen in allen Nationalparks generell verboten.", "Besonders relevant für beliebte Reiseziele: Im Uluru-Kata-Tjuta-Nationalpark ist Drohnenbetrieb grundsätzlich untersagt (nur in seltenen Ausnahmefällen nach Rücksprache mit dem Central Land Council wegen der kulturellen Bedeutung für die Anangu), im Kakadu-Nationalpark werden für Freizeitflieger überhaupt keine Genehmigungen ausgestellt.", "Bei Verstößen drohen Bußgelder vor Ort bis rund 1.650 AUD, vor Gericht bis über 16.000 AUD, bei Gefährdung anderer Luftfahrzeuge sogar bis zu zwei Jahre Haft.", "Für Touristen ist Drohnenfliegen in Australien insgesamt unkompliziert und ohne besondere Formalitäten möglich – die eigentliche Hürde liegt darin, für jedes Reiseziel vorher zu prüfen, ob dort ein bundesstaatliches oder lokales Nationalpark-Verbot gilt."] },
  { code: "BS", name: "Bahamas", maxAltitude: 122, registrationRequired: true, insuranceRequired: false, sourceUrl: "https://caabahamas.com/drone-registration/", rules: ["Auf den Bahamas musst du jede Drohne bei der Zivilluftfahrtbehörde CAA-B registrieren – auch als Tourist. Die Gebühr beträgt 30 US-Dollar (Bearbeitung rund fünf Werktage) oder 50 US-Dollar im Express-Verfahren (zwei Werktage), die Genehmigung gilt jeweils nur für den Zeitraum deiner Reise.", "Eine landesweite Versicherungspflicht ist für die Bahamas nicht dokumentiert.", "Geofencing muss aktiviert sein, und für kontrollierten Luftraum brauchst du eine gesonderte Freigabe. Mindestabstände: 500 Fuß zu Menschenansammlungen, 165 Fuß zu Unbeteiligten, rund 3 Meilen zu Flugplätzen.", "Die maximale Flughöhe liegt bei 400 Fuß (rund 122 Metern) über Grund."] },
  { code: "BH", name: "Bahrain", maxAltitude: 120, registrationRequired: true, insuranceRequired: true, sourceUrl: "https://www.bahrain.bh/wps/portal/en/BNP/ExploreBahrain/Drones", rules: ["Aktuell gilt ein vollständiges Drohnenverbot: Das Innenministerium hat am 28. März 2026 wegen der angespannten Sicherheitslage jede Nutzung von Drohnen untersagt, unabhängig vom Zweck – bis auf Weiteres. Bei Verstößen droht die sofortige Vernichtung der Drohne und eine Strafverfolgung. Die folgenden Regeln gelten erst wieder, wenn das Verbot aufgehoben ist.", "In Bahrain muss jede Drohne unabhängig vom Gewicht bei der Zivilluftfahrtbehörde registriert werden. Größere Kategorien ab 5 Kilogramm benötigen zusätzlich vorab eine Importgenehmigung, bevor das Gerät überhaupt ins Land gebracht werden darf.", "Vor jedem einzelnen Flug ist ein Permit bei der Behörde nötig, das mindestens sieben Werktage im Voraus beantragt werden muss und eine Freigabe von Bahrains Verteidigungsstreitkräften und/oder dem Innenministerium voraussetzt. Ein Versicherungsnachweis gehört zu den Antragsunterlagen, eine Haftpflichtversicherung ist damit in der Praxis Voraussetzung für jeden legalen Flug.", "Die maximale Flughöhe liegt bei 122 Metern (400 Fuß), außer in Flughafennähe, wo eine gesonderte Genehmigung nötig ist.", "In der Praxis lässt der Zoll die Einfuhr von Drohnen häufig gar nicht erst zu – Beschlagnahmungen wurden auch dann berichtet, wenn gar keine Nutzung im Land geplant war.", "Für kurzfristige Touristen ist der offiziell vorgesehene Weg damit kaum praktikabel; wer nicht mindestens eine Woche vorher plant und mit einer möglichen Einbehaltung am Zoll rechnet, sollte die Drohne besser zu Hause lassen."] },
  { code: "BD", name: "Bangladesch", maxAltitude: 61, registrationRequired: true, insuranceRequired: true, sourceUrl: "http://www.caab.gov.bd/corporate/rpas.pdf", rules: ["Die Zivilluftfahrtbehörde CAAB erlaubt Flüge grundsätzlich bis zu einer Höhe von 200 Fuß (rund 61 Metern) über Grund; für Betriebe außerhalb dieses Rahmens ist eine gesonderte Sondererlaubnis (Special Flight Operations Certificate) erforderlich.", "Eine Registrierungspflicht bei der CAAB besteht praktisch für jede Drohne ab etwa 250 Gramm Gewicht, mit Kamera oder Mikrofon zur Aufnahme oder mit einer Fernsteuerreichweite über 100 Metern; lediglich kamera- und mikrofonlose Spielzeugdrohnen unter 250 Gramm in ausgewiesenen Grünzonen sind ausgenommen.", "Für gewerbliche oder professionelle Einsätze wie Luftaufnahmen, Vermessung oder Forschung verlangt die CAAB mindestens 45 Tage im Voraus eine Sondererlaubnis samt Nachweis einer Haftpflichtversicherung; für rein private beziehungsweise touristische Freizeitflüge wird eine Versicherung dagegen von den meisten Quellen nur empfohlen, eine einheitlich dokumentierte Pflicht für die reine Freizeitnutzung besteht nicht.", "Flüge sind unter anderem innerhalb von 10 Seemeilen um Flughäfen, 5 Seemeilen um bebaute Gebiete, sicherheitsrelevante Anlagen und Waldbrandgebiete sowie über Menschenansammlungen im Freien untersagt, zudem ist ein seitlicher Mindestabstand von rund 300 Metern zu Gebäuden und unbeteiligten Personen einzuhalten.", "Ausländische Touristen dürfen laut mehreren unabhängigen Quellen ohne eigene Pilotenlizenz fliegen, benötigen aber eine Registrierung ihrer Drohne; da es kein durchgehendes digitales Self-Service-Portal gibt, gelingt die Anmeldung in der Praxis oft nur mit Unterstützung vor Ort ansässiger Kontakte, Agenturen oder Reiseveranstalter.", "Konkrete Bußgeldhöhen bei Verstößen sind offiziell nicht klar beziffert; verfügbare Quellen sprechen allgemein von möglichen Strafen und Bußgeldern, ohne dass die CAAB feste Beträge veröffentlicht hat."] },
  { code: "BB", name: "Barbados", maxAltitude: 120, registrationRequired: true, insuranceRequired: true, sourceUrl: "https://www.bcaa.gov.bb/remotely-piloted-aircraft-systems/", rules: ["In Barbados brauchst du für jeden Drohnenflug eine vorherige Genehmigung über das Antragsverfahren des Premierministeramts – eine einfache Registrierung wie in vielen anderen Ländern reicht nicht.", "Für die Genehmigung sind eine Haftpflichtversicherung mit einer Mindestdeckung von 250.000 US-Dollar sowie ein Schulungsnachweis vorgeschrieben.", "Mindestabstände: 50 Meter zu Menschenansammlungen und Gebäuden, 5 Kilometer zu kontrollierten Flughäfen, Polizei- und Regierungsgebäuden; Flüge in der Nähe des Grantley-Adams-Flughafens musst du 15 Minuten vorher beim Tower anmelden. Es gibt fünf ausgewiesene, freigegebene Fluggebiete für Betreiber mit gültiger Genehmigung.", "Die maximale Flughöhe liegt bei 400 Fuß (rund 122 Metern) über Grund."] },
  { code: "BE", name: "Belgien", maxAltitude: 120, registrationRequired: true, insuranceRequired: true, sourceUrl: "https://mobilit.belgium.be/en/aviation/flying-operating/drones-uas", rules: ["Wer in Belgien wohnt und eine Drohne betreibt, muss sich einmalig über das Drone-Portal (mobilit.belgium.be) bei der Generaldirektion Luftfahrt registrieren – Pflicht ab 250 Gramm Startgewicht sowie für jede leichtere Drohne mit Kamera oder anderer Sensorik.", "Registriert wird nur einmal, und zwar in dem EASA-Staat, in dem du deinen Wohnsitz hast – zum EASA-Raum gehören die EU-Länder plus Island, Liechtenstein, Norwegen und die Schweiz. Die Betreibernummer gilt dann im gesamten EASA-Raum: Wer bereits in einem anderen EASA-Land registriert ist, braucht in Belgien keine zweite Registrierung. Nur wer außerhalb des EASA-Raums wohnt, registriert sich in dem EASA-Staat, in dem er zuerst fliegt.", "Eine Haftpflichtversicherung ist für jede gewerbliche Nutzung sowie für private Drohnen ab 900 Gramm gesetzlich vorgeschrieben; nur rein privat genutzte Leichtdrohnen darunter sind ausgenommen.", "Für die Flugplanung lohnt sich vorab ein Blick in Droneguide (map.droneguide.be) – die offizielle Geozonen-Karte der belgischen Flugsicherung Skeyes, getrennt vom eigentlichen Registrierungsportal.", "In der offenen Kategorie gilt EU-weit einheitlich eine maximale Flughöhe von 120 Metern über Grund."] },
  { code: "BZ", name: "Belize", maxAltitude: 122, registrationRequired: false, insuranceRequired: false, sourceUrl: "https://civilaviation.gov.bz/index.php/drones", rules: ["Belize hat noch kein umfassendes Drohnengesetz – der Umgang läuft über Einzelfall-Genehmigungen der Zivilluftfahrtbehörde DCA (Gebühr rund 30 Belize-Dollar), ein neuer Regelentwurf befand sich Stand September 2026 noch im Konsultationsverfahren.", "Wichtiger Hinweis für Reisende: Die private Einfuhr einer Drohne für eigene Urlaubsfotos ist aktuell nicht vorgesehen – genehmigt werden in der Praxis nur kommerzielle Anfragen über ein in Belize ansässiges Unternehmen, für Filmaufnahmen zusätzlich mit Zustimmung der Film Commission.", "Rund um Flugplätze wie Ladyville, Placencia oder Caye Caulker gilt ein Sperrradius von mehreren Kilometern, geflogen werden darf ohnehin nur tagsüber und in Sichtweite."] },
  { code: "BM", name: "Bermuda", maxAltitude: 120, registrationRequired: false, insuranceRequired: false, sourceUrl: "https://bcaa.bm/drone-operations", rules: ["Für Bermuda sind auf der offiziellen Seite der Luftfahrtbehörde BCAA weder eine feste Gewichtsgrenze für eine Registrierungspflicht noch eine Versicherungspflicht dokumentiert – im Zweifel lohnt sich eine direkte Nachfrage bei der BCAA vor dem Flug.", "Klar geregelt sind dagegen Mindestabstände: 50 Meter zu Personen, Fahrzeugen und Gebäuden, und Drohnenflüge über bewohnten Gebieten (Straßen, Ortschaften, Städten) sind grundsätzlich verboten.", "Für Flüge über Regierungsgelände brauchst du zusätzlich eine gesonderte Erlaubnis des Parks-Departments.", "Die maximale Flughöhe liegt bei 400 Fuß (rund 120 Metern) über Grund, im durchgehenden Sichtflug."] },
  { code: "BT", name: "Bhutan", maxAltitude: null, registrationRequired: true, insuranceRequired: false, sourceUrl: "https://bcaa.gov.bt/faq-2/", rules: ["Privater und touristischer Drohnenbetrieb ist in Bhutan de facto nicht erlaubt: Laut der offiziellen FAQ der Bhutan Civil Aviation Authority (BCAA) dürfen ausschließlich staatliche Organisationen für staatliche Zwecke Drohnen betreiben, Privatpersonen und Unternehmen ist der Besitz oder Betrieb von Drohnen untersagt.", "Die Einfuhr einer Drohne ohne vorherige Genehmigung der BCAA ist nicht gestattet; wird ein Fluggerät bei der Einreise entdeckt, wird es laut offizieller Angabe am Einreisepunkt beschlagnahmt, sodass Reisende praktisch mit dem Verlust ihrer Drohne am Flughafen rechnen müssen.", "Ein Genehmigungsverfahren für den Drohnenbetrieb existiert zwar formal, richtet sich jedoch ausschließlich an Regierungsstellen; ausländische Pilotenlizenzen oder Schulungsnachweise können dabei allenfalls als Qualifikationsnachweis für staatliche Auftraggeber dienen, begründen aber keinen Anspruch auf eine private Betriebserlaubnis.", "Belastbare, offiziell bestätigte Angaben zu Flughöhen-, Gewichts- oder Versicherungsvorgaben für den ohnehin nicht zugänglichen privaten Betrieb liegen nicht vor; in Sekundärquellen kursierende Zahlen wie eine maximale Flughöhe von rund 90 Metern beziehen sich, soweit nachvollziehbar, auf die für Behörden geltenden technischen Vorgaben und sollten nicht als allgemein gültige Werte für Touristen missverstanden werden.", "Bei Verstößen drohen laut BCAA-Regelwerk Sanktionen nach Abschnitt 4.12.21 der Vorschriften; in der Reisepraxis werden im Zusammenhang mit unerlaubten Drohnen verhängte Bußgelder Berichten zufolge oft dem örtlichen Reiseveranstalter angelastet, der für seine Gäste haftet, statt direkt gegenüber dem Touristen verhängt zu werden.", "Da eine legale private Nutzung praktisch ausgeschlossen ist, empfiehlt es sich, eine Drohne gar nicht erst nach Bhutan einzuführen beziehungsweise vorab schriftlich bei der BCAA zu klären, ob im Einzelfall eine Ausnahmegenehmigung im Rahmen eines behördlich beauftragten Projekts realistisch ist."] },
  { code: "BO", name: "Bolivien", maxAltitude: 120, registrationRequired: true, insuranceRequired: false, sourceUrl: "https://www.dgac.gob.bo/drones/", rules: ["In Bolivien müssen Drohnen zwischen 200 Gramm und 35 Kilogramm bei der Luftfahrtbehörde DGAC registriert werden (Mindestalter für den Halter: 18 Jahre); Geräte unter 200 Gramm sowie reine Modellflugzeuge sind ausgenommen, die Registriernummer muss sichtbar am Gerät angebracht sein.", "Rein private Freizeitflüge mit Drohnen unter 6 Kilogramm sind innerhalb der allgemeinen Vorgaben ohne gesonderte DGAC-Genehmigung möglich; für gewerbliche Luftarbeiten (Filmaufnahmen, Vermessung, Transport) sowie für Nachtflüge ist dagegen mindestens 10 Werktage vorher ein formeller Antrag bei der DGAC nötig.", "Verboten bzw. genehmigungspflichtig sind Flüge in der Nähe von Flughäfen, Regierungseinrichtungen und militärischen Sperrzonen sowie aus fahrenden Fahrzeugen oder unter Einfluss von Alkohol und Drogen; Vorfälle müssen der DGAC innerhalb von 72 Stunden gemeldet werden.", "Zu einer landesweiten Versicherungspflicht macht die DGAC auf ihrer offiziellen Seite keine öffentlich zugänglichen Angaben – im Zweifel lohnt sich vor dem Flug eine direkte Nachfrage bei der Behörde.", "Die maximale Flughöhe liegt bei 400 Fuß (rund 120 Metern) über Grund, ausschließlich im durchgehenden Sichtflug (VLOS)."] },
  { code: "BA", name: "Bosnien-Herzegowina", maxAltitude: 30, registrationRequired: true, insuranceRequired: true, sourceUrl: "https://www.bhdca.gov.ba/index.php/en/drone", rules: ["In Bosnien und Herzegowina musst du deine Drohne ab rund 250 Gramm Startgewicht bei der Luftfahrtbehörde BHDCA registrieren.", "Eine Haftpflichtversicherung für Schäden am Boden ist gesetzlich vorgeschrieben.", "Auffällig streng: Die maximale Flughöhe liegt bei nur 30 Metern über Grund – deutlich niedriger als der EU-Standard von 120 Metern. Zusätzlich gilt ein Mindestabstand von 300 Metern zur Staatsgrenze (dort ist vorab die Zustimmung der Grenzpolizei nötig) sowie 500 Metern zu Industrieanlagen, Botschaften und Regierungsgebäuden."] },
  { code: "BW", name: "Botsuana", maxAltitude: 122, registrationRequired: true, insuranceRequired: false, sourceUrl: "https://drone-laws.com/drone-laws-in-botswana/", rules: ["In Botsuana muss jede Drohne bei der Luftfahrtbehörde CAAB registriert werden – auch als Tourist, über eine temporäre Registrierung. Eine Versicherung ist gesetzlich nicht vorgeschrieben, wird aber empfohlen.", "Die maximale Flughöhe liegt bei 122 Metern (400 Fuß), der horizontale Abstand zum Piloten darf 500 Meter nicht überschreiten.", "Sperrzonen gelten in 3 Kilometern um unkontrollierte Flugplätze; da Botsuana über 100 Nationalparks und Wildreservate zählt (u. a. Chobe, Okavango-Delta), betrifft das einen großen Teil der touristisch interessanten Gebiete.", "Der Registrierungsantrag verlangt Reisepasskopie, Führungszeugnis und ein Sicherheits-Interview in Gaborone oder Maun, geplant mindestens 7 Tage vor dem gewünschten Flug.", "Bei Verstößen in Schutzgebieten drohen Bußgelder im niedrigen dreistelligen Euro-Bereich.", "Insgesamt bürokratisch für einen Kurzurlaub, aber mit etwas Vorlauf ein tatsächlich gangbarer legaler Weg."] },
  { code: "BR", name: "Brasilien", maxAltitude: 120, registrationRequired: true, insuranceRequired: true, sourceUrl: "https://www.gov.br/anac/pt-br/sistemas/sisant", rules: ["Drohnen ab 250 Gramm müssen bei der Luftfahrtbehörde ANAC über das Online-System SISANT registriert werden; die dabei vergebene Kennung ist gut sichtbar am Fluggerät anzubringen, und die Registrierung muss alle 24 Monate erneuert werden.", "Zusätzlich zur Registrierung bei ANAC ist für den eigentlichen Flug eine Freigabe der Flugsicherungsbehörde DECEA über das System SARPAS erforderlich; praktisch jeder Flug braucht damit vorab eine gesonderte Luftraumfreigabe.", "DECEA unterteilt den Luftraum in rote Zonen wie Militäranlagen und Gefängnisse, die absolut gesperrt sind, gelbe Zonen mit Genehmigungspflicht etwa in Flughafennähe sowie grüne Zonen ohne dauerhafte Einschränkung, für die aber ebenfalls eine Freigabe nötig ist.", "Seit Mitte 2026 ersetzt das neue Regelwerk RBAC 100 die bisherige Regelung RBAC-E Nr. 94 und führt statt gewichtsbasierter Klassen ein risikobasiertes System mit den Kategorien offen, spezifisch und zertifiziert ein; für die meisten Betriebsarten unter diesem Regelwerk ist zudem eine Haftpflichtversicherung für Schäden gegenüber Dritten vorgeschrieben.", "Für Schutzgebiete, das Amazonasgebiet oder indigene Territorien fanden sich keine eindeutig dokumentierten Sonderregeln für Drohnen; da solche Flächen in Brasilien häufig einen eigenen Schutzstatus genießen, sollte vor Ort bei der zuständigen Behörde, etwa der Umweltbehörde ICMBio, gesondert nachgefragt werden."] },
  { code: "BN", name: "Brunei", maxAltitude: 60, registrationRequired: true, insuranceRequired: false, sourceUrl: "https://www.dca.gov.bn/Site%20Pages/Unmanned%20Aircraft%20Registration%20Guide.aspx", rules: ["Der Höchststand für Drohnenflüge liegt laut Department of Civil Aviation bei 200 Fuß, umgerechnet rund 60 Meter, über mittlerem Meeresspiegel, Flüge außerhalb der Sichtweite des Piloten sind grundsätzlich untersagt.", "Private Drohnen müssen mit dem Formular DCA Form 21 bei der Behörde registriert werden, wobei eine Farbkopie des Personalausweises oder Reisepasses sowie Fotos und die Seriennummer der Drohne einzureichen sind, ausgenommen von der Registrierungspflicht sind lediglich reine Spielzeugdrohnen.", "Touristen, die ihre Drohne mitführen, aber nicht fliegen wollen, müssen sie nicht anmelden, sobald sie tatsächlich fliegen wollen, gelten für sie dieselben Registrierungs- und Betriebsregeln wie für Einwohner, ein gesondertes vereinfachtes Verfahren für Kurzaufenthalte existiert nicht.", "Eine gesetzliche Versicherungspflicht besteht für den privaten Freizeitgebrauch nicht, wird von der Behörde aber empfohlen, auch für gewerbliche und behördliche Betreiber sind keine Versicherungsvorgaben dokumentiert.", "Um Flughäfen, Hubschrauberlandeplätze und Militärbasen ist ein Mindestabstand von 5 Kilometern einzuhalten, Flüge sind nur bei Tageslicht und guten Wetterbedingungen gestattet, über Menschenansammlungen oder öffentlichen Veranstaltungen ist das Fliegen verboten.", "Verstöße gegen die Vorschriften der Civil Aviation Order 2006 können mit Geldstrafen bis zu 50.000 Brunei-Dollar oder Freiheitsstrafen bis zu fünf Jahren, oder beidem, geahndet werden."] },
  { code: "BG", name: "Bulgarien", maxAltitude: 120, registrationRequired: true, insuranceRequired: false, sourceUrl: "https://drones.caa.bg", rules: ["In Bulgarien registrierst du dich als Drohnenbetreiber über das offizielle Portal der Zivilluftfahrtbehörde (drones.caa.bg) – Pflicht ab 250 Gramm Startgewicht oder bei jeder Drohne mit Kamera bzw. anderem Datenerfassungs-Sensor, unabhängig vom Gewicht.", "Registriert wird nur einmal, und zwar in dem EASA-Staat, in dem du deinen Wohnsitz hast – zum EASA-Raum gehören die EU-Länder plus Island, Liechtenstein, Norwegen und die Schweiz. Die Betreibernummer gilt dann im gesamten EASA-Raum: Wer bereits in einem anderen EASA-Land registriert ist, braucht in Bulgarien keine zweite Registrierung. Nur wer außerhalb des EASA-Raums wohnt, registriert sich in dem EASA-Staat, in dem er zuerst fliegt.", "Eine Haftpflichtversicherung ist in Bulgarien nach aktuellem Stand erst ab einem Startgewicht von 20 Kilogramm gesetzlich vorgeschrieben – die EU-Grundregel gilt hier ohne nationale Verschärfung.", "Flüge in Sperr- oder Beschränkungsgebieten müssen mindestens sieben Tage im Voraus bei der Zivilluftfahrtbehörde angemeldet werden. Die A1/A3-Prüfung läuft über die offizielle Plattform X-TESLA.", "In der offenen Kategorie gilt eine maximale Flughöhe von 120 Metern über Grund, wie EU-weit einheitlich geregelt."] },
  { code: "CL", name: "Chile", maxAltitude: 120, registrationRequired: true, insuranceRequired: false, sourceUrl: "https://www.dgac.gob.cl/operacion-de-drones/", rules: ["Ab 250 Gramm Startgewicht muss die Drohne vor dem ersten Flug im speziellen RPA-Register der DGAC eingetragen werden, mit Angaben zu Hersteller, Modell und Seriennummer.", "Die Flughöhe ist grundsätzlich auf 120 Meter über Grund in direkter Sichtweite begrenzt; für rein private Flüge mit sehr leichten Fluggeräten unter 750 Gramm gilt nach DAN 91 abweichend eine Grenze von 50 Metern über dem höchsten Hindernis der Umgebung.", "Verboten ist der Flug unter anderem über Militäranlagen, Gefängnissen und als strategisch eingestuften Einrichtungen sowie im Bereich von rund 2 Kilometern um Landebahnverlängerungen; aktuell gültige Sperrzonen sind im chilenischen Luftfahrthandbuch AIP und in laufenden NOTAMs veröffentlicht.", "Eine Haftpflichtversicherung verlangt die DGAC ausdrücklich für kommerzielle Einsätze sowie für Flüge über Menschenansammlungen oder bewohnten Gebieten; für einfache private Freizeitflüge abseits von Personen ist sie nach den verfügbaren Quellen nicht zwingend vorgeschrieben.", "In Nationalparks und anderen von der Forstbehörde CONAF verwalteten Schutzgebieten ist vorab eine gesonderte Genehmigung nötig - das betrifft auch touristisch beliebte Ziele wie den Nationalpark Torres del Paine."] },
  { code: "CN", name: "China", maxAltitude: 120, registrationRequired: true, insuranceRequired: false, sourceUrl: "https://www.caac.gov.cn/XXGK/XXGK/FLFG/202401/t20240115_222642.html", rules: ["Nach dem seit Januar 2024 geltenden Regelwerk zur Verwaltung unbemannter Luftfahrzeuge müssen alle zivilen Drohnen in China mit dem echten Namen des Eigentümers registriert werden; eine Gewichtsausnahme für kleine Freizeitdrohnen ist in der Vorschrift nicht vorgesehen.", "Die Registrierung läuft über die offizielle UOM-Plattform der Zivilluftfahrtbehörde CAAC und erfordert eine chinesische Mobilfunknummer für die SMS-Verifizierung; ausländische Touristen benötigen dafür in der Praxis häufig eine lokal erworbene SIM-Karte oder einen entsprechenden Dienstleister, eine reine Passnummer genügt meist nicht.", "Luftraum oberhalb von 120 Metern über Grund gilt landesweit grundsätzlich als kontrollierter Luftraum und erfordert eine gesonderte Freigabe, die genaue Umsetzung wird zusätzlich durch häufig wechselnde regionale und städtische Sonderregelungen überlagert.", "Seit August 2025 gilt das gesamte Verwaltungsgebiet Pekings offiziell als Flugbeschränkungszone, in der jeder Drohnenflug eine vorherige Genehmigung der Luftverkehrskontrolle voraussetzt; traditionell ähnlich streng oder faktisch vollständig gesperrt sind zudem sensible Grenzregionen wie Tibet und Teile Xinjiangs.", "Eine gesetzliche Versicherungspflicht besteht für den privaten Freizeitbereich nur bei Drohnen ab der sogenannten Small-Klasse, also ab 15 Kilogramm Leergewicht beziehungsweise 25 Kilogramm Startgewicht; die meisten handelsüblichen Foto- und Freizeitdrohnen liegen deutlich darunter und sind damit von der Pflicht ausgenommen.", "Verstöße gegen die Registrierungspflicht werden mit Bußgeldern bis 200 Yuan, in schweren Fällen bis 20.000 Yuan geahndet, unerlaubte Flüge im kontrollierten Luftraum können zusätzlich mit bis zu 10.000 Yuan sowie Beschlagnahmung des Fluggeräts bestraft werden."] },
  { code: "CR", name: "Costa Rica", maxAltitude: 120, registrationRequired: false, insuranceRequired: false, sourceUrl: "https://www.dgac.go.cr", rules: ["In Costa Rica ist für rein privates Freizeitfliegen innerhalb der allgemeinen Regeln keine Registrierung bei der Luftfahrtbehörde DGAC nötig – Pflicht ist sie nur für gewerbliche Betreiber und für Drohnen über 25 Kilogramm.", "Eine Versicherungspflicht besteht ebenfalls nur für den gewerblichen Betrieb.", "Wichtig für Reisende: In den zahlreichen Nationalparks und Schutzgebieten (etwa Manuel Antonio, Arenal, Corcovado) verlangt die Naturschutzbehörde SINAC nach übereinstimmenden Berichten zusätzlich zu den DGAC-Regeln eine eigene Genehmigung – da Costa Ricas bekannteste Fotomotive fast durchweg in solchen Gebieten liegen, lohnt sich eine Nachfrage bei SINAC oder am jeweiligen Parkeingang vor dem Flug.", "Die maximale Flughöhe liegt bei rund 120 Metern über Grund, mit Sicherheitsabstand zu Menschenansammlungen und Flughäfen."] },
  { code: "CD", name: "Demokratische Republik Kongo", maxAltitude: null, registrationRequired: false, insuranceRequired: false, sourceUrl: "https://www.congoquotidien.com/2025/07/09/drones-rdc-reglementation-filmer-legal/", rules: ["Wichtiger Hinweis: In der Demokratischen Republik Kongo herrscht im Osten des Landes (v. a. Nord-Kivu, Region Goma) seit Jahren ein anhaltender bewaffneter Konflikt. Für 2026 sind unter anderem GPS-Störungen rund um Goma und Drohnenangriffe auf Militär- und Flughafeninfrastruktur dokumentiert; mehrere Länder raten inzwischen ausdrücklich vom Überflug bestimmter Landesteile ab.", "Selbst im ruhigeren Westen des Landes (Kinshasa und Umgebung) ist ziviler Drohnenbetrieb formal an eine Genehmigung der Luftfahrtbehörde gebunden, die Bearbeitung dauert nach verfügbaren Quellen 15 bis 30 Tage und kostet umgerechnet 50 bis 500 US-Dollar – für kurze Reisen kaum praktikabel. Eine Haftpflichtversicherung gilt dort als Pflicht für alle Betreiber.", "Zu einer landesweit einheitlichen Flughöhengrenze liegen widersprüchliche Angaben vor (teils rund 91 Meter für die Freizeitkategorie genannt), eine gesichert offizielle Zahl war nicht auffindbar.", "Sperrzonen betreffen unter anderem 5 bis 10 Kilometer um Flughäfen und Militärbasen, Regierungsgebäude sowie Nationalparks ohne Sondererlaubnis.", "Angesichts der Sicherheitslage im Osten und des ohnehin hohen bürokratischen Aufwands selbst im Westen: Eine Drohne besser gar nicht erst in die Demokratische Republik Kongo mitnehmen."] },
  { code: "DE", name: "Deutschland", maxAltitude: 120, registrationRequired: true, insuranceRequired: true, sourceUrl: "https://uas-registration.lba-openuav.de/", rules: ["Wer in Deutschland wohnt und eine Drohne ab 250 Gramm Startgewicht betreibt, muss sich beim Luftfahrt-Bundesamt (LBA) registrieren – auch leichtere Modelle mit Kamera oder anderen Sensoren, die personenbezogene Daten erfassen können, fallen darunter. Bei der Registrierung erhältst du eine e-ID, die du sichtbar an jeder deiner Drohnen anbringen musst.", "Registriert wird nur einmal, und zwar in dem EASA-Staat, in dem du deinen Wohnsitz hast – zum EASA-Raum gehören die EU-Länder plus Island, Liechtenstein, Norwegen und die Schweiz. Die Betreibernummer gilt dann im gesamten EASA-Raum: Wer bereits in einem anderen EASA-Land registriert ist, braucht in Deutschland keine zweite Registrierung. Nur wer außerhalb des EASA-Raums wohnt, registriert sich in dem EASA-Staat, in dem er zuerst fliegt.", "Eine Halterhaftpflichtversicherung ist für den Betrieb jeder Drohne in Deutschland gesetzlich vorgeschrieben, unabhängig vom Gewicht – die Versicherungsdaten werden bereits bei der Registrierung hinterlegt.", "Für Drohnen der Klassen C1 bis C4 brauchst du mindestens den EU-Kompetenznachweis A1/A3 (Online-Prüfung). Willst du mit einer C2-Drohne näher an Personen heranfliegen (offene Unterkategorie A2), ist zusätzlich das EU-Fernpilotenzeugnis nötig.", "In der offenen Kategorie gilt eine maximale Flughöhe von 120 Metern über Grund – EU-weit einheitlich geregelt."] },
  { code: "DO", name: "Dominikanische Republik", maxAltitude: 121, registrationRequired: true, insuranceRequired: true, sourceUrl: "https://www.idac.gob.do/drone/", rules: ["In der Dominikanischen Republik musst du deine Drohne ab 250 Gramm bei der Luftfahrtbehörde IDAC über das Portal Vuela Seguro registrieren; Drohnen unter 250 Gramm sind ausgenommen.", "Ab 250 Gramm ist außerdem eine Haftpflichtversicherung gegen Schäden an Dritten vorgeschrieben.", "Wichtig für den Urlaub: Ohne vorherige schriftliche IDAC-Genehmigung wird deine Drohne am Flughafen (etwa in Punta Cana) häufig vom Zoll einbehalten, bis die Einfuhrabgaben geklärt sind. Die Genehmigung kann mehrere Wochen dauern – beantrage sie rechtzeitig vor der Reise, nicht erst kurz vorher.", "Die maximale Flughöhe liegt bei 400 Fuß (rund 121 Metern) über Grund, ausschließlich bei Tageslicht."] },
  { code: "DK", name: "Dänemark", maxAltitude: 120, registrationRequired: true, insuranceRequired: true, sourceUrl: "https://www.droneregler.dk", rules: ["In Dänemark registrierst du dich als Drohnenbetreiber über droneregler.dk bei der Luftfahrtbehörde Trafikstyrelsen – Pflicht ab 250 Gramm Startgewicht oder bei jeder Drohne mit Kamera bzw. anderem Sensor. Die Registrierung muss alle drei Jahre erneuert werden.", "Registriert wird nur einmal, und zwar in dem EASA-Staat, in dem du deinen Wohnsitz hast – zum EASA-Raum gehören die EU-Länder plus Island, Liechtenstein, Norwegen und die Schweiz. Die Betreibernummer gilt dann im gesamten EASA-Raum: Wer bereits in einem anderen EASA-Land registriert ist, braucht in Dänemark keine zweite Registrierung. Nur wer außerhalb des EASA-Raums wohnt, registriert sich in dem EASA-Staat, in dem er zuerst fliegt.", "Eine Haftpflichtversicherung ist in Dänemark für praktisch jede Drohne oberhalb der Spielzeug-Kategorie bzw. ab 250 Gramm vorgeschrieben – eine deutliche Verschärfung gegenüber der EU-Grundregel, die Versicherung erst ab 20 Kilogramm verlangt.", "Rund um Flugplätze gelten je nach Sichtflug- oder Instrumentenflugbetrieb Sperrzonen von 4 bis 8 Kilometern, außer du verfügst über den zusätzlichen A2-Kompetenznachweis.", "In der offenen Kategorie gilt eine maximale Flughöhe von 120 Metern über Grund, wie EU-weit einheitlich geregelt."] },
  { code: "EC", name: "Ecuador", maxAltitude: 120, registrationRequired: true, insuranceRequired: false, sourceUrl: "https://www.aviacioncivil.gob.ec/normativa-uas-drones/", rules: ["Seit dem 5. Mai 2025 müssen in Ecuador grundsätzlich alle Drohnen unabhängig vom Gewicht online bei der Luftfahrtbehörde DGAC registriert werden; nach der Anmeldung erhält das Gerät eine eindeutige Kennnummer mit QR-Code, die beim Fliegen sichtbar angebracht und deren Zulassungsnachweis mitgeführt werden muss.", "Das Reglement RDAC 101 unterscheidet zwei Kategorien: Die offene Kategorie für Freizeitflüge bis 4 Kilogramm Startgewicht (Mindestalter 14 Jahre) kommt ohne Betriebserlaubnis, Pilotenschein oder Versicherungsnachweis aus; für die spezifische Kategorie (kommerzielle bzw. professionelle Nutzung) sind dagegen ein Fernpilotenlehrgang, eine Betreiberzulassung (UOC) und eine Haftpflichtversicherung Pflicht.", "Wichtiger Sonderfall für Reisende: Im Nationalpark Galápagos ist privates bzw. touristisches Drohnenfliegen seit einer Verordnung vom März 2026 praktisch vollständig untersagt – erlaubt sind Flüge dort nur mit Sondergenehmigung für Wissenschaft, Such- und Rettungseinsätze, Naturschutz oder professionelle Foto-/Filmproduktionen, jeweils mit DGAC-Pilotenzertifikat, Parkranger-Begleitung und eigener Haftpflichtversicherung.", "Verboten sind außerdem Flüge über Gefängnissen, Regierungsgebäuden und anderen sicherheitsrelevanten Einrichtungen sowie Aufnahmen, die die Privatsphäre Dritter verletzen.", "Die maximale Flughöhe liegt bei 400 Fuß (rund 120 Metern) über Grund; im Galápagos-Nationalpark gilt für genehmigte Flüge eine eigene Obergrenze von 122 Metern."] },
  { code: "SV", name: "El Salvador", maxAltitude: 122, registrationRequired: true, insuranceRequired: true, sourceUrl: "https://www.aac.gob.sv", rules: ["In El Salvador musst du deine Drohne bei der Luftfahrtbehörde AAC registrieren (rund 20 US-Dollar je Gerät, weitere 20 US-Dollar für die Betreiberregistrierung) – auch als ausländischer Besucher, ein vereinfachtes Touristenverfahren gibt es nicht.", "Für gewerbliche Luftarbeiten ist eine Haftpflichtversicherung mit einer Mindestdeckung von 1 Million US-Dollar vorgeschrieben.", "Rund um internationale Flughäfen gilt ein Sperrradius von 6 Kilometern, um kleinere Flugplätze 2 Kilometer; Nachtflüge sind grundsätzlich untersagt.", "Die maximale Flughöhe liegt bei 400 Fuß (rund 122 Metern) über Grund, im durchgehenden Sichtflug."] },
  { code: "EE", name: "Estland", maxAltitude: 120, registrationRequired: true, insuranceRequired: false, sourceUrl: "https://transpordiamet.ee/en/drones", rules: ["In Estland registrierst du dich als Drohnenbetreiber über die Plattform LOIS2 (lois.transpordiamet.ee) bei der Behörde Transpordiamet – Pflicht ab 250 Gramm Startgewicht oder bei jeder Drohne mit Datenerfassungs-Sensor. Die Registrierung kostet 10 Euro und muss jährlich erneuert werden.", "Registriert wird nur einmal, und zwar in dem EASA-Staat, in dem du deinen Wohnsitz hast – zum EASA-Raum gehören die EU-Länder plus Island, Liechtenstein, Norwegen und die Schweiz. Die Betreibernummer gilt dann im gesamten EASA-Raum: Wer bereits in einem anderen EASA-Land registriert ist, braucht in Estland keine zweite Registrierung. Nur wer außerhalb des EASA-Raums wohnt, registriert sich in dem EASA-Staat, in dem er zuerst fliegt.", "Eine Haftpflichtversicherung ist in Estland erst ab einem Startgewicht von 20 Kilogramm gesetzlich vorgeschrieben – die EU-Grundregel gilt ohne nationale Verschärfung.", "Estland gilt als besonders drohnenfreundliches Land mit einer landesweiten Geodaten-App für die Flugvorbereitung, über die aktuelle Sperrzonen in Echtzeit abrufbar sind.", "In der offenen Kategorie gilt eine maximale Flughöhe von 120 Metern über Grund, wie EU-weit einheitlich geregelt."] },
  { code: "SZ", name: "Eswatini (Swasiland)", maxAltitude: 120, registrationRequired: true, insuranceRequired: true, sourceUrl: "https://www.eswacaa.co.sz/rpas-uav-drone-operation-requirements/", rules: ["In Eswatini brauchst du vor der Einreise eine Importlizenz und ein Genehmigungsschreiben der Luftfahrtbehörde ESWACAA – das gilt nach den verfügbaren Angaben sogar für kleine Freizeitdrohnen ab 1,5 Kilogramm, ohne Ausnahme für besonders leichte Sub-250-Gramm-Modelle.", "Ein Nachweis der Haftpflichtversicherung ist fester Bestandteil des Antrags.", "Die maximale Flughöhe liegt bei 120 Metern (400 Fuß), mit durchgehender Sichtverbindung zur Drohne.", "Sperrzonen gelten in 5 Kilometern um Flughäfen, um königliche Residenzen sowie Militär- und Regierungsgebäude; für Nationalparks und Wildreservate ist eine zusätzliche Genehmigung nötig, zu unbeteiligten Personen sind 50 Meter Abstand einzuhalten.", "Die Bearbeitung dauert in der Regel zwei bis vier Wochen; ohne vorherige Genehmigung droht Konfiszierung am Zoll.", "Mit ausreichend Vorlauf vor der Reise ist ein legaler Flug in Eswatini also machbar, spontan geht hier aber nichts."] },
  { code: "EU", name: "Europa", maxAltitude: 120, registrationRequired: true, insuranceRequired: false, sourceUrl: "https://www.easa.europa.eu/en/domains/civil-drones", rules: ["Dieser Eintrag beschreibt die gemeinsame EU-weite Drohnenverordnung (EU 2019/947 und 2019/945), die in allen 27 EU-Mitgliedstaaten sowie in Island, Liechtenstein und Norwegen einheitlich gilt – die Schweiz wendet sie seit 2023 über das Luftverkehrsabkommen mit der EU ebenfalls an. Für die Regeln eines konkreten Landes lohnt sich trotzdem der jeweilige Länder-Eintrag, da einzelne Staaten die EU-Vorgaben zusätzlich verschärfen dürfen – etwa bei der Versicherungspflicht, die deshalb hier bewusst nicht pauschal als Pflicht markiert ist.", "Flüge werden nach Risiko in drei Kategorien eingeteilt: Offen (geringes Risiko, für die allermeisten Freizeitflüge relevant), Speziell (mittleres Risiko, mit Genehmigung) und Zulassungspflichtig (hohes Risiko). Innerhalb der offenen Kategorie gibt es die Unterkategorien A1 (Überflug einzelner Personen kurzzeitig erlaubt), A2 (mindestens 30 Meter Abstand zu Unbeteiligten, reduzierbar im Low-Speed-Modus) und A3 (mindestens 150 Meter Abstand zu Wohn-, Gewerbe- und Erholungsgebieten).", "In der offenen Kategorie darf im unkontrollierten Luftraum bis 120 Meter über Grund geflogen werden, immer mit durchgehender Sichtverbindung zur Drohne (VLOS).", "Eine Registrierung als Betreiber ist EU-weit ab 250 Gramm Startgewicht nötig, unabhängig vom Gewicht aber auch schon dann, wenn die Drohne einen Sensor zur Erfassung personenbezogener Daten trägt (z. B. eine Kamera) und nicht als reines Spielzeug im Sinne der EU-Spielzeugrichtlinie gilt. Die Registrierung ist nur in einem einzigen Mitgliedstaat nötig (in der Regel dem Wohnsitzland) und gilt dann EU-weit, ebenso wie der EU-Kompetenznachweis.", "Für ältere, nicht klassifizierte (\"Legacy\") Drohnen ohne C-Kennzeichnung wurde die Übergangsregelung inzwischen verschärft: Nur noch Modelle unter 250 Gramm dürfen weiterhin in der einfacheren Unterkategorie A1 geflogen werden, alle anderen unklassifizierten Legacy-Drohnen sind auf die deutlich abstandsintensivere Unterkategorie A3 beschränkt.", "Kurz gesagt: Die EU-Regeln geben den gemeinsamen Rahmen vor (Registrierung, Höhenlimit, Kompetenznachweis), aber Details wie Versicherungspflicht, genaue Sperrzonen oder zusätzliche nationale Auflagen unterscheiden sich von Land zu Land – dafür lohnt sich der Blick in den jeweiligen Länder-Eintrag in diesem Regelwerk."] },
  { code: "FJ", name: "Fidschi", maxAltitude: 61, registrationRequired: true, insuranceRequired: false, sourceUrl: "https://www.caaf.org.fj/drones/", rules: ["In Fidschi muss jede Drohne unabhängig vom Gewicht bei der Luftfahrtbehörde CAAF registriert werden, für Freizeitpiloten über ein Online-Formular. Eine Versicherung ist für Hobbynutzer nicht vorgeschrieben, für kommerzielle Betreiber dagegen schon.", "Auffällig streng: Die maximale Flughöhe liegt bei nur 61 Metern (200 Fuß) – deutlich niedriger als der sonst verbreitete Standard von 120 Metern.", "Sperrzonen gelten in 3 Kilometern um nationale und 5 Kilometern um internationale Flughäfen, dazu um Polizei- und Militärstationen, Gefängnisse, Regierungsgebäude, Nationalparks und öffentliche Versammlungen. Über Resorts und Privatgrundstücken brauchst du zusätzlich die Zustimmung des Managements.", "Wichtig für die Reiseplanung: Die Registrierung muss vorab online bei der CAAF beantragt werden – ein Flug direkt nach Ankunft ohne Vorbereitung ist nicht vorgesehen, auch wenn die Bearbeitung meist innerhalb weniger Tage erfolgt.", "Zu konkreten Bußgeldbeträgen bei Verstößen liegen keine offiziell bestätigten Zahlen vor. Insgesamt wirkt die Regelung im Vergleich zu Australien oder Neuseeland weniger ausgereift und weniger einheitlich kommuniziert – im Zweifel direkt bei der CAAF nachfragen."] },
  { code: "FI", name: "Finnland", maxAltitude: 120, registrationRequired: true, insuranceRequired: false, sourceUrl: "https://www.traficom.fi/en/unmanned-aviation/registration-and-theoretical-examination", rules: ["In Finnland registrierst du dich als Drohnenbetreiber über den Online-Dienst Dronepalvelu von Traficom – Pflicht ab 250 Gramm Startgewicht oder bei jeder Drohne mit Kamera bzw. anderem Sensor. Deine Betreiberkennung muss sichtbar an der Drohne angebracht werden.", "Registriert wird nur einmal, und zwar in dem EASA-Staat, in dem du deinen Wohnsitz hast – zum EASA-Raum gehören die EU-Länder plus Island, Liechtenstein, Norwegen und die Schweiz. Die Betreibernummer gilt dann im gesamten EASA-Raum: Wer bereits in einem anderen EASA-Land registriert ist, braucht in Finnland keine zweite Registrierung. Nur wer außerhalb des EASA-Raums wohnt, registriert sich in dem EASA-Staat, in dem er zuerst fliegt.", "Eine Haftpflichtversicherung ist in Finnland erst ab einem Startgewicht von 20 Kilogramm gesetzlich vorgeschrieben; für leichtere Drohnen in der offenen Kategorie wird sie empfohlen, ist aber keine Pflicht.", "Für die Flugplanung liefert das Portal droneinfo.fi eine offizielle Übersicht über Sperrzonen und aktuelle Vorschriften.", "In der offenen Kategorie gilt eine maximale Flughöhe von 120 Metern über Grund, wie EU-weit einheitlich geregelt."] },
  { code: "FR", name: "Frankreich", maxAltitude: 120, registrationRequired: true, insuranceRequired: false, sourceUrl: "https://www.ecologie.gouv.fr/politiques-publiques/exploitation-drones-categorie-ouverte", rules: ["Wer in Frankreich wohnt, muss sich als Drohnenbetreiber über das Portal AlphaTango bei der Luftfahrtbehörde DGAC registrieren – Pflicht ab 250 Gramm Startgewicht oder bei jeder Drohne mit einem Sensor, der personenbezogene Daten erfassen kann.", "Registriert wird nur einmal, und zwar in dem EASA-Staat, in dem du deinen Wohnsitz hast – zum EASA-Raum gehören die EU-Länder plus Island, Liechtenstein, Norwegen und die Schweiz. Die Betreibernummer gilt dann im gesamten EASA-Raum: Wer bereits in einem anderen EASA-Land registriert ist, braucht in Frankreich keine zweite Registrierung. Nur wer außerhalb des EASA-Raums wohnt, registriert sich in dem EASA-Staat, in dem er zuerst fliegt.", "Eine Haftpflichtversicherung ist in Frankreich für die offene Kategorie nicht gesetzlich vorgeschrieben; die DGAC empfiehlt aber ausdrücklich, vorab zu prüfen, ob die eigene Privathaftpflicht auch Drohnenschäden abdeckt.", "Nachtflüge sind in der offenen Kategorie grundsätzlich untersagt, außer mit einer vorab beantragten Ausnahmegenehmigung der Präfektur (mindestens 30 Tage Vorlauf). Für die Flugplanung liefert Géoportail die offizielle französische Geozonen-Karte.", "In der offenen Kategorie gilt eine maximale Flughöhe von 120 Metern über Grund, wie in der gesamten EU."] },
  { code: "GE", name: "Georgien", maxAltitude: 120, registrationRequired: true, insuranceRequired: false, sourceUrl: "https://uas.gov.ge/EN", rules: ["In Georgien registrierst du dich als Drohnenbetreiber über das Portal uas.gov.ge bei der Zivilluftfahrtbehörde GCAA – Pflicht ab 250 Gramm Startgewicht, kostenlos.", "Eine gesetzliche Versicherungspflicht ist für Georgien nicht dokumentiert – dennoch ist eine Haftpflichtversicherung empfehlenswert.", "Georgien orientiert sich stark am EU-Modell: Es gibt die gleichen Unterkategorien A1, A2 und A3 sowie einen kostenlosen Online-Kompetenznachweis mit fünf Jahren Gültigkeit.", "In der offenen Kategorie gilt eine maximale Flughöhe von 120 Metern über Grund."] },
  { code: "GH", name: "Ghana", maxAltitude: 122, registrationRequired: true, insuranceRequired: false, sourceUrl: "https://www.gcaa.com.gh/web/wp-content/uploads/2023/RPAS%20AOC/AC%2028-001%20-%20Advisory%20Pamphlet.pdf", rules: ["In Ghana muss jede Drohne bei der Luftfahrtbehörde GCAA registriert werden – persönlich vor Ort am Kotoka-Flughafen. Die Gewichtsklassen reichen von \"Small\" (bis 1,5 Kilogramm) über \"Light\" (1,5 bis 7 Kilogramm) bis \"Large\" (über 7 Kilogramm).", "Eine Versicherung ist laut offiziellem Regelwerk für private Freizeitnutzung nicht ausdrücklich erwähnt, für kommerzielle Flüge dagegen üblich.", "Die maximale Flughöhe liegt bei 122 Metern (400 Fuß). Vor jedem Betrieb ist zudem eine Flugerlaubnis nötig, die jährlich erneuert werden muss.", "Sperrzonen gelten in 5 bis 10 Kilometern um Flughäfen (je nach Anflugverfahren), über Menschenmengen, Stränden und Privatgrundstücken ohne Erlaubnis; Nachtflüge brauchen eine Sondergenehmigung. Seit 2025 ist zusätzlich eine schriftliche Einfuhr-Deklaration mindestens 5 Werktage vor der Einreise vorgeschrieben, für historische Stätten wie die alten Forts kann eine zusätzliche Sicherheitsfreigabe nötig sein.", "Da die Registrierung nur persönlich vor Ort möglich ist und einige Zeit in Anspruch nimmt, ist Ghana für sehr kurze Aufenthalte eher unpraktisch, für längere Reisen mit etwas Vorlauf aber machbar."] },
  { code: "GD", name: "Grenada", maxAltitude: null, registrationRequired: false, insuranceRequired: false, sourceUrl: "https://eccaa.aero/", rules: ["Für Grenada ist über die zuständige regionale Behörde ECCAA kein eigenes, öffentlich dokumentiertes Drohnen-Regelwerk auffindbar – weder zu Registrierung noch zu Versicherung oder Flughöhen-Grenzen.", "Bevor du in Grenada fliegst, lohnt sich deshalb eine direkte Nachfrage bei der ECCAA oder den örtlichen Behörden vor Ort, um aktuelle Vorgaben zu erfahren."] },
  { code: "GR", name: "Griechenland", maxAltitude: 120, registrationRequired: true, insuranceRequired: false, sourceUrl: "https://hcaa.gov.gr/en/geniki-aeroporia-smiea", rules: ["In Griechenland registrierst du dich als Drohnenbetreiber über das Portal uas.hcaa.gov.gr bei der Luftfahrtbehörde HCAA – Pflicht ab 250 Gramm Startgewicht oder bei jeder Drohne mit einem Sensor, der personenbezogene Daten erfassen kann.", "Registriert wird nur einmal, und zwar in dem EASA-Staat, in dem du deinen Wohnsitz hast – zum EASA-Raum gehören die EU-Länder plus Island, Liechtenstein, Norwegen und die Schweiz. Die Betreibernummer gilt dann im gesamten EASA-Raum: Wer bereits in einem anderen EASA-Land registriert ist, braucht in Griechenland keine zweite Registrierung. Nur wer außerhalb des EASA-Raums wohnt, registriert sich in dem EASA-Staat, in dem er zuerst fliegt.", "Eine Haftpflichtversicherung ist in Griechenland erst ab einem Startgewicht von 20 Kilogramm gesetzlich vorgeschrieben – die EU-Grundregel gilt ohne bestätigte nationale Verschärfung.", "Flüge über oder in der Nähe von archäologischen Stätten benötigen eine vorherige Genehmigung der HCAA, meist mit mindestens fünf Werktagen Vorlauf – die kostenlose App Drone Aware Greece zeigt diese und weitere Sperrzonen in Echtzeit an.", "In der offenen Kategorie gilt eine maximale Flughöhe von 120 Metern über Grund, wie EU-weit einheitlich geregelt."] },
  { code: "GL", name: "Grönland", maxAltitude: 100, registrationRequired: true, insuranceRequired: true, sourceUrl: "https://www.en.droneregler.dk/drone-flying-abroad/drone-flying-in-greenland", rules: ["Grönland ist ein autonomes dänisches Überseegebiet und gehört nicht zum EU-/EASA-Luftraum – die europäische Drohnenverordnung gilt dort ausdrücklich nicht, ebenso wenig wie EU-Kompetenznachweise (A1/A3, A2). Stattdessen gilt ein eigenes grönländisch-dänisches Regelwerk (u. a. BL 9-4), zuständig ist die dänische Luftfahrtbehörde Trafikstyrelsen.", "Die maximale Flughöhe liegt bei nur 100 Metern über Grund – niedriger als der EU-Standard von 120 Metern. Höhere Flüge sind nur mit einer gesonderten Ausnahmegenehmigung nach vorheriger Risikobewertung möglich.", "Für Drohnen zwischen 7 und 25 Kilogramm sowie für jetgetriebene Drohnen ist eine Haftpflichtversicherung gesetzlich vorgeschrieben; für kleinere Freizeitdrohnen unter 7 Kilogramm ist die Quellenlage zu Registrierung und Versicherung nicht eindeutig – im Zweifel vorab direkt bei der Trafikstyrelsen nachfragen.", "Sperrzonen: 5 Kilometer Abstand zu zivilen Flugplätzen, 8 Kilometer zu militärischen Luftwaffenstützpunkten, 150 Meter zu bebauten Gebieten und größeren öffentlichen Straßen; über dicht besiedelten Orten und Siedlungen ist der Überflug generell nicht erlaubt.", "Mehrere Naturschutzgebiete sind komplett drohnenfrei, darunter der Nationalpark Grönland, die Melville-Bucht und das Gebiet Angujaartorfiup Nunaa südwestlich von Kangerlussuaq. Zusätzlich ist es ausdrücklich verboten, Eisbären mit einer Drohne zu filmen oder zu verfolgen.", "Bei Verstößen setzt die grönländische Polizei vor Ort Bußgelder zwischen umgerechnet rund 270 und 800 Euro durch, dazu kann die Drohne beschlagnahmt werden.", "Für Touristen mit einer normalen Freizeitdrohne unter 7 Kilogramm ist ein Flug außerhalb der Schutzgebiete und Siedlungen grundsätzlich möglich, für alles, was über die Standardregeln hinausgeht (Städte, mehr Höhe, schwerere Drohnen), ist eine vorherige Ausnahmegenehmigung der Trafikstyrelsen nötig."] },
  { code: "GT", name: "Guatemala", maxAltitude: 120, registrationRequired: true, insuranceRequired: true, sourceUrl: "https://www.dgac.gob.gt", rules: ["In Guatemala musst du deine Drohne ab 250 Gramm bei der Luftfahrtbehörde DGAC registrieren – das gilt auch für Touristen.", "Für die Registrierung musst du eine gültige Haftpflichtversicherung nachweisen.", "Rund um Flughäfen gilt ein Sperrradius von 6 Kilometern, Flüge über Menschenansammlungen ab 100 Personen sind verboten – wichtig etwa während der zahlreichen Prozessionen und Feste wie der Semana Santa. Für Foto- und Videoaufnahmen brauchen auch Touristen eine gesonderte Genehmigung (Formular DVSO-805).", "Ohne besondere Genehmigung liegt die maximale Flughöhe bei rund 120 Metern über Grund."] },
  { code: "GY", name: "Guyana", maxAltitude: 150, registrationRequired: true, insuranceRequired: false, sourceUrl: "https://www.gcaa-gy.org/drones.html", rules: ["In Guyana ist die Guyana Civil Aviation Authority (GCAA) für Zulassung und Kontrolle von Drohnen zuständig; wer ein Fluggerät betreiben möchte, muss grundsätzlich einen formellen Antrag samt Informationsblatt und Identitätsnachweis per E-Mail einreichen.", "Freizeitdrohnen bis 7 Kilogramm ohne Telemetrieübertragung sind von der Genehmigungspflicht ausgenommen, solange keine kommerzielle Nutzung vorliegt; schwerere Modelle oder Geräte mit Telemetriefunktion benötigen dagegen in jedem Fall eine Zulassung.", "Die maximale Flughöhe liegt bei 150 Metern über Grund; zusätzlich gilt ein horizontaler Betriebsradius von 500 Metern um die Position des Piloten sowie durchgehender Sichtkontakt zum Fluggerät.", "Mindestabstände sind unter anderem zu Menschenansammlungen (150 Meter), fremden Fahrzeugen und Gebäuden (100 Meter) sowie einzelnen Personen (50 Meter) einzuhalten; Nachtflüge und Flüge bei schlechter Sicht sind nicht erlaubt.", "Eine Haftpflichtversicherung ist offiziell nur für kommerzielle Einsätze vorgeschrieben; da die Sicherheitsprüfung laut GCAA mindestens 29 Tage dauern kann, sollten Besucher einen Antrag frühzeitig vor der Reise stellen – belastbare, aktuelle Informationen speziell zu kurzen touristischen Aufenthalten sind insgesamt aber vergleichsweise dünn dokumentiert."] },
  { code: "HK", name: "Hongkong", maxAltitude: 91, registrationRequired: true, insuranceRequired: false, sourceUrl: "https://www.cad.gov.hk/english/sua_new.html", rules: ["Das Small Unmanned Aircraft Order (Cap. 448G) unterteilt Drohnen nach Gewicht in die Kategorien A1 (bis 250 Gramm), A2 (250 Gramm bis 7 Kilogramm) sowie B und C (über 7 bis 150 Kilogramm), wobei die Höhenbegrenzung je Kategorie unterschiedlich ausfällt: Kategorie A1 darf bis 30 Meter über Grund fliegen, die für die meisten handelsüblichen Kameradrohnen relevante Kategorie A2 bis 91 Meter.", "Drohnen unter 250 Gramm benötigen weder eine Geräte- noch eine Pilotenregistrierung, während für alle Geräte zwischen 250 Gramm und 7 Kilogramm sowohl eine Drohnen- als auch eine Fernpilotenregistrierung über das elektronische Portal eSUA der Civil Aviation Department verpflichtend ist.", "Ausländische Touristen können sich mit ihrer Passnummer statt einer Hongkonger ID-Karte im eSUA-Portal registrieren, eine lokale Adresse ist dafür nicht erforderlich, wohl aber Angaben zum Drohnenmodell und zum geplanten Einsatzort.", "Eine gesetzliche Versicherungspflicht besteht für die reguläre Kategorie A2 bislang nicht, ein Starttermin dafür wurde von der Behörde noch nicht bekanntgegeben; nur für genehmigungspflichtige Advanced Operations ist eine Haftpflichtversicherung mit einer Mindestdeckung von 10 Millionen Hongkong-Dollar, bei schwereren Geräten bis zu 20 Millionen, vorgeschrieben.", "Rund um den Flughafen Hong Kong International Airport gilt ein Sperrradius von etwa 5 Kilometern, weitere Verbotszonen betreffen unter anderem Regierungsgebäude und Bereiche über Menschenansammlungen, zudem ist das Fliegen nur bei Tageslicht, also eine halbe Stunde vor Sonnenaufgang bis eine halbe Stunde nach Sonnenuntergang, erlaubt.", "Verstöße können je nach Schwere mit Geldstrafen geahndet werden, wobei Sekundärquellen unterschiedliche Rahmen zwischen rund 5.000 und 50.000 Hongkong-Dollar nennen; eine offizielle, vollständige Bußgeldtabelle war auf der Website der Civil Aviation Department zum Recherchezeitpunkt nicht auffindbar."] },
  { code: "IN", name: "Indien", maxAltitude: 120, registrationRequired: true, insuranceRequired: false, sourceUrl: "https://digitalsky.aai.aero/", rules: ["Drohnen werden nach Gewicht in fünf Kategorien eingeteilt (Nano bis unter 250 Gramm, Micro bis 2 Kilogramm, Small bis 25 Kilogramm, Medium bis 150 Kilogramm und Large darüber), wobei nur Nano-Drohnen bei rein privater, nicht kommerzieller Nutzung von der Registrierungspflicht ausgenommen sind.", "Alle Drohnen ab der Kategorie Micro benötigen eine Unique Identification Number (UIN), die über die staatliche Plattform Digital Sky beantragt wird; für kommerzielle Nutzung und größere Kategorien ist zusätzlich eine Unmanned Aircraft Operator Permit (UAOP) sowie ein Remote Pilot Certificate erforderlich.", "Die maximale Flughöhe liegt im als Grün eingestuften Luftraum bei 120 Metern (400 Fuß) über Grund ohne gesonderte Genehmigung; in Gelb markierten Zonen ist vorab eine Freigabe über Digital Sky einzuholen, Rot markierte Gebiete rund um Flughäfen, Militäranlagen und die Landesgrenzen sind vollständig gesperrt.", "Eine Haftpflichtversicherung ist nach den Drone Rules 2021 ausschließlich für den kommerziellen Betrieb zwingend vorgeschrieben; für rein private beziehungsweise touristische Freizeitnutzung besteht keine gesetzliche Versicherungspflicht, auch wenn manche Quellen dies pauschal behaupten.", "Ausländische Touristen können grundsätzlich mit eigener Drohne einreisen, sollten die Registrierung über Digital Sky jedoch bereits Wochen vor der Reise vorbereiten; problematisch ist, dass insbesondere chinesische Fabrikate wiederholt beim Zoll beschlagnahmt wurden, weshalb Kauf oder Miete vor Ort teils empfohlen wird.", "Verstöße wie Flüge ohne Registrierung oder in Sperrzonen werden mit Bußgeldern im Bereich von umgerechnet rund 250 bis über 5.000 Euro geahndet, bei schweren oder wiederholten Verstößen drohen Beschlagnahmung der Drohne und strafrechtliche Verfahren."] },
  { code: "ID", name: "Indonesien", maxAltitude: 150, registrationRequired: true, insuranceRequired: false, sourceUrl: "https://peraturan.go.id/id/permenhub-no-pm37-tahun-2020", rules: ["Für den Standardbetrieb liegt die zulässige maximale Flughöhe laut der Verordnung PM 37/2020 des Verkehrsministeriums bei 150 Metern über Grund, wobei einzelne Quellen abweichend 120 Meter nennen und der Wert vor Reiseantritt über eine aktuelle Quelle geprüft werden sollte.", "Drohnen bis 250 Gramm gelten als besonders leicht mit gelockerten Anforderungen, für Fluggeräte bis 7 Kilogramm Startgewicht greifen die regulären Vorschriften, und schwerere Systeme benötigen zusätzliche Genehmigungen.", "Für touristische Nutzung existiert kein landesweit einfaches Registrierungsverfahren: Die offizielle Fernpilotenzertifizierung setzt indonesische Staatsangehörigkeit voraus, sodass ausländische Piloten sie faktisch nicht erlangen können; in touristisch geprägten Regionen wie Bali verlangt das lokale Portal SIPUDI/SIPP-TA dennoch eine Registrierung von Drohne und Pilot samt Reisepassdaten mit mehreren Werktagen Bearbeitungszeit.", "Eine landesweite Versicherungspflicht für private und touristische Flüge ist nicht eindeutig belegt, für die lokale Registrierung in Bali wird jedoch häufig ein Nachweis einer Haftpflichtversicherung verlangt, weshalb der Abschluss einer Drohnenhaftpflicht dringend empfohlen wird.", "Rund um Flughäfen gilt ein Sperrradius von etwa 15 Kilometern, der in Bali praktisch den gesamten touristisch genutzten Süden der Insel einschließt, zusätzlich bestehen Schutzzonen um Tempelanlagen sowie im Komodo-Nationalpark, wo ein separates, kostenpflichtiges Genehmigungsverfahren mit mehrtägiger Vorlaufzeit erforderlich ist.", "Verstöße können mit erheblichen Bußgeldern und im Extremfall mit Freiheitsstrafen bis zu drei bis fünf Jahren geahndet werden, zudem drohen die Konfiszierung des Fluggeräts und im Einzelfall die Ausweisung."] },
  { code: "IR", name: "Iran", maxAltitude: null, registrationRequired: false, insuranceRequired: false, sourceUrl: "https://caravanistan.com/planning/drones/", rules: ["Wichtiger Hinweis: Der Iran gehört zu den Ländern, in denen private Drohnennutzung faktisch nicht empfehlenswert ist. Mehrere übereinstimmende Quellen nennen für Drohnen unter 300 Gramm keine Genehmigungspflicht, für alles darüber eine Genehmigung, die von mehreren Behörden gemeinsam erteilt werden muss – belastbare, öffentlich zugängliche Angaben zu Flughöhe oder Versicherungspflicht gibt es darüber hinaus nicht.", "Sperrzonen bestehen unter anderem über der gesamten Hauptstadt Teheran, um Militärbasen, Kernkraftwerke, Flughäfen und Grenzgebiete.", "Am Zoll wurden Fälle dokumentiert, in denen Drohnen versiegelt oder einbehalten wurden; die Ausfuhr-Dokumentation wird nicht immer anerkannt.", "Die Konsequenzen bei Verstößen können gravierend sein: Dokumentiert ist der Fall eines französischen Touristen, der wegen eines Drohnenflugs nahe der Grenze zu Turkmenistan unter Spionageverdacht zu acht Jahren Haft verurteilt wurde. GPS-fähige Geräte und Kameras werden generell mit Argwohn betrachtet.", "Angesichts dieser Risiken und einer politisch angespannten Lage in der Region wird von der Mitnahme einer Drohne in den Iran grundsätzlich abgeraten."] },
  { code: "IE", name: "Irland", maxAltitude: 120, registrationRequired: true, insuranceRequired: true, sourceUrl: "https://www.iaa.ie/general-aviation/drones", rules: ["In Irland registrierst du dich als Drohnenbetreiber über das Portal MYSRS der Luftfahrtbehörde IAA – Pflicht ab 250 Gramm Startgewicht oder bei jeder Drohne mit einem Sensor, der personenbezogene Daten erfassen kann. Mindestalter für die Registrierung: 16 Jahre.", "Registriert wird nur einmal, und zwar in dem EASA-Staat, in dem du deinen Wohnsitz hast – zum EASA-Raum gehören die EU-Länder plus Island, Liechtenstein, Norwegen und die Schweiz. Die Betreibernummer gilt dann im gesamten EASA-Raum: Wer bereits in einem anderen EASA-Land registriert ist, braucht in Irland keine zweite Registrierung. Nur wer außerhalb des EASA-Raums wohnt, registriert sich in dem EASA-Staat, in dem er zuerst fliegt.", "Eine Haftpflichtversicherung ist in Irland für jede gewerbliche Drohnennutzung Pflicht, unabhängig vom Gewicht. Rein privates Freizeitfliegen mit Drohnen unter 20 Kilogramm ist davon ausgenommen.", "In der offenen Kategorie gilt eine maximale Flughöhe von 120 Metern über Grund, wie EU-weit einheitlich geregelt."] },
  { code: "IS", name: "Island", maxAltitude: 120, registrationRequired: true, insuranceRequired: false, sourceUrl: "https://samgongustofa.is/flug/fjarstyrd-loftfor-dronar", rules: ["In Island registrierst du dich als Drohnenbetreiber über flydrone.is bei der Luftfahrtbehörde Samgöngustofa – die Registrierung ist für alle Betreiber mit Wohnsitz in Island Pflicht, unabhängig vom Gewicht der Drohne, und fünf Jahre gültig.", "Registriert wird nur einmal, und zwar in dem EASA-Staat, in dem du deinen Wohnsitz hast – zum EASA-Raum gehören die EU-Länder plus Island, Liechtenstein, Norwegen und die Schweiz. Die Betreibernummer gilt dann im gesamten EASA-Raum: Wer bereits in einem anderen EASA-Land registriert ist, braucht in Island keine zweite Registrierung. Nur wer außerhalb des EASA-Raums wohnt, registriert sich in dem EASA-Staat, in dem er zuerst fliegt.", "Eine Haftpflichtversicherung ist in Island erst ab einem Startgewicht von 20 Kilogramm gesetzlich vorgeschrieben – die EU-Grundregel gilt ohne nationale Verschärfung.", "Rund um sensible Einrichtungen wie Kraftwerke, das Parlamentsgebäude Althingi, Botschaften, Polizeistationen, Gefängnisse und Krankenhäuser gilt ein Sperrbereich von 150 Metern.", "In der offenen Kategorie gilt eine maximale Flughöhe von 120 Metern über Grund, wie in ganz Europa einheitlich geregelt – obwohl Island kein EU-Mitglied ist, wendet das Land die EASA-Vorschriften über das EWR-Abkommen an."] },
  { code: "IL", name: "Israel", maxAltitude: 50, registrationRequired: true, insuranceRequired: false, sourceUrl: "https://www.icd.org.il/english", rules: ["In Israel ist auch für Touristen eine Registrierung vor der Einreise Pflicht: online bei der Israel Drone Organization (ICD, Kosten rund 350 NIS), mit anschließender Freigabe durch Kommunikationsministerium und Zoll, die laut ICD innerhalb von 72 Stunden erfolgt. Zusätzlich ist ein Online-Multiple-Choice-Test der Luftfahrtbehörde CAAI mit 15 Fragen abzulegen (rund 30 NIS).", "Eine Haftpflichtversicherung ist gesetzlich nicht vorgeschrieben, wird aber allen Nutzergruppen empfohlen.", "Auffällig streng: Die maximale Flughöhe liegt bei nur 50 Metern über Grund – deutlich niedriger als der sonst verbreitete Standard von 120 Metern.", "Sperrzonen gelten unter anderem in 2 Kilometern Umkreis um Flughäfen, mit 250 Metern Mindestabstand zu Wohngebieten und Menschenansammlungen, dazu Militäranlagen, Grenzgebiete, Gefängnisse, Kraftwerke, Stadien und Polizeistationen. Über der Jerusalemer Altstadt sollte grundsätzlich nicht geflogen werden.", "Wegen wiederholter militärischer Eskalationen in der Region kann es kurzfristig zu zusätzlichen Luftraumsperrungen kommen – das betrifft dann alle Fluggeräte, nicht nur Drohnen.", "Wichtig: Die gesamte Registrierung und Prüfung muss vor der Anreise abgeschlossen sein – spontanes Fliegen mit einer erst vor Ort besorgten Genehmigung ist nicht vorgesehen."] },
  { code: "IT", name: "Italien", maxAltitude: 120, registrationRequired: true, insuranceRequired: true, sourceUrl: "https://www.enac.gov.it/sicurezza-aerea/droni/categoria-aperta-open-category/requisiti-generali-per-operare-nella/", rules: ["In Italien registrierst du dich als Drohnenbetreiber über das Portal D-Flight bei der Luftfahrtbehörde ENAC – Pflicht ab 250 Gramm Startgewicht oder bei jeder Drohne mit Kamera bzw. anderem Aufnahmesensor. Die zugeteilte Kennung wird als QR-Code an der Drohne angebracht.", "Registriert wird nur einmal, und zwar in dem EASA-Staat, in dem du deinen Wohnsitz hast – zum EASA-Raum gehören die EU-Länder plus Island, Liechtenstein, Norwegen und die Schweiz. Die Betreibernummer gilt dann im gesamten EASA-Raum: Wer bereits in einem anderen EASA-Land registriert ist, braucht in Italien keine zweite Registrierung. Nur wer außerhalb des EASA-Raums wohnt, registriert sich in dem EASA-Staat, in dem er zuerst fliegt.", "Eine Haftpflichtversicherung ist in Italien für jede Drohne in der offenen Kategorie vorgeschrieben, unabhängig vom Gewicht.", "Zusätzlich zu den EU-weiten Vorgaben gilt in Italien das nationale Regelwerk UAS-IT der ENAC, das eigene Ergänzungen etwa zu Kontrollen und Sanktionen enthält.", "In der offenen Kategorie liegt die maximale Flughöhe bei 120 Metern über Grund, wie EU-weit einheitlich geregelt."] },
  { code: "JM", name: "Jamaika", maxAltitude: 122, registrationRequired: false, insuranceRequired: true, sourceUrl: "https://www.jcaa.gov.jm/unmanned-aircraft/", rules: ["Für rein privates Freizeitfliegen verlangt die jamaikanische Luftfahrtbehörde JCAA nach eigenen Angaben keine gesonderte Genehmigung – die genauen Registrierungs- und Gewichtsgrenzen sind allerdings nicht einheitlich dokumentiert, im Zweifel lohnt sich eine direkte Nachfrage bei der JCAA.", "Für gewerbliche Nutzung ist dagegen eine eigene Genehmigung (Special Aerial Work Permit) sowie eine Haftpflichtversicherung mit einer Mindestdeckung von 100.000 US-Dollar vorgeschrieben.", "In der Praxis berichten viele Reisende, dass Drohnen am Flughafen ohne vorherige Anmeldung bei der JCAA (empfohlen zwei bis vier Wochen vorab) vom Zoll bis zur Ausreise einbehalten werden – auch wenn das offiziell kein festgeschriebenes Touristenverfahren ist, lohnt sich die frühzeitige Anmeldung.", "Die maximale Flughöhe liegt bei 400 Fuß (rund 122 Metern) über Grund."] },
  { code: "JP", name: "Japan", maxAltitude: 150, registrationRequired: true, insuranceRequired: false, sourceUrl: "https://www.mlit.go.jp/koku/drone/", rules: ["Seit Juni 2022 müssen in Japan sämtliche unbemannte Luftfahrzeuge ab 100 Gramm Gewicht über das Online-System DIPS2.0 registriert werden; die Registrierung ist drei Jahre gültig, und die zugeteilte Nummer muss sichtbar am Fluggerät angebracht sein.", "Ausländische Besucher können sich mit dem Reisepass anstelle einer japanischen ID-Nummer online registrieren, benötigen dafür aber eine japanische Kontaktadresse, etwa die Hoteladresse, sowie eine funktionierende Remote-ID-Sendeeinheit, sofern das Gerät nicht bereits werkseitig damit ausgestattet ist.", "Das japanische Luftfahrtgesetz begrenzt Flüge grundsätzlich auf 150 Meter über Grund oder Wasser; für höhere Flüge sowie für Nachtbetrieb, Flüge außerhalb der Sichtweite oder über dicht besiedelten Gebieten ist eine gesonderte Genehmigung über DIPS2.0 mit üblicherweise rund zehn Werktagen Bearbeitungszeit erforderlich.", "Eine Haftpflichtversicherung ist in Japan gesetzlich nicht vorgeschrieben, wird von Behörden und Fachverbänden angesichts möglicher Schadenssummen im Millionenbereich aber dringend empfohlen.", "Rund um sensible Bereiche wie den Kaiserpalast, Regierungsgebäude, Flughäfen sowie in zahlreichen Stadtteilen Tokios gelten zusätzliche, teils kurzfristig verhängte Flugverbote, weshalb eine Prüfung der aktuellen Karten vor jedem Flug notwendig ist.", "Verstöße gegen Registrierungs- oder Höhenvorgaben können mit Geldstrafen oder Freiheitsstrafen von bis zu einem Jahr geahndet werden."] },
  { code: "JO", name: "Jordanien", maxAltitude: 120, registrationRequired: true, insuranceRequired: true, sourceUrl: "https://carc.gov.jo/en/drones", rules: ["In Jordanien musst du deine Drohne bei der Luftfahrtbehörde CARC registrieren und dafür eine Haftpflichtversicherung nachweisen. Vor jedem Flug ist zusätzlich eine gesonderte Genehmigung nötig, für die du mindestens zehn Werktage einplanen solltest – der Antrag verlangt unter anderem Pilotenlizenz, Versicherungsnachweis, Seriennummer der Drohne und die geplante GPS-Route.", "Die maximale Flughöhe liegt bei 120 Metern über Grund.", "Sperrzonen gelten in 5 Kilometern Umkreis um die großen Flughäfen (u. a. Amman-Queen Alia), an den nördlichen und westlichen Grenzgebieten, um Militärzonen, Königspaläste und Botschaften. Über sensiblen Zonen wird ein Flug ohne Genehmigung ernst genommen und kann strafrechtliche Folgen haben.", "Für die beliebten Ausflugsziele Petra und Wadi Rum brauchst du zusätzlich zur CARC-Freigabe eine eigene Genehmigung der jeweils zuständigen Schutzgebietsverwaltung.", "Bei der Einreise muss die Drohne im Aufgabegepäck transportiert werden, Lithium-Akkus separat im Handgepäck. Ohne Vorabgenehmigung droht am Zoll die Einbehaltung gegen eine Kaution von umgerechnet mehreren hundert Euro bis zur Ausreise; Bußgelder bei Verstößen liegen im Bereich von 1.000 bis 3.000 JOD.", "Kurz gesagt: In Jordanien zu fliegen ist möglich, aber nur mit ordentlichem Vorlauf vor der Reise – spontan geht hier nichts."] },
  { code: "KH", name: "Kambodscha", maxAltitude: null, registrationRequired: true, insuranceRequired: false, sourceUrl: "https://www.akp.gov.kh/post/detail/357648", rules: ["Am 30. Dezember 2025 hat das kambodschanische Verteidigungsministerium per Direktive ein landesweites Verbot für Start und Betrieb sämtlicher Drohnenarten ohne vorherige Genehmigung erlassen, das im Zusammenhang mit dem bewaffneten Grenzkonflikt mit Thailand steht und nach verfügbaren Quellen mit Stand Mitte 2026 weiterhin in Kraft ist.", "Seit Dezember 2025 hält an der Grenze ein Waffenstillstand an, dieser gilt jedoch als fragil, und insbesondere die an Thailand angrenzenden Provinzen sowie die Provinz Pursat unterliegen weiterhin einer verschärften militärischen Überwachung.", "Verstöße gegen das Drohnenverbot können strafrechtlich verfolgt werden, und die kambodschanischen Streitkräfte sind ausdrücklich befugt, nicht genehmigte Drohnen mittels Anti-Drohnen-Systemen abzuwehren.", "Von der Mitnahme und dem Betrieb einer Drohne in Kambodscha wird daher derzeit grundsätzlich abgeraten, unabhängig vom konkreten Reiseziel innerhalb des Landes."] },
  { code: "CM", name: "Kamerun", maxAltitude: 120, registrationRequired: true, insuranceRequired: false, sourceUrl: "https://drone-laws.com/drone-laws-in-cameroon/", rules: ["Kamerun hat noch kein vollständig kodifiziertes Drohnenregelwerk – bislang existiert nur ein Rundschreiben der Luftfahrtbehörde CCAA zur Kennzeichnung von Drohnen, ein umfassenderes Regelwerk war zuletzt weiterhin \"in Entwicklung\". Die Quellenlage zur Registrierungspflicht ist entsprechend uneinheitlich, in der Praxis ist aber von einer Genehmigungspflicht auszugehen.", "Eine Versicherung ist für private Nutzung nicht verpflichtend, wird aber empfohlen; für kommerzielle Flüge ist sie üblich.", "Eine häufig genannte, aber nicht amtlich bestätigte Flughöhengrenze liegt bei 120 Metern.", "Entscheidend für Reisende: Jeder Flug – auch touristisch – soll mindestens 30 Tage im Voraus bei der CCAA beantragt und zusätzlich mit dem Verteidigungsministerium abgestimmt werden. Auch die Einfuhr selbst gilt als genehmigungspflichtig. Sperrzonen gelten in 5,5 Kilometern um Flughäfen und in 15 Metern zu Personen und Gebäuden.", "Für Kurzzeit-Touristen ist das damit praktisch kaum umsetzbar – wer trotzdem legal fliegen möchte, muss den Antrag lange vor der Reise stellen."] },
  { code: "CA", name: "Kanada", maxAltitude: 122, registrationRequired: true, insuranceRequired: false, sourceUrl: "https://tc.canada.ca/en/aviation/drone-safety", rules: ["In Kanada musst du Drohnen zwischen 250 Gramm und 25 Kilogramm bei Transport Canada registrieren und brauchst zusätzlich einen kanadischen Drohnenführerschein (Basic oder Advanced) – ein EU-Kompetenznachweis wird nicht anerkannt.", "Wichtig für Besucher aus Deutschland: Für jede Drohne ab 250 Gramm brauchst du zusätzlich zur Prüfung eine gesonderte Sondererlaubnis (SFOC-RPAS), deren Bearbeitung bis zu 30 Arbeitstage dauern kann – plane das unbedingt weit im Voraus. Nur Drohnen unter 250 Gramm sind davon ausgenommen.", "Eine Haftpflichtversicherung ist in Kanada gesetzlich nicht vorgeschrieben, wird von Transport Canada aber ausdrücklich empfohlen.", "Die maximale Flughöhe liegt bei 400 Fuß (rund 122 Metern) über Grund, mit mindestens 30 Metern horizontalem Abstand zu unbeteiligten Personen."] },
  { code: "KZ", name: "Kasachstan", maxAltitude: null, registrationRequired: true, insuranceRequired: false, sourceUrl: "https://egov.kz/cms/en/government-services/for_busunesses/pass_1102023_mt", rules: ["In Kasachstan muss jede Drohne bei der Luftfahrtbehörde registriert werden. Die verfügbaren Quellen widersprechen sich bei der genauen Gewichtsschwelle – Angaben reichen von 250 Gramm bis zu einer generellen Pflicht unabhängig vom Gewicht –, weshalb hier keine einzelne Zahl als gesichert gelten sollte.", "Eine Haftpflichtversicherung ist nicht gesetzlich vorgeschrieben, wird aber empfohlen.", "Auch bei der maximalen Flughöhe sind die Angaben uneinheitlich (120 Meter in einer Quelle, 50 Meter als Schwelle für eine genehmigungsfreie Nutzung in einer anderen) – eine amtlich eindeutig bestätigte einzelne Zahl war nicht auffindbar.", "Sperrzonen gelten in 5,5 bis 8 Kilometern Umkreis um Flughäfen (je nach Quelle), dazu über Menschenansammlungen, Regierungsgebäuden, Militärbasen und Industrieanlagen; Mindestabstände von 50 Metern beim Start/bei der Landung und 100 Metern im Flug zu Personen und Gebäuden sind einzuhalten.", "Die Registrierung selbst setzt eine kasachische Identifikationsnummer (IIN) samt elektronischer Signatur voraus – für Ausländer ohne Aufenthaltsstatus ist das kurzfristig kaum zu bekommen. In Reiseforen werden dennoch vergleichsweise wenige Probleme mit mitgebrachten Drohnen berichtet, was Kasachstan im Vergleich zu den Nachbarländern als eher zugänglich erscheinen lässt – ein dokumentierter Fall von Gewahrsam wegen eines Überflugs über den Präsidenten zeigt aber, dass sensible Ziele weiterhin ernste Konsequenzen haben können."] },
  { code: "QA", name: "Katar", maxAltitude: null, registrationRequired: true, insuranceRequired: true, sourceUrl: "https://marhaba.qa/qatars-new-drone-law-introduces-licensing-rules-up-to-seven-years-imprisonment-and-qar300000-fines/", rules: ["Katar hat sein Drohnenrecht mit dem Gesetz Nr. 10/2026 (veröffentlicht im Juli 2026) grundlegend neu geregelt und deutlich verschärft. Jede Drohne muss registriert werden, für den Betrieb ist zusätzlich eine Lizenz nötig – auch für reine Freizeitnutzung.", "Eine Haftpflichtversicherung gegenüber Dritten ist gesetzlich vorgeschrieben.", "Eine feste Meterangabe zur maximalen Flughöhe nennt das neue Gesetz nicht, sondern verweist auf von der Behörde im Einzelfall festgelegte Grenzen. In älteren Quellen kursiert eine Zahl von rund 122 Metern (400 Fuß), die aber nicht als amtlich bestätigt gelten sollte.", "Am wichtigsten für Reisende: Drohnenflüge durch ausländische Besucher sind nach dem neuen Gesetz ausdrücklich untersagt, Genehmigungen werden nur an Personen mit Wohnsitz in Katar vergeben. Bei der Einreise kann die Drohne deklariert und bis zu zwei Wochen am Flughafen verwahrt werden, statt sie einzuführen.", "Verstöße werden hart geahndet: Je nach Schwere drohen Geldstrafen bis 300.000 QAR und Haftstrafen bis zu sieben Jahren, dazu Lizenzentzug und Einziehung des Geräts.", "Für kurzfristige Touristen gibt es damit aktuell keinen legalen Weg, in Katar zu fliegen."] },
  { code: "KE", name: "Kenia", maxAltitude: 122, registrationRequired: true, insuranceRequired: false, sourceUrl: "https://drone-laws.com/drone-laws-in-kenya/", rules: ["In Kenia muss jede Drohne bei der Luftfahrtbehörde KCAA registriert werden, unabhängig vom Verwendungszweck. Eigentum und Registrierung sind aber grundsätzlich kenianischen Staatsbürgern, Residenten und Firmen vorbehalten – als Tourist brauchst du zusätzlich ein temporäres Import-Permit, oder du greifst auf eine der vor Ort angebotenen Mietdrohnen zurück.", "Für die reine Freizeitkategorie (bis 25 Kilogramm) reicht eine Meldung bei der KCAA, eine volle Betriebsgenehmigung ist nicht nötig. Eine Versicherung ist für Hobbyflieger nicht vorgeschrieben, für kommerzielle Nutzung dagegen schon.", "Die maximale Flughöhe liegt bei 122 Metern (400 Fuß).", "Sperrzonen gelten in 50 Metern zu Menschen und Fahrzeugen sowie in 7 bis 10 Kilometern um Flughäfen. Für Nationalparks und Wildreservate – ein naheliegendes Fotomotiv – brauchst du zusätzlich zur KCAA-Freigabe auch die Erlaubnis der jeweiligen Parkbehörde und der Kenya Film Commission.", "Bei Verstößen drohen Bußgelder bis umgerechnet mehreren tausend Euro oder bis zu einem Jahr Haft, bei Eigentums- oder Privatsphäreverstößen noch mehr.", "Kurz gesagt: Mit eigener Drohne administrativ aufwendig, aber nicht unmöglich – für viele Touristen ist die Miete einer Drohne vor Ort der unkompliziertere Weg."] },
  { code: "CO", name: "Kolumbien", maxAltitude: 150, registrationRequired: true, insuranceRequired: false, sourceUrl: "https://www.aerocivil.gov.co/autoridad_aeronautica/normatividad/13-reglamentos-aeronauticos-de-colombia-rac", rules: ["Drohnen werden nach Startgewicht in drei Klassen eingeteilt: Klasse A für Freizeitgebrauch bis 10 Kilogramm, Klasse B für kommerzielle beziehungsweise professionelle Nutzung bis 150 Kilogramm und Klasse C für experimentelle Fluggeräte über 150 Kilogramm; zuständige Behörde ist die UAEAC, besser bekannt als Aerocivil.", "Die Registrierung erfolgt online über das Portal der Aerocivil oder per E-Mail mit den erforderlichen Unterlagen; ohne diese Registrierung darf grundsätzlich kein Drohnenflug in Kolumbien stattfinden.", "Die Flughöhe ist auf rund 150 Meter über Grund begrenzt, und ein vollständig autonomer Betrieb ohne durchgehende Kontrolle durch den Piloten ist nach dem Regelwerk RAC 91 nicht erlaubt.", "Größere Sicherheitsabstände gelten unter anderem zu Flughäfen und Hubschrauberlandeplätzen mit etwa 9,2 Kilometern, zu Staatsgrenzen mit rund 3,6 Kilometern, zu Amtsträgern und Staatsgästen mit etwa 5,5 Kilometern sowie zu Gefängnissen und militärischen Einrichtungen.", "Für die kommerzielle Klasse B zwischen 10 und 150 Kilogramm verlangt Aerocivil den Nachweis einer Haftpflichtversicherung für Schäden gegenüber Dritten; für die kleinere Klasse A ist dieser Nachweis nach den vorliegenden Quellen nicht ausdrücklich gefordert. Besondere Regeln für Amazonas-Schutzgebiete oder für ausländische Touristen sind in den verfügbaren Quellen nicht eindeutig dokumentiert, weshalb sich eine Rückfrage bei Aerocivil vor der Reise empfiehlt."] },
  { code: "XK", name: "Kosovo", maxAltitude: 150, registrationRequired: true, insuranceRequired: false, sourceUrl: "https://caa.rks-gov.net/en/rpas/", rules: ["Im Kosovo brauchst du für Drohnen ab 0,5 Kilogramm eine Genehmigung und Registrierung bei der Zivilluftfahrtbehörde CAA Kosovo.", "Eine landesweite gesetzliche Versicherungspflicht ist nicht dokumentiert.", "Geflogen werden darf im Kosovo ausschließlich bei Tageslicht und in Sichtweite; für die leichteste Kategorie unter 1 Kilogramm liegt die Höchstgrenze bei 50 Metern, ansonsten grundsätzlich bei 150 Metern über Grund, sofern die Behörde nicht mehr genehmigt."] },
  { code: "HR", name: "Kroatien", maxAltitude: 120, registrationRequired: true, insuranceRequired: false, sourceUrl: "https://www.ccaa.hr/en/uas-operator-registration-52143", rules: ["In Kroatien registrierst du dich als Drohnenbetreiber über die FAUST-Plattform der Zivilluftfahrtbehörde CCAA – Pflicht ab 250 Gramm Startgewicht, bei mehr als 80 Joule Aufprallenergie oder bei jeder Drohne mit einem Sensor, der personenbezogene Daten erfassen kann.", "Registriert wird nur einmal, und zwar in dem EASA-Staat, in dem du deinen Wohnsitz hast – zum EASA-Raum gehören die EU-Länder plus Island, Liechtenstein, Norwegen und die Schweiz. Die Betreibernummer gilt dann im gesamten EASA-Raum: Wer bereits in einem anderen EASA-Land registriert ist, braucht in Kroatien keine zweite Registrierung. Nur wer außerhalb des EASA-Raums wohnt, registriert sich in dem EASA-Staat, in dem er zuerst fliegt.", "Eine Haftpflichtversicherung ist in Kroatien nach der EU-Grundregel erst ab einem Startgewicht von 20 Kilogramm gesetzlich vorgeschrieben; für gewerbliche Nutzung lohnt sich unabhängig davon in der Praxis eine Rücksprache mit dem Versicherer.", "In der offenen Kategorie gilt eine maximale Flughöhe von 120 Metern über Grund, wie EU-weit einheitlich geregelt."] },
  { code: "CU", name: "Kuba", maxAltitude: null, registrationRequired: true, insuranceRequired: false, sourceUrl: "https://www.iacc.gob.cu/", rules: ["Wichtiger Hinweis: Kuba hat aktuell keinen praktikablen Weg für Touristen, eine eigene Drohne zu nutzen. Nach Dekret 34/2021 dürfen Zollbehörden Drohnen bei Ein- oder Ausreise ohne vorherige Importgenehmigung einbehalten – das kubanische Zollamt rät Reisenden ausdrücklich davon ab, überhaupt eine Drohne mitzubringen.", "Ziviles Drohnenfliegen ist im Wesentlichen lizenzierten Piloten sowie staatlich beauftragten Stellen vorbehalten, etwa GEOCUBA für gewerbliche Arbeiten oder dem Cuba Aviation Club für Modellflug.", "Für deinen Kuba-Urlaub gilt daher: Plane besser ohne eigene Drohne – das Risiko einer vorübergehenden Beschlagnahmung ist real und wird von Reisenden immer wieder berichtet."] },
  { code: "KW", name: "Kuwait", maxAltitude: null, registrationRequired: false, insuranceRequired: false, sourceUrl: "https://timeskuwait.com/moi-imposes-nationwide-ban-on-drones-aerial-filming/", rules: ["Wichtiger Hinweis: Seit dem 3. März 2026 gilt in Kuwait ein vollständiges, landesweites Verbot für Drohnenflüge und Luftaufnahmen, verhängt vom Innenministerium ohne genannte Ausnahmen für Einwohner oder Touristen. Hintergrund waren mutmaßlich iranische Drohnen- und Raketenangriffe auf den Kuwait International Airport zwischen Ende Februar und April 2026.", "Am 2. April 2026 kam ein zusätzliches Verbot für Verkauf und Handel mit Drohnen in allen Geschäften und auf Märkten hinzu.", "Im August 2026 hat das Kabinett den Entwurf eines neuen, deutlich umfangreicheren Drohnengesetzes verabschiedet und dem Emir zur Unterzeichnung vorgelegt – ob und wann es in Kraft tritt und was danach für Freizeitpiloten gilt, war zum Zeitpunkt der Recherche noch offen.", "Schon vor der aktuellen Verschärfung war die Einfuhr ohne Vorabgenehmigung untersagt, mit Beschlagnahmung am Flughafen und Strafen von bis zu drei Jahren Haft.", "Für die Kuwait-Reise gilt daher: Drohne besser gar nicht erst mitnehmen. Aktuell gibt es keinen legalen Weg, dort zu fliegen – weder für Einwohner noch für Besucher."] },
  { code: "LV", name: "Lettland", maxAltitude: 120, registrationRequired: true, insuranceRequired: true, sourceUrl: "https://droni.caa.gov.lv/en/uasis/", rules: ["In Lettland registrierst du dich als Drohnenbetreiber über den Online-Dienst der Zivilluftfahrtbehörde CAA (e.caa.gov.lv) – Pflicht ab 250 Gramm Startgewicht oder bei jeder Drohne mit Kamera, unabhängig vom Gewicht. Die jährliche Gebühr beträgt 5 Euro.", "Registriert wird nur einmal, und zwar in dem EASA-Staat, in dem du deinen Wohnsitz hast – zum EASA-Raum gehören die EU-Länder plus Island, Liechtenstein, Norwegen und die Schweiz. Die Betreibernummer gilt dann im gesamten EASA-Raum: Wer bereits in einem anderen EASA-Land registriert ist, braucht in Lettland keine zweite Registrierung. Nur wer außerhalb des EASA-Raums wohnt, registriert sich in dem EASA-Staat, in dem er zuerst fliegt.", "Eine Haftpflichtversicherung ist in Lettland deutlich strenger geregelt als die EU-Grundregel: Für die Unterkategorien A2, A3 sowie die spezifische Kategorie ist eine Mindestdeckung von umgerechnet mehreren hunderttausend Euro vorgeschrieben, statt der EU-weiten Pflicht erst ab 20 Kilogramm.", "Das Mindestalter für Drohnenbetreiber liegt bei 16 Jahren.", "In der offenen Kategorie gilt eine maximale Flughöhe von 120 Metern über Grund oder Wasseroberfläche, wie EU-weit einheitlich geregelt."] },
  { code: "LB", name: "Libanon", maxAltitude: null, registrationRequired: false, insuranceRequired: false, sourceUrl: "https://drone-traveller.com/drone-laws-lebanon/", rules: ["Wichtiger Hinweis: Über Drohnenflüge in Libanon entscheidet nicht die Zivilluftfahrtbehörde, sondern im Einzelfall die libanesische Armee. Nach verfügbaren Quellen sind seit März 2026 sämtliche Genehmigungen ausgesetzt, Ausnahmen gibt es nur noch vereinzelt für Anlässe wie Hochzeiten oder kulturelle/sportliche Veranstaltungen.", "Diese Aussetzung fällt zeitlich mit einer erneuten militärischen Eskalation zwischen Israel und der Hisbollah zusammen. Größere Kampfhandlungen mit israelischem Vordringen in den Süden Libanons wurden für März/April 2026 dokumentiert, ein Waffenstillstand folgte im April, an dem sich im Juni 2026 weitere Verhandlungen anschlossen. Für die Zeit danach ließ sich keine verlässliche aktuelle Bestätigung der Sicherheitslage finden.", "Im Süden Libanons, nahe der Grenze zu Israel, gilt ohnehin besondere Vorsicht: Zivile Drohnen können dort mit militärischen verwechselt werden, das Militär behält sich Abschuss oder Beschlagnahmung ausdrücklich vor.", "Zur Einfuhr gibt es keine schriftlich fixierte Regelung; einzelne DJI-Modelle wurden Erfahrungsberichten zufolge am Zoll nicht durchgelassen.", "Für die Libanon-Reise gilt aktuell: Drohne besser zu Hause lassen. Ein praktikabler legaler Weg besteht derzeit nicht, unabhängig vom geplanten Reiseziel im Land."] },
  { code: "LR", name: "Liberia", maxAltitude: null, registrationRequired: false, insuranceRequired: false, sourceUrl: "https://drone-laws.com/drone-laws-in-liberia/", rules: ["Wichtiger Hinweis: Liberia hat bislang kein verabschiedetes Drohnenregelwerk – die zuständige Luftfahrtbehörde LCAA hatte nach verfügbaren Quellen zwar Vorschriften entworfen, diese aber noch nicht offiziell in Kraft gesetzt.", "Das fehlende Regelwerk bedeutet dabei ausdrücklich keine automatische Erlaubnis: Die Behörden können den Betrieb im Einzelfall trotzdem untersagen, und der Zoll kann Drohnen ohne klare gesetzliche Grundlage einbehalten.", "Eine der ausgewerteten Quellen fasst die Lage explizit so zusammen: Drohnenflüge durch ausländische Besucher sind in Liberia nicht erlaubt.", "Eine feste Angabe zu Flughöhe oder Versicherungspflicht existiert mangels Regelwerk nicht.", "Für die Liberia-Reise gilt daher: Ohne verlässliche Rechtsgrundlage und mit dokumentiertem Risiko der Einbehaltung ist von der Mitnahme einer Drohne abzuraten."] },
  { code: "LI", name: "Liechtenstein", maxAltitude: 120, registrationRequired: true, insuranceRequired: true, sourceUrl: "https://www.landespolizei.li/informationen/drohnen", rules: ["Liechtenstein hat kein eigenes Drohnenrecht, sondern übernimmt vollständig das Schweizer Luftfahrtrecht – zuständig ist das Schweizer Bundesamt für Zivilluftfahrt (BAZL), Registrierung und Betreibernummer laufen über dieselbe Plattform (dLIS) wie in der Schweiz.", "Registriert wird nur einmal, und zwar in dem EASA-Staat, in dem du deinen Wohnsitz hast – zum EASA-Raum gehören die EU-Länder plus Island, Liechtenstein, Norwegen und die Schweiz. Die Betreibernummer gilt dann im gesamten EASA-Raum: Wer bereits in einem anderen EASA-Land registriert ist, braucht in Liechtenstein keine zweite Registrierung. Nur wer außerhalb des EASA-Raums wohnt, registriert sich in dem EASA-Staat, in dem er zuerst fliegt.", "Für Drohnen ab 250 Gramm ist eine Haftpflichtversicherung mit einer Mindestdeckungssumme von 1 Million Schweizer Franken vorgeschrieben; der Versicherungsnachweis muss beim Fliegen mitgeführt werden.", "Rund um Regierungsgebäude in Vaduz gelten dauerhafte Flugverbotszonen – die aktuellen Sperrgebiete sind in der BAZL-Drohnenkarte eingezeichnet, die auch für Liechtenstein gilt.", "Fragen zu Bewilligungen und Ausnahmen beantwortet das Amt für Bau und Raumplanung, Bereich Zivilluftfahrt."] },
  { code: "LT", name: "Litauen", maxAltitude: 120, registrationRequired: true, insuranceRequired: false, sourceUrl: "https://tka.lt/en/katalogas/dazniausiai-uzduodami-klausimai/", rules: ["In Litauen registrierst du dich als Drohnenbetreiber bei der Transportbehörde TKA – über sertifitai.tka.lt oder, mit litauischer digitaler Signatur, über das E-Government-Portal VIISP. Eine Betreibernummer deckt alle deine Drohnen ab.", "Registriert wird nur einmal, und zwar in dem EASA-Staat, in dem du deinen Wohnsitz hast – zum EASA-Raum gehören die EU-Länder plus Island, Liechtenstein, Norwegen und die Schweiz. Die Betreibernummer gilt dann im gesamten EASA-Raum: Wer bereits in einem anderen EASA-Land registriert ist, braucht in Litauen keine zweite Registrierung. Nur wer außerhalb des EASA-Raums wohnt, registriert sich in dem EASA-Staat, in dem er zuerst fliegt.", "Eine Haftpflichtversicherung ist in Litauen nach Angaben der TKA erst ab einem Startgewicht von 20 Kilogramm gesetzlich vorgeschrieben – die EU-Grundregel gilt ohne nationale Verschärfung.", "Flüge im kontrollierten Luftraum rund um Vilnius, Kaunas oder Palanga musst du bis spätestens 12 Uhr des Vortags anmelden; die Freigabe erfolgt über die UTM-Karte von Oro navigacija.", "In der offenen Kategorie gilt eine maximale Flughöhe von 120 Metern über Grund, wie EU-weit einheitlich geregelt."] },
  { code: "LU", name: "Luxemburg", maxAltitude: 120, registrationRequired: true, insuranceRequired: true, sourceUrl: "https://dac.gouvernement.lu/en/drones/where-when-register.html", rules: ["In Luxemburg registrierst du dich als Drohnenbetreiber über das Portal Guichet.lu bei der Luftfahrtbehörde DAC – Pflicht ab 250 Gramm Startgewicht oder bei jeder Drohne mit Kamera bzw. anderem Sensor. Seit Januar 2026 gilt ein neues Regelwerk mit jährlicher Erneuerungspflicht (10 Euro Gebühr) statt der bisher längeren Gültigkeit.", "Registriert wird nur einmal, und zwar in dem EASA-Staat, in dem du deinen Wohnsitz hast – zum EASA-Raum gehören die EU-Länder plus Island, Liechtenstein, Norwegen und die Schweiz. Die Betreibernummer gilt dann im gesamten EASA-Raum: Wer bereits in einem anderen EASA-Land registriert ist, braucht in Luxemburg keine zweite Registrierung. Nur wer außerhalb des EASA-Raums wohnt, registriert sich in dem EASA-Staat, in dem er zuerst fliegt.", "Eine Haftpflichtversicherung ist in Luxemburg für jede Drohne in der offenen und der spezifischen Kategorie vorgeschrieben, unabhängig vom Gewicht.", "Die nationale Geozonen-Karte auf dem Geoportail gilt als rechtlich maßgeblich – auch wenn die Geofencing-Daten deines Drohnenherstellers etwas anderes anzeigen.", "In der offenen Kategorie gilt eine maximale Flughöhe von 120 Metern über Grund, wie EU-weit einheitlich geregelt."] },
  { code: "MO", name: "Macau", maxAltitude: 30, registrationRequired: true, insuranceRequired: false, sourceUrl: "https://www.aacm.gov.mo/en/guide/DronesandOthers/Drones", rules: ["Die Verkehrsluftfahrtbehörde AACM unterteilt Drohnen nach Gewicht in drei Kategorien, CAT 1 bis 250 Gramm, CAT 2 von 250 Gramm bis 7 Kilogramm und CAT 3 von 7 bis 25 Kilogramm, wobei ohne gesonderte Genehmigung nur Flüge bis 30 Meter über Grund zulässig sind.", "Für Geräte der Kategorie CAT 1 sind weder eine Geräteregistrierung noch eine Pilotenregistrierung notwendig, ab CAT 2, also oberhalb von 250 Gramm, müssen sowohl die Drohne als auch der Pilot über die Online Service Platform der AACM registriert und jeder einzelne Flug vorab dort angemeldet werden.", "Auch Touristen und andere ausländische Besucher müssen ihre Drohne registrieren, sobald sie mehr als 250 Gramm wiegt, obwohl für den rein privaten Gebrauch keine gesonderte Pilotenlizenz verlangt wird.", "Eine gesetzliche Haftpflichtversicherung ist erst ab Kategorie CAT 3, also oberhalb von 7 Kilogramm, vorgeschrieben, und zwar mit einer Mindestdeckungssumme von 10 Millionen Patacas; für den typischen freizeitlichen Einsatz mit kleineren Drohnen besteht keine Versicherungspflicht, eine Versicherung wird von der Behörde aber empfohlen.", "Ein Sicherheitsabstand von rund 1.000 Metern zu Flughäfen sowie feste Mindestabstände zu größeren Menschenansammlungen und geschützten Gebäuden sind einzuhalten, zusätzlich existiert eine offizielle Flugkarte mit weiteren Sperr- und Beschränkungszonen, die vor jedem Flug zu prüfen ist.", "Verstöße gegen die Vorschriften können laut verfügbaren Quellen mit Geldstrafen bis rund 20.000 Patacas geahndet werden, eine vollständige, direkt von der AACM veröffentlichte Bußgeldtabelle mit exakten Beträgen ließ sich bei der Recherche nicht auffinden; seit dem 1. Februar 2026 gilt zudem ein neues Luftfahrtgesetz, das die bisherigen Sanktionsregeln teilweise ersetzt."] },
  { code: "MG", name: "Madagaskar", maxAltitude: null, registrationRequired: true, insuranceRequired: false, sourceUrl: "https://waumadagascar.com/blog/new-drone-regulations-in-madagascar-what-travelers-and-operators-need-to-know", rules: ["In Madagaskar muss die überwiegende Mehrheit der Drohnen bei der Luftfahrtbehörde ACM registriert werden. Eine Ausnahme gilt nur für eine enge \"Spielzeug\"-Kategorie, deren genaue Grenze (Reichweite unter 100 Metern ohne Sensorik, oder ein Gewicht unter etwa 900 Gramm) sich in den verfügbaren Quellen widerspricht.", "Für Touristen existiert ein vereinfachtes, temporäres Registrierungsverfahren direkt per E-Mail an die ACM, die Bearbeitung dauert allerdings mehrere Wochen.", "Eine offizielle Angabe zur maximalen Flughöhe war nicht auffindbar.", "Sperrzonen gelten in mehreren Kilometern um Flughäfen, über Städten und Menschenansammlungen, um Militär- und Regierungseinrichtungen sowie in Nationalparks und weiteren Schutzgebieten, wo zusätzlich eine Genehmigung des Umweltministeriums nötig ist.", "Die Strafen bei unregistrierter Nutzung sind drastisch: fünf bis zehn Jahre Haft und ein hohes Bußgeld sind im Gesetz vorgesehen, auch wenn die tatsächliche Durchsetzung an den Grenzen bislang uneinheitlich beschrieben wird.", "Wer trotzdem fliegen möchte, sollte die E-Mail-Registrierung frühzeitig vor der Reise anstoßen, statt auf eine unsichere Kontrolle am Flughafen zu hoffen."] },
  { code: "MY", name: "Malaysia", maxAltitude: 120, registrationRequired: true, insuranceRequired: false, sourceUrl: "https://www.caam.gov.my/public/unmanned-aircraft-system-uas/", rules: ["Die zulässige Flughöhe liegt landesweit bei 120 Metern (400 Fuß) über Grund; höhere Flüge bedürfen einer gesonderten Freigabe der Flugsicherung.", "Drohnen bis 20 Kilogramm gelten als 'Small UAS', schwerere Systeme benötigen eine zusätzliche Genehmigung der Civil Aviation Authority of Malaysia (CAAM).", "Für praktisch jeden Flug, auch touristische Freizeitflüge, ist eine sogenannte Standard Authorisation to Fly (ATF) bei der CAAM erforderlich, die mindestens 14 Werktage vor dem geplanten Flug beantragt werden muss; für Touristen mit kurzen Aufenthalten ist dieser Vorlauf in der Praxis die größte Hürde, da spontane Flüge damit ausgeschlossen sind.", "Eine gesetzliche Versicherungspflicht besteht nicht, eine Haftpflichtversicherung wird von der CAAM aber ausdrücklich empfohlen.", "Sperrzonen gelten unter anderem im Umkreis von rund 9,3 Kilometern um Flughäfen, innerhalb von 150 Metern zu Wohn-, Gewerbe- und Erholungsgebieten sowie über Menschenansammlungen ab 1.000 Personen; Nachtflüge und Flüge außerhalb der Sichtweite sind ohne Sondergenehmigung untersagt.", "Verstöße können mit Geldstrafen bis zu 50.000 Ringgit für Privatpersonen und bis zu 100.000 Ringgit für Unternehmen sowie mit Freiheitsstrafen von mehr als drei Jahren geahndet werden."] },
  { code: "MV", name: "Malediven", maxAltitude: 122, registrationRequired: true, insuranceRequired: false, sourceUrl: "https://caa.gov.mv/operations/flying-remotely-piloted-aircraft-(drones)-in-the-maldives", rules: ["Auf den Malediven gibt es kein klassisches Registrierungssystem mit Gewichtsschwelle – stattdessen braucht jeder einzelne Drohnenflug eine eigene, mehrstufige Genehmigung, unabhängig vom Gewicht der Drohne.", "Der offizielle Ablauf besteht aus drei Schritten: zuerst eine Freigabe der Maldives National Defence Force über ein Online-Formular, danach ein Antrag bei der Luftfahrtbehörde CAA, und schließlich – ausdrücklich als eigener Schritt genannt – die Zustimmung des jeweiligen Resorts, der Insel- oder der Stadtverwaltung, je nachdem, wo geflogen werden soll.", "Die maximale Flughöhe liegt bei rund 122 Metern (400 Fuß). Eine Versicherungspflicht ist in den verfügbaren Quellen nicht dokumentiert.", "Wichtig gerade für Resort-Urlauber: Die Regeln unterscheiden sich zusätzlich von Insel zu Insel. Manche Resorts verbieten Drohnen komplett, andere erlauben sie mit Auflagen wie festen Zeitfenstern oder Mindestabstand zu den Wasservillen – das lohnt sich, schon vor der Buchung beim Resort direkt zu erfragen.", "Die Einfuhr selbst ist nach verfügbaren (nicht amtlichen) Berichten unproblematisch, betroffen ist nur der Betrieb ohne Genehmigung.", "Insgesamt ist der offizielle Weg mehrstufig und wird im Einzelfall geprüft; nach Erfahrungsberichten kann die gesamte Genehmigung mehrere Wochen dauern. Für kurzfristig gebuchte Reisen ist das kaum realistisch umzusetzen – wer seine Drohne auf den Malediven nutzen möchte, sollte deutlich vor der Reise mit CAA, MNDF und dem Resort in Kontakt treten."] },
  { code: "MT", name: "Malta", maxAltitude: 120, registrationRequired: true, insuranceRequired: true, sourceUrl: "https://www.transport.gov.mt/aviation/drones/registration-4448", rules: ["In Malta registrierst du dich als Drohnenbetreiber über die Plattform von Transport Malta (Civil Aviation Directorate) – Pflicht ab 250 Gramm Startgewicht oder bei jeder Drohne mit Kamera bzw. anderem Aufnahmesensor.", "Registriert wird nur einmal, und zwar in dem EASA-Staat, in dem du deinen Wohnsitz hast – zum EASA-Raum gehören die EU-Länder plus Island, Liechtenstein, Norwegen und die Schweiz. Die Betreibernummer gilt dann im gesamten EASA-Raum: Wer bereits in einem anderen EASA-Land registriert ist, braucht in Malta keine zweite Registrierung. Nur wer außerhalb des EASA-Raums wohnt, registriert sich in dem EASA-Staat, in dem er zuerst fliegt.", "Eine Haftpflichtversicherung ist in Malta für jede Drohne vorgeschrieben, unabhängig vom Gewicht – die Behörde begründet das damit, dass praktisch der gesamte maltesische Luftraum als kontrolliert gilt.", "Wegen des durchgehend kontrollierten Luftraums lohnt sich vor jedem Flug ein Blick auf die Geozonen-Vorgaben von Transport Malta, da viele Bereiche eine gesonderte Freigabe benötigen.", "In der offenen Kategorie gilt eine maximale Flughöhe von 120 Metern über Grund, wie EU-weit einheitlich geregelt."] },
  { code: "MA", name: "Marokko", maxAltitude: null, registrationRequired: false, insuranceRequired: false, sourceUrl: "https://www.auswaertiges-amt.de/de/service/laender/marokko-node/marokkosicherheit/224080", rules: ["Einfuhrverbot: Laut Auswärtigem Amt ist die Einfuhr von Flugdrohnen aller Art nach Marokko streng verboten. Das gilt unabhängig von Größe und Gewicht – also auch für kleine Drohnen unter 250 g im Handgepäck.", "Der Zoll beschlagnahmt die Drohne bei der Einreise, Verstöße werden strafrechtlich verfolgt. Dass Reisende ihre Drohne bei der Ausreise zurückbekommen haben, ist kein Anspruch – verlass dich nicht darauf.", "Einen Weg für Freizeitpiloten, eine Drohne legal einzuführen, gibt es nicht. Deshalb gibt es auch keine Angaben zu Flughöhe, Registrierung oder Versicherung.", "Für die Marokko-Reise heißt das: Lass die Drohne zu Hause."] },
  { code: "MU", name: "Mauritius", maxAltitude: 120, registrationRequired: true, insuranceRequired: false, sourceUrl: "https://ts2.tech/en/mauritius-drone-laws-2025-8-critical-rules-recent-updates-every-pilot-must-know/", rules: ["Auf Mauritius müssen seit dem 1. Januar 2025 alle Drohnen und ihre Piloten unabhängig vom Gewicht bei der Luftfahrtbehörde DCA registriert werden – eine ältere, häufig noch zitierte Ausnahme für Drohnen unter 7 Kilogramm gilt damit nicht mehr.", "Eine Versicherung ist für Freizeitnutzung nicht verpflichtend, wird aber empfohlen; für gewerbliche Nutzung ist sie Pflicht.", "Die maximale Flughöhe liegt bei 120 Metern (400 Fuß).", "Sperrzonen sind großzügig bemessen: 27 Kilometer um den internationalen Flughafen SSR, 150 Meter zu Menschenansammlungen und dicht besiedelten Gebieten. Öffentliche Strände benötigen eine eigene Genehmigung, Meeresschutzzonen für Wale und Delfine sind strikt tabu.", "Vor jedem Freizeitflug ist eine Einzelerlaubnis der DCA nötig, deren Bearbeitung nach Angaben Betroffener bis zu drei Monate dauern kann – vereinzelt wurde bei Vorlage eines ausländischen Registrierungsnachweises aber auch schneller genehmigt.", "Bei Verstößen drohen empfindliche Bußgelder und bis zu zwölf Monate Haft. Für Kurzzeit-Touristen ist Mauritius damit administrativ eines der aufwendigeren Ziele in dieser Region."] },
  { code: "MX", name: "Mexiko", maxAltitude: 120, registrationRequired: true, insuranceRequired: true, sourceUrl: "https://www.gob.mx/afac/acciones-y-programas/rpas-drones", rules: ["In Mexiko regelt die Luftfahrtbehörde AFAC den Drohnenbetrieb nach Gewichtsklassen: Sehr leichte Drohnen unterliegen nur wenigen Einschränkungen, ab etwa 2 Kilogramm sind Registrierung und ein zertifizierter Betreiber erforderlich, ab 25 Kilogramm zusätzlich ein Lufttüchtigkeitszeugnis.", "Für den gewerblichen Betrieb ist eine Haftpflichtversicherung gegen Schäden an Dritten vorgeschrieben.", "Wichtig für Reisende: An archäologischen Stätten wie Chichén Itzá oder Tulum ist Drohnenfliegen ohne gesonderte Genehmigung des Denkmalschutzamts INAH verboten – ein Umstand, der viele Touristen überrascht, da diese Orte zu den beliebtesten Fotomotiven zählen.", "Ohne besondere Genehmigung liegt die maximale Flughöhe bei rund 120 Metern über Grund."] },
  { code: "MC", name: "Monaco", maxAltitude: null, registrationRequired: true, insuranceRequired: true, sourceUrl: "https://flysafe.gouv.mc/login", rules: ["Monaco hat eine eigene Luftfahrtbehörde (Direction de l'Aviation Civile) und folgt nicht automatisch den EU-Regeln. Für jede Drohne ab 100 Gramm brauchst du eine jährlich zu erneuernde Betriebsgenehmigung – zusätzlich musst du jeden einzelnen Flug vorab über die Plattform FlySafe anmelden und genehmigen lassen.", "Eine Haftpflichtversicherung musst du bereits bei der Antragstellung nachweisen.", "Wegen der geringen Fläche und hohen Dichte ist Fliegen in Monaco stark eingeschränkt: Über dem Fürstenpalast sowie im Umkreis von 150 Metern um den Hubschrauberlandeplatz ist es grundsätzlich verboten, auch für sehr leichte Drohnen.", "Eine pauschale Flughöhengrenze wie in der EU gibt es nicht – die zulässige Höhe wird für jeden Flug einzeln in der Genehmigung festgelegt."] },
  { code: "ME", name: "Montenegro", maxAltitude: 120, registrationRequired: true, insuranceRequired: true, sourceUrl: "https://www.caa.me/en/pilot-examination-and-registration-drone-operators", rules: ["In Montenegro registrierst du dich als Drohnenbetreiber kostenlos über dron.caa.me bei der Zivilluftfahrtbehörde CAA – Pflicht ab 250 Gramm Startgewicht oder bei jeder Drohne mit einem Sensor, der personenbezogene Daten erfassen kann. Die Registrierung gilt zwei Jahre.", "Eine Haftpflichtversicherung ist in Montenegro für jeden Drohnenbetrieb gesetzlich vorgeschrieben, auch für ausländische Piloten.", "Seit Juli 2024 hat Montenegro sein Regelwerk vollständig an die EU-Drohnenverordnung angeglichen: Gültige EU-Kompetenznachweise (A1/A3 oder A2) werden anerkannt, du musst dich aber trotzdem lokal registrieren und lokal versichert sein. Mindestalter: 16 Jahre.", "In der offenen Kategorie gilt eine maximale Flughöhe von 120 Metern über Grund."] },
  { code: "MM", name: "Myanmar", maxAltitude: null, registrationRequired: true, insuranceRequired: false, sourceUrl: "https://travel.state.gov/content/travel/en/traveladvisories/traveladvisories/burma-travel-advisory.html", rules: ["Für Myanmar besteht seit dem Militärputsch 2021 ein anhaltender bewaffneter Konflikt zwischen Regierungstruppen und oppositionellen bewaffneten Gruppen, den das US-Außenministerium mit Stand Mai 2026 auf der höchsten Warnstufe 4 ('Do not travel') einstuft; dazu zählen laut Reisehinweis unter anderem monatlich mehrere Sprengstoffanschläge allein in Rangun sowie Landminen im gesamten Land.", "Die Einfuhr und der Betrieb von Drohnen ohne vorherige behördliche Genehmigung sind in Myanmar ausdrücklich untersagt und wurden zuletzt mit Haftstrafen geahndet, unter anderem gegen ausländische Reisende, die wegen eines Drohnenflugs über einem Park zu einem Jahr Gefängnis verurteilt wurden.", "Von der Mitnahme und dem Betrieb einer Drohne in Myanmar wird angesichts der Sicherheitslage und der drohenden strafrechtlichen Konsequenzen derzeit grundsätzlich abgeraten."] },
  { code: "NA", name: "Namibia", maxAltitude: 45, registrationRequired: true, insuranceRequired: false, sourceUrl: "https://www.ncaa.com.na/", rules: ["In Namibia ist für jede Drohne eine schriftliche Genehmigung der Luftfahrtbehörde NCAA nötig. Für Hobbynutzer ist eine Versicherung nicht vorgeschrieben, wird aber empfohlen, für gewerbliche Nutzung dagegen schon.", "Ohne Sondergenehmigung liegt die maximale Flughöhe bei nur 45 Metern (150 Fuß) – deutlich niedriger als der sonst verbreitete Standard.", "Nationalparks und Naturreservate, darunter der bekannte Etosha-Nationalpark, sind generell für Drohnen gesperrt; hier ist zusätzlich eine Genehmigung des Umweltministeriums nötig. Um Flugplätze gilt eine 10-Kilometer-Sperrzone.", "Der entscheidende Haken für Reisende: Anträge müssen mindestens 60 Tage vor der Einreise gestellt werden.", "Für eine spontan geplante Reise ist das damit faktisch nicht umsetzbar – wer in Namibia wirklich mit der eigenen Drohne fliegen will, muss das lange vor Buchung des Fluges einplanen."] },
  { code: "NP", name: "Nepal", maxAltitude: 100, registrationRequired: true, insuranceRequired: false, sourceUrl: "https://caanepal.gov.np/storage/app/media/drone/UAS%20Requirement%20final.pdf", rules: ["Die Zivilluftfahrtbehörde CAAN erlaubt Drohnenflüge unter Standardbedingungen bis zu einer Höhe von 100 Metern (rund 328 Fuß) über Grund im unkontrollierten Luftraum; höhere Flüge erfordern eine gesonderte Genehmigung sowie eine mindestens 24 Stunden im Voraus eingereichte NOTAM-Meldung.", "Drohnen werden nach Startgewicht in vier Risikokategorien eingeteilt (unter 250 Gramm, 250 Gramm bis 2 Kilogramm, 2 bis 25 Kilogramm sowie über 25 Kilogramm), wobei das zulässige Gesamtgewicht generell auf 25 Kilogramm begrenzt ist.", "Für jede Drohne ist eine Registrierung bei der CAAN mit dem Formular RPA/Form/01 vorgeschrieben, wofür Personaldokumente, technische Gerätedaten sowie Kauf- beziehungsweise Zollbelege einzureichen sind; nach erfolgreicher Prüfung wird eine Unique Identification Number (UIN) vergeben, die sichtbar am Gerät angebracht werden muss.", "Eine gesetzliche Versicherungspflicht ist im offiziellen CAAN-Regelwerk zu den UAS-Anforderungen nicht dokumentiert, weshalb hier keine Pflicht angenommen wird; unabhängig davon verlangen viele Trekking-Regionen zusätzliche lokale Genehmigungen.", "Flüge sind unter anderem innerhalb von 5 Kilometern um Flughäfen ohne gesonderte Freigabe, näher als 30 Meter an nicht einwilligenden Personen sowie über dicht besiedelten Gebieten und in staatlich ausgewiesenen Sperrzonen untersagt; Nachtflüge sind grundsätzlich nicht erlaubt.", "Für ausländische Touristen sind im Regelwerk keine gesonderten Erleichterungen ausgewiesen; in der Praxis berichten Reisende von einem aufwendigen, oft mehrtägigen Genehmigungsprozess in Kathmandu, der eine nepalesische SIM-Karte, lokale Kontakte oder die Unterstützung einer Trekking-Agentur erfordern kann, da die Antragstellung nicht vollständig online möglich ist."] },
  { code: "NZ", name: "Neuseeland", maxAltitude: 120, registrationRequired: false, insuranceRequired: false, sourceUrl: "https://www.aviation.govt.nz/drones/regulations/part-101-rules-for-drones/", rules: ["In Neuseeland ist für Freizeitdrohnen keine Luftfahrzeug-Registrierung nötig, eine Versicherung ist ebenfalls nicht gesetzlich vorgeschrieben (aber empfohlen). Die maximale Flughöhe liegt bei 120 Metern (400 Fuß), zu Flugplätzen sind ohne Freigabe mindestens 4 Kilometer Abstand einzuhalten; zudem brauchst du die Zustimmung von Grundstückseigentümern und überflogenen Personen.", "Wichtiger Sonderfall: Auf DOC-Naturschutzland (das betrifft praktisch alle Nationalparks) ist für jeden Start, jede Landung oder jeden Schwebeflug ein Permit der Naturschutzbehörde DOC nötig. Die Flächen sind in drei Zonen eingeteilt: Grün (automatische Online-Genehmigung, rund 180 NZD), Orange (Einzelfallprüfung, deutlich teurer) und Rot (nur sehr selten genehmigt).", "Zu speziellen Regeln für Māori-Kulturstätten (etwa Marae oder Urgräberstätten) ließ sich auf den offiziellen DOC-Seiten keine zentral dokumentierte, konkrete Verbotsliste finden – die Zonen-Einteilung berücksichtigt kulturelle Werte generell, Details können aber lokal/je Region unterschiedlich sein. Vor Ort im Zweifel nachfragen.", "Bei Verstößen werden in Sekundärquellen Bußgelder ab rund 500 NZD genannt, in Nationalparks mit möglicher Beschlagnahmung der Drohne – offiziell bezifferte Beträge waren nicht auffindbar.", "Für Touristen ist Neuseeland außerhalb von DOC-Land unkompliziert; auf Naturschutzland (also den meisten der klassischen Sehenswürdigkeiten) muss vorher ein Online-Permit eingeholt werden, was in der grünen Zone aber sofort möglich ist."] },
  { code: "NI", name: "Nicaragua", maxAltitude: null, registrationRequired: false, insuranceRequired: false, sourceUrl: "https://www.inac.gob.ni/drones/", rules: ["Wichtiger Hinweis: In Nicaragua ist der Besitz und Betrieb von Drohnen durch Privatpersonen seit einem Gesetz von Dezember 2024 grundsätzlich untersagt – Ausnahmen genehmigt ausschließlich das Präsidialamt, etwa für Forschung oder Rettungseinsätze.", "Ein reguläres Registrierungsverfahren für private Nutzer existiert nicht.", "Für Reisende heißt das in der Praxis: Nimm keine private Drohne mit nach Nicaragua – es gibt aktuell keinen legalen Weg für Touristen, sie dort zu nutzen."] },
  { code: "NL", name: "Niederlande", maxAltitude: 120, registrationRequired: true, insuranceRequired: false, sourceUrl: "https://www.rdw.nl/drone", rules: ["Wenn du in den Niederlanden wohnst, registrierst du dich beim RDW (rdw.nl/drone) – Pflicht ab 250 Gramm Startgewicht oder bei jeder Drohne mit Kamera bzw. anderer Sensorik, auch wenn sie leichter ist. Für die Registrierung brauchst du DigiD (Privatpersonen) oder eHerkenning (Unternehmen).", "Registriert wird nur einmal, und zwar in dem EASA-Staat, in dem du deinen Wohnsitz hast – zum EASA-Raum gehören die EU-Länder plus Island, Liechtenstein, Norwegen und die Schweiz. Die Betreibernummer gilt dann im gesamten EASA-Raum: Wer bereits in einem anderen EASA-Land registriert ist, braucht in den Niederlanden keine zweite Registrierung. Nur wer außerhalb des EASA-Raums wohnt, registriert sich in dem EASA-Staat, in dem er zuerst fliegt.", "Eine Haftpflichtversicherung ist in den Niederlanden erst ab einem Startgewicht von 20 Kilogramm gesetzlich vorgeschrieben; für die meisten handelsüblichen Drohnen darunter wird sie zwar empfohlen, ist aber keine Pflicht.", "Für die Flugvorbereitung bietet die Aufsichtsbehörde ILT die App GoDrone als offizielles Werkzeug zur Prüfung von Flugverbotszonen an. Für den alleinigen Flug in der offenen Kategorie gilt ein Mindestalter von 16 Jahren.", "In der offenen Kategorie gilt eine maximale Flughöhe von 120 Metern über Grund, wie EU-weit einheitlich geregelt."] },
  { code: "NG", name: "Nigeria", maxAltitude: null, registrationRequired: true, insuranceRequired: false, sourceUrl: "https://ncaa.gov.ng/documents/advisory-circulars/guidelines-for-the-operations-of-remotely-piloted-aircraft-systemsunmanned-aerial-vehicle-rpasuav-in-nigeria/", rules: ["Nigeria hat eines der sicherheitsbehördlich strengsten Drohnensysteme in dieser Region: Registriert wird zwar bei der Luftfahrtbehörde NCAA über ein Online-Portal, zusätzlich ist aber für jede Drohne eine gesonderte Sicherheitsfreigabe des nationalen Sicherheitsberaters (ONSA) sowie ein individuelles Endnutzer-Zertifikat nötig.", "Zu einer generellen Versicherungspflicht für Freizeitnutzer liegen keine eindeutigen Angaben vor; bei kommerziellen Anträgen wird sie teils verlangt.", "Eine offizielle Angabe zur maximalen Flughöhe war in keiner ausgewerteten Quelle zu finden.", "Im Mai 2026 hat die NCAA ein neues digitales Portal gestartet, das unter anderem die Freizeitkategorie eigens regeln soll – wie genau sich das für Touristen konkret auswirkt, war zum Zeitpunkt der Recherche noch nicht abschließend zu klären. Verstärkte Sicherheitskontrollen in Lagos, Abuja und Port Harcourt wurden 2026 zusätzlich berichtet.", "Bei Verstößen drohen laut Behördenankündigung Bußgelder, Haft und Beschlagnahmung.", "Angesichts der Einbindung der Sicherheitsbehörde ist Nigeria für kurzfristige Touristen praktisch eine hohe Hürde – ein Antrag lohnt sich nur mit viel Vorlauf und Geduld."] },
  { code: "KP", name: "Nordkorea", maxAltitude: null, registrationRequired: false, insuranceRequired: false, sourceUrl: "https://en.wikipedia.org/wiki/Tourism_in_North_Korea", rules: ["Wichtiger Hinweis: Nordkorea-Reisen sind grundsätzlich nur als geführte Gruppenreise über einen der wenigen lizenzierten Reiseveranstalter möglich, individuelles Reisen ohne durchgehende staatliche Begleitung ist nicht erlaubt.", "Drohnen sind dabei laut übereinstimmenden Angaben mehrerer etablierter Nordkorea-Reiseveranstalter vollständig verboten. Eine öffentlich einsehbare, offizielle nordkoreanische Rechtsgrundlage dazu gibt es nicht, aber das Verbot wird von der Reisebranche durchgängig bestätigt: Wer versucht, eine Drohne einzuführen, muss mit Konfiszierung am Zoll rechnen.", "Auch andere Foto-/Kameraausrüstung wird streng kontrolliert – Kameras mit GPS-Funktion sind ebenfalls verboten, sehr große Objektive und professionelles Equipment werden abgeraten, da sie mit journalistischer Ausrüstung verwechselt werden könnten (Journalisten dürfen nicht als Touristen einreisen). Auch ohne Drohne ist Fotografieren nur mit Erlaubnis der Reisebegleitung erlaubt.", "Eine feste Angabe zu Flughöhe, Registrierung oder Versicherung existiert mangels legalem Betrieb nicht.", "Für eine Nordkorea-Reise gilt daher eindeutig: Drohne zu Hause lassen. Es gibt keinen legalen Weg, dort zu fliegen, und ein Mitführversuch riskiert mindestens den Verlust des Geräts am Zoll."] },
  { code: "MK", name: "Nordmazedonien", maxAltitude: 100, registrationRequired: true, insuranceRequired: true, sourceUrl: "https://drone.gov.mk/?lang=en", rules: ["In Nordmazedonien musst du deine Drohne ab 0,5 Kilogramm Startgewicht bei der Zivilluftfahrtbehörde registrieren – sowohl für private als auch für gewerbliche Nutzung.", "Eine Haftpflichtversicherung für Schäden am Boden ist für jede Nutzung Pflicht, in bestimmten Zonen zusätzlich eine erweiterte Transporthaftpflicht.", "Flüge musst du mindestens 24 Stunden vorher anmelden. Entlang der Landesgrenzen gilt eine Sperrzone von 3 Kilometern.", "Registrierte Betreiber dürfen im Sichtflug bis 100 Meter Höhe und 500 Meter horizontaler Entfernung fliegen; ohne Registrierung bzw. Lizenz liegt die Grenze in ausgewiesenen Gebieten nur bei 50 Metern."] },
  { code: "NO", name: "Norwegen", maxAltitude: 120, registrationRequired: true, insuranceRequired: true, sourceUrl: "https://www.luftfartstilsynet.no/droner/", rules: ["In Norwegen registrierst du dich als Drohnenbetreiber über flydrone.no bei der Luftfahrtbehörde Luftfartstilsynet – Pflicht ab 250 Gramm Startgewicht oder bei jeder Drohne mit Kamera, unabhängig vom Gewicht. Für Privatpersonen kostet die Registrierung 230, für Organisationen 1.500 Norwegische Kronen pro Jahr.", "Registriert wird nur einmal, und zwar in dem EASA-Staat, in dem du deinen Wohnsitz hast – zum EASA-Raum gehören die EU-Länder plus Island, Liechtenstein, Norwegen und die Schweiz. Die Betreibernummer gilt dann im gesamten EASA-Raum: Wer bereits in einem anderen EASA-Land registriert ist, braucht in Norwegen keine zweite Registrierung. Nur wer außerhalb des EASA-Raums wohnt, registriert sich in dem EASA-Staat, in dem er zuerst fliegt.", "Eine Haftpflichtversicherung mit einer Mindestdeckung von umgerechnet rund 750.000 Sonderziehungsrechten ist in Norwegen für praktisch jeden Drohnenbetrieb vorgeschrieben – eine deutliche Verschärfung gegenüber der EU-Grundregel, die Versicherung erst ab 20 Kilogramm verlangt. Ausgenommen sind nur als Spielzeug gekennzeichnete Drohnen und kameralose Modelle unter 250 Gramm.", "Obwohl Norwegen kein EU-Mitglied ist, wendet das Land die EASA-Vorschriften über das EWR-Abkommen direkt an: In der offenen Kategorie gilt eine maximale Flughöhe von 120 Metern, gemessen ab dem nächstgelegenen Punkt der Grund- oder Wasseroberfläche."] },
  { code: "OM", name: "Oman", maxAltitude: 120, registrationRequired: true, insuranceRequired: true, sourceUrl: "https://www.caa.gov.om/files/publications/regulation-governing-unmanned-aircraft-systems-drones.pdf", rules: ["In Oman muss jede Drohne bei der Zivilluftfahrtbehörde CAA registriert werden, seit Anfang 2026 über das digitale System AirPortal bzw. die App Sarab. Ausgenommen sind nur Spielzeug- und Mikro-Drohnen unter 250 Gramm ohne Kamera, die auf maximal 100 Meter Höhe begrenzt sind.", "Für registrierte Drohnen ist eine Haftpflichtversicherung für die gesamte Gültigkeitsdauer der Lizenz gesetzlich vorgeschrieben.", "Die maximale Flughöhe liegt bei 120 Metern über Grund, geflogen werden darf nur bei Tageslicht.", "Sperrzonen gelten in rund 5 Kilometern Umkreis um Flughäfen und Seehäfen sowie um besonders geschützte Orte; dicht besiedelte Gebiete dürfen ohne gesonderte Genehmigung nicht überflogen werden, ebenso wenig Konvois oder laufende Polizei-/Feuerwehreinsätze. Zu Unbeteiligten ist ein Mindestabstand von 30 Metern einzuhalten.", "Ausländische Betreiber sollten für die nötige Genehmigung mindestens 15 Tage vor dem geplanten Flug einplanen, das Mindestalter liegt bei 18 Jahren.", "Bei Verstößen drohen Bußgelder zwischen 200 und 600 OMR, für unlizenzierten Betrieb 500 OMR, bei Wiederholung das Doppelte. Im Vergleich zu vielen Nachbarländern ist Oman insgesamt klarer und zugänglicher reguliert – aber eben nicht genehmigungsfrei, wer ohne Registrierung fliegt, riskiert die genannten Strafen."] },
  { code: "PK", name: "Pakistan", maxAltitude: 60, registrationRequired: true, insuranceRequired: true, sourceUrl: "https://www.na.gov.pk/uploads/documents/1628242813_323.pdf", rules: ["Für die am häufigsten touristisch genutzten, leichten Drohnenklassen (unter rund 2 Kilogramm Startgewicht) liegt die maximale Flughöhe nach der bisherigen Klassifizierung der Pakistan Civil Aviation Authority (PCAA) bei etwa 60 Metern (200 Fuß), schwerere Klassen dürfen bis zu 120 Meter (400 Fuß) fliegen; da das Regelwerk seit 2020 mehrfach überarbeitet wurde (zuletzt mit den Civil Unmanned Aircraft Rules 2024), sollten Piloten die aktuell gültigen Werte vor Reiseantritt direkt bei der PCAA prüfen.", "Drohnen werden nach Startgewicht in vier bis fünf Klassen eingeteilt, wobei bereits Fluggeräte ab 250 Gramm einer Registrierungspflicht unterliegen, ab etwa 10 Kilogramm eine Fernpilotenlizenz nötig wird und beim Import schwererer Klassen zusätzlich eine Freigabe des Verteidigungsministeriums erforderlich ist.", "Eine Registrierung im pakistanischen Luftfahrzeugregister ist für In- und Ausländer gleichermaßen vorgeschrieben; für Touristen ist der Prozess eine erhebliche praktische Hürde, da mehrere Quellen eine Bearbeitungsdauer von bis zu 60 Tagen sowie eine Sicherheitsüberprüfung durch Innen- beziehungsweise Verteidigungsministerium nennen, was eine spontane Mitnahme der Drohne im Urlaubsgepäck praktisch ausschließt.", "Bei der Einreise berichten Reisende wiederholt von Problemen am Zoll bis hin zur vorübergehenden oder dauerhaften Beschlagnahmung nicht angemeldeter Drohnen, weshalb eine vorherige Klärung mit der PCAA beziehungsweise ein 'No Objection Certificate' dringend angeraten wird.", "Für Drohnenpiloten ab 18 Jahren gilt eine Versicherungspflicht.", "Sperrzonen bestehen unter anderem im Umkreis von rund 18,5 Kilometern um Flughäfen, 2 Kilometern um Landesgrenzen sowie um militärische und sicherheitsrelevante Einrichtungen; Verstöße gegen die Registrierungspflicht können mit Geldstrafen bis 100.000 pakistanische Rupien zuzüglich 10.000 Rupien pro Tag fortgesetzten Verstoßes geahndet werden."] },
  { code: "PA", name: "Panama", maxAltitude: null, registrationRequired: true, insuranceRequired: true, sourceUrl: "https://www.aeronautica.gob.pa", rules: ["In Panama musst du deine Drohne ab 250 Gramm bei der Luftfahrtbehörde AAC registrieren lassen – dafür ist eine persönliche Vorstellung mit dem Gerät im AAC-Gebäude in Albrook nötig, du bekommst danach eine Plakette.", "Ab dieser Gewichtsklasse ist auch eine Haftpflichtversicherung gegen Schäden an Dritten Teil der Betriebsgenehmigung.", "Für Reisende gilt: Eine einzelne Drohne wird meist als persönliches Reisegepäck behandelt, mehrere Geräte oder Originalverpackungen können vom Zoll dagegen als gewerblicher Import mit Einfuhrsteuer eingestuft werden. Ersatzakkus gehören ausschließlich ins Handgepäck. Rund um Feiertage verhängt die AAC gelegentlich kurzfristige, landesweite Flugverbote – ein Blick auf aktuelle AAC-Meldungen lohnt sich vor jedem Flug."] },
  { code: "PG", name: "Papua-Neuguinea", maxAltitude: 120, registrationRequired: true, insuranceRequired: false, sourceUrl: "https://casapng.gov.pg/", rules: ["In Papua-Neuguinea müssen Drohnen ab 250 Gramm bei der Luftfahrtbehörde CASA PNG registriert werden. Eine Versicherung ist in den verfügbaren Quellen nicht spezifiziert.", "Die maximale Flughöhe liegt bei 120 Metern (400 Fuß). Das Besondere: Für die \"Offene Kategorie\" (Drohnen unter 10 Kilogramm, mit durchgehender Sichtverbindung, innerhalb der Höhengrenze und mit Abstand zu Flugplätzen) ist über die Registrierung hinaus keine zusätzliche Einzelgenehmigung nötig – damit ist Papua-Neuguinea von den in diesem Batch recherchierten pazifischen Inselstaaten der mit dem klarsten genehmigungsfreien Weg für den Standardfall.", "Sperrzonen gelten für ausgewiesene Sperrgebiete und \"Low Flying Zones\", für Militär- und Sperrgebiete ist zusätzlich die Zustimmung der jeweils verantwortlichen Stelle nötig, im Umkreis von etwa 5,5 Kilometern (3 nautische Meilen) um kontrollierte Flugplätze braucht es eine Freigabe der Flugsicherung.", "Zu konkreten Bußgeldern bei Verstößen liegen keine belastbaren Angaben vor. Eine drohnenspezifische Sicherheitswarnung über die allgemeine Reisesicherheitslage hinaus wurde nicht gefunden.", "Für Touristen mit einer typischen kleinen Freizeitdrohne unter 10 Kilogramm ist ein regelkonformer Flug damit vergleichsweise unkompliziert möglich, sobald die Registrierung erledigt ist."] },
  { code: "PY", name: "Paraguay", maxAltitude: null, registrationRequired: true, insuranceRequired: false, sourceUrl: "https://www.dinac.gov.py/Seguridad_Operacional/docs/DINAC_R1103_RPAS-2017.pdf", rules: ["In Paraguay reguliert die Dirección Nacional de Aeronáutica Civil (DINAC) den Betrieb ferngesteuerter Luftfahrzeuge (RPA) auf Grundlage des Reglaments DINAC R 1103 aus dem Jahr 2017.", "Drohnen werden nach Startgewicht in drei Klassen unterteilt: klein bis 10 Kilogramm, mittel zwischen 10 und 150 Kilogramm sowie groß über 150 Kilogramm; laut Reglament ist grundsätzlich jedes RPA im nationalen Luftfahrzeugregister einzutragen, unabhängig von der Gewichtsklasse.", "Eine feste maximale Flughöhe schreibt das Reglament nicht vor; stattdessen legt DINAC die zulässige Höhe im Rahmen der jeweiligen Genehmigung im Einzelfall fest, weshalb hier keine verlässliche Meterangabe gemacht werden kann.", "Für gewerbliche Einsätze in der Nähe internationaler Flughäfen ist laut aktuellen Gebührenregelungen eine vorherige Anfrage per E-Mail an DINAC sowie teils eine Gebühr erforderlich, während rein privater Freizeitflug auf eigenem oder genehmigtem Grund derzeit gebührenfrei bleibt.", "Nach Presseberichten aus dem Jahr 2024 wird im paraguayischen Parlament zudem eine neue, verpflichtende Drohnenregistrierung mit Versicherungspflicht diskutiert; eine solche Pflicht ist aktuell aber noch nicht in Kraft, weshalb Besucher aktuelle Informationen direkt bei DINAC einholen sollten."] },
  { code: "PE", name: "Peru", maxAltitude: 152, registrationRequired: true, insuranceRequired: false, sourceUrl: "https://www.gob.pe/institucion/mtc/noticias/1097751-mtc-simplifica-el-tramite-para-registrar-un-dron-de-manera-automatica", rules: ["Seit Mai 2026 gilt in Peru ein neues RPAS-Reglement der Luftfahrtbehörde DGAC (Teil des Verkehrsministeriums MTC): Drohnen der Kategorien Open und Specific müssen innerhalb von 30 Werktagen nach Anschaffung bei der DGAC registriert werden, die Zulassung ist danach unbefristet gültig.", "Rein private Freizeitflüge mit einer Startmasse unter 2 Kilogramm sind von den meisten Auflagen der neuen Verordnung ausgenommen; ab dieser Grenze bzw. bei gewerblicher Nutzung sind Registrierung, eine Haftpflichtversicherung gegen Schäden an Dritten und je nach Einsatzart eine vorläufige RPAS-Pilotenakkreditierung der DGAC vorgeschrieben.", "Verboten sind Flüge in kontrolliertem Luftraum, in Flughafennähe ohne gesonderte DGAC-Freigabe sowie über Militäranlagen und Naturschutzgebieten; besonders wichtig für Reisende ist das Drohnenverbot über Machu Picchu und weiteren archäologischen Stätten, wo Ausnahmen praktisch nur mit gesonderter Genehmigung des Kulturministeriums möglich sind.", "Die maximale Flughöhe liegt bei rund 152 Metern (500 Fuß) über Grund, außer beim direkten Überfliegen eines Hindernisses.", "Für ausländische Piloten mit gewerblichem Vorhaben besteht grundsätzlich die Möglichkeit, eine im Ausland erworbene Pilotenlizenz bei der DGAC anerkennen (konvalidieren) zu lassen; für reines Freizeitfliegen unterhalb der 2-Kilogramm-Grenze ist das nicht nötig."] },
  { code: "PL", name: "Polen", maxAltitude: 120, registrationRequired: true, insuranceRequired: true, sourceUrl: "https://ulc.gov.pl/drony", rules: ["In Polen registrierst du dich als Drohnenbetreiber über drony.gov.pl bei der Zivilluftfahrtbehörde ULC – Pflicht ab 250 Gramm Startgewicht oder bei jeder Drohne mit einem Sensor, der personenbezogene Daten erfassen kann.", "Registriert wird nur einmal, und zwar in dem EASA-Staat, in dem du deinen Wohnsitz hast – zum EASA-Raum gehören die EU-Länder plus Island, Liechtenstein, Norwegen und die Schweiz. Die Betreibernummer gilt dann im gesamten EASA-Raum: Wer bereits in einem anderen EASA-Land registriert ist, braucht in Polen keine zweite Registrierung. Nur wer außerhalb des EASA-Raums wohnt, registriert sich in dem EASA-Staat, in dem er zuerst fliegt.", "Seit November 2025 ist eine Haftpflichtversicherung in Polen bereits ab 250 Gramm Startgewicht vorgeschrieben, mit einer Mindestdeckungssumme von 50.000 Sonderziehungsrechten – zuvor galt wie EU-weit üblich erst die 20-Kilogramm-Grenze.", "In der offenen Kategorie gilt eine maximale Flughöhe von 120 Metern über Grund; bei Hindernissen über 120 Metern ist mit Zustimmung des Eigentümers und mindestens 50 Metern horizontalem Abstand ein Zuschlag von bis zu 15 Metern erlaubt."] },
  { code: "PT", name: "Portugal", maxAltitude: 120, registrationRequired: true, insuranceRequired: true, sourceUrl: "https://uas.anac.pt/anac-registry/", rules: ["In Portugal registrierst du dich als Drohnenbetreiber über das offizielle Register der Luftfahrtbehörde ANAC (uas.anac.pt) – Pflicht bei jeder Drohne mit Sensor unabhängig vom Gewicht, sowie ab 250 Gramm ohne Sensor oder bei mehr als 80 Joule Aufprallenergie.", "Registriert wird nur einmal, und zwar in dem EASA-Staat, in dem du deinen Wohnsitz hast – zum EASA-Raum gehören die EU-Länder plus Island, Liechtenstein, Norwegen und die Schweiz. Die Betreibernummer gilt dann im gesamten EASA-Raum: Wer bereits in einem anderen EASA-Land registriert ist, braucht in Portugal keine zweite Registrierung. Nur wer außerhalb des EASA-Raums wohnt, registriert sich in dem EASA-Staat, in dem er zuerst fliegt.", "Eine Haftpflichtversicherung ist in Portugal für jede gewerbliche Nutzung sowie für private Drohnen ab 900 Gramm vorgeschrieben; nur rein private Leichtdrohnen darunter sind ausgenommen.", "Die ANAC vergibt bei der Registrierung eine Kennung, die sichtbar an der Drohne angebracht werden muss.", "In der offenen Kategorie gilt eine maximale Flughöhe von 120 Metern über Grund, wie EU-weit einheitlich geregelt."] },
  { code: "RW", name: "Ruanda", maxAltitude: null, registrationRequired: true, insuranceRequired: false, sourceUrl: "https://www.caa.gov.rw/drones", rules: ["In Ruanda müssen Drohnen bei der Luftfahrtbehörde RCAA registriert werden – Ausländer können das aber nicht selbst tun. Nur ruandische Staatsbürger, Residenten oder Firmen können eine Drohne stellvertretend registrieren, was für Touristen ohne lokalen Kontakt ein echtes Hindernis ist.", "Freizeitbetrieb ist offiziell nur innerhalb eines von der RCAA zugelassenen, registrierten Drohnenclubs erlaubt.", "Bei der Einreise muss jede Drohne der Nationalpolizei am Grenzübergang deklariert werden, sonst drohen Strafen. Für sicherheitsrelevante Gebiete ist zusätzlich eine Genehmigung von Polizei oder Militär nötig.", "Es gibt zwei Genehmigungsarten – ein kurzfristiges Activity Permit (mehrere Wochen Bearbeitungszeit) und ein langfristiges Operator Certificate –, beide mit spürbarem Vorlauf.", "Sperrzonen gelten in 10 Kilometern um Flughäfen sowie um Regierungs- und Militäreinrichtungen, Nachtflüge sind nicht erlaubt.", "Für Kurzzeit-Touristen ist der Aufwand insgesamt hoch: fremde Registrierung nötig, mehrere Wochen Vorlauf, kein spontaner Freizeitflug."] },
  { code: "RO", name: "Rumänien", maxAltitude: 120, registrationRequired: true, insuranceRequired: false, sourceUrl: "https://www.caa.ro/ro/pages/legislatie-drone", rules: ["In Rumänien registrierst du dich als Drohnenbetreiber über das Portal uas.caa.ro bei der Zivilluftfahrtbehörde AACR – Pflicht ab 250 Gramm Startgewicht oder bei jeder Drohne mit Kamera bzw. anderem Sensor. Selbstgebaute Drohnen unter 250 Gramm in der Unterkategorie A1 sind ausgenommen.", "Registriert wird nur einmal, und zwar in dem EASA-Staat, in dem du deinen Wohnsitz hast – zum EASA-Raum gehören die EU-Länder plus Island, Liechtenstein, Norwegen und die Schweiz. Die Betreibernummer gilt dann im gesamten EASA-Raum: Wer bereits in einem anderen EASA-Land registriert ist, braucht in Rumänien keine zweite Registrierung. Nur wer außerhalb des EASA-Raums wohnt, registriert sich in dem EASA-Staat, in dem er zuerst fliegt.", "Eine Haftpflichtversicherung ist in Rumänien erst ab einem Startgewicht von 20 Kilogramm gesetzlich vorgeschrieben – die EU-Grundregel gilt ohne nationale Verschärfung.", "Flüge unterhalb von 3.000 Metern über Bukarest außerhalb ausgewiesener Korridore sowie Luftaufnahmen benötigen eine gesonderte Genehmigung des Verteidigungsministeriums.", "In der offenen Kategorie gilt eine maximale Flughöhe von 120 Metern über Grund, wie EU-weit einheitlich geregelt."] },
  { code: "RU", name: "Russland", maxAltitude: null, registrationRequired: true, insuranceRequired: false, sourceUrl: "https://favt.gov.ru", rules: ["Wichtiger Hinweis: In weiten Teilen des europäischen Russlands gelten wegen des Kriegs großflächige, häufig kurzfristig verhängte Flugverbote für zivile Drohnen – seit Juni 2026 etwa über Moskau und mehreren umliegenden Regionen bis in große Höhen, zeitlich unbefristet (\"bis auf Weiteres\"). Diese Lage ändert sich laufend.", "Die reguläre, in Friedenszeiten geltende Registrierungspflicht bei der Luftfahrtbehörde Rosaviatsia (für Drohnen etwa zwischen 0,25 und 30 Kilogramm) besteht formal weiter, ersetzt aber nicht die Prüfung lokaler, oft sehr kurzfristiger Flugverbote.", "Verlässliche, aktuelle Informationen zu erlaubten Flughöhen oder einer Versicherungspflicht sind derzeit nicht öffentlich zugänglich. Von Freizeitflügen in oder nahe den betroffenen Regionen ist dringend abzuraten – informiere dich unmittelbar vor Ort."] },
  { code: "ZM", name: "Sambia", maxAltitude: 120, registrationRequired: true, insuranceRequired: true, sourceUrl: "https://drone-laws.com/drone-laws-in-zambia/", rules: ["In Sambia ist eine CAA-Registrierung für rein private Freizeitdrohnen unter 1,5 Kilogramm formal nicht nötig – für ausländische Besucher gilt aber grundsätzlich die strengere Registrierungspflicht, mit spürbaren Gebühren für Inspektion und Genehmigungsschreiben.", "Für Touristen ist eine Haftpflichtversicherung ebenso Pflicht wie eine gültige Pilotenlizenz.", "Die maximale Flughöhe liegt bei 120 Metern und darf zusätzlich die Höhe der höchsten Struktur im Umkreis von 300 Metern nicht überschreiten. Um Flughäfen gilt eine 10-Kilometer-Sperrzone, Start und Landung auf öffentlichen Straßen sind verboten.", "Am aufwendigsten: Touristen müssen sich bei jedem Flug von einem Inspektor der Luftfahrtbehörde begleiten lassen – inklusive Kostenübernahme für dessen Unterkunft, Transport und Tagegeld –, zusätzlich ist eine Freigabe der Luftwaffe nötig.", "Damit ist Sambia für kurzfristige Touristen praktisch kein gangbarer Weg für die eigene Drohne; wer dort unbedingt Luftaufnahmen machen möchte, sollte eher lokale Anbieter beauftragen."] },
  { code: "SA", name: "Saudi-Arabien", maxAltitude: 120, registrationRequired: true, insuranceRequired: false, sourceUrl: "https://uas.gaca.gov.sa", rules: ["Saudi-Arabien hatte 2015 zunächst ein komplettes Drohnenverbot verhängt und öffnet den Luftraum seither nur schrittweise wieder: Jede Drohne ab 250 Gramm muss bei der Luftfahrtbehörde GACA über das Portal uas.gaca.gov.sa registriert werden.", "Die Registrierung läuft über das staatliche Identifikationssystem Nafath, das an eine saudische Ausweisnummer bzw. Aufenthaltserlaubnis gekoppelt ist. Für Touristen ohne eine solche ID ist der reguläre Weg damit praktisch nicht zugänglich, unabhängig davon, wie sorgfältig man sich vorbereitet.", "Eine gesetzliche Versicherungspflicht besteht nicht, wird aber empfohlen.", "In der offenen Kategorie gilt eine maximale Flughöhe von 120 Metern über Grund bei durchgehender Sichtverbindung. Kuriere und Zoll behandeln unangemeldete Drohnen häufig pauschal als verbotene Ware und behalten sie bis zu einer GACA-Freigabe ein, deren Bearbeitung von rund einem Monat bis zu mehreren Monaten dauern kann.", "Kurz gesagt: Wer nur für ein paar Tage als Tourist unterwegs ist, hat aktuell keinen praktikablen legalen Weg, die eigene Drohne in Saudi-Arabien zu nutzen."] },
  { code: "SE", name: "Schweden", maxAltitude: 120, registrationRequired: true, insuranceRequired: false, sourceUrl: "https://www.transportstyrelsen.se/sv/luftfart/luftfartyg-och-luftvardighet/dronare/dronarflygguiden/", rules: ["In Schweden registrierst du dich als Drohnenbetreiber über die Drönarsidan der Transportstyrelsen – Pflicht ab 250 Gramm Startgewicht, bei mehr als 80 Joule Aufprallenergie oder bei jeder Drohne mit Kamera bzw. anderem Sensor.", "Registriert wird nur einmal, und zwar in dem EASA-Staat, in dem du deinen Wohnsitz hast – zum EASA-Raum gehören die EU-Länder plus Island, Liechtenstein, Norwegen und die Schweiz. Die Betreibernummer gilt dann im gesamten EASA-Raum: Wer bereits in einem anderen EASA-Land registriert ist, braucht in Schweden keine zweite Registrierung. Nur wer außerhalb des EASA-Raums wohnt, registriert sich in dem EASA-Staat, in dem er zuerst fliegt.", "Eine Haftpflichtversicherung ist in Schweden für privates Freizeitfliegen mit Drohnen unter 20 Kilogramm nicht vorgeschrieben – erst darüber gilt die Pflicht nach EU-Grundregel.", "Rund um Hubschrauberlandeplätze gilt ein Sperrbereich von 1.000 Metern; Starts und Landungen in Naturschutzgebieten wie Sarek oder Stora Sjöfallet benötigen eine Genehmigung der zuständigen Provinzverwaltung.", "In der offenen Kategorie gilt eine maximale Flughöhe von 120 Metern über Grund, wie EU-weit einheitlich geregelt."] },
  { code: "CH", name: "Schweiz", maxAltitude: 120, registrationRequired: true, insuranceRequired: true, sourceUrl: "https://www.bazl.admin.ch/de/registrierung-drohnenbetreiber", rules: ["Wer in der Schweiz wohnt und eine Drohne betreibt, muss sich über die Plattform dLIS als Drohnenbetreiber registrieren – ausgenommen sind nur Fluggeräte unter 250 Gramm ohne Kamera oder andere Sensoren zur Erfassung personenbezogener Daten. Du erhältst eine Betreibernummer, die in allen EASA-Mitgliedstaaten anerkannt wird.", "Registriert wird nur einmal, und zwar in dem EASA-Staat, in dem du deinen Wohnsitz hast – zum EASA-Raum gehören die EU-Länder plus Island, Liechtenstein, Norwegen und die Schweiz. Wer bereits in einem anderen EASA-Land registriert ist, braucht in der Schweiz also keine zweite Registrierung. Nur wer außerhalb des EASA-Raums wohnt, registriert sich in dem EASA-Staat, in dem er zuerst fliegt.", "Ab 250 Gramm Startgewicht ist eine Haftpflichtversicherung Pflicht; Police und Versicherer werden bei der Registrierung hinterlegt. Leichtere Drohnen ohne Sensorik sind davon ausgenommen.", "Obwohl die Schweiz kein EU-Mitglied ist, wendet sie die EASA-Vorschriften direkt an: In der offenen Kategorie gilt wie in der EU eine maximale Flughöhe von 120 Metern über Grund."] },
  { code: "RS", name: "Serbien", maxAltitude: 100, registrationRequired: true, insuranceRequired: true, sourceUrl: "https://cad.gov.rs/strana/23311/", rules: ["In Serbien registrierst du deine Drohne ab 0,5 Kilogramm Startgewicht bei der Zivilluftfahrtbehörde CAD – Serbien folgt einem eigenen, nicht EU-angeglichenen Regelwerk.", "Eine Haftpflichtversicherung ist in Serbien für die Registrierung und jede Flugfreigabe Pflicht.", "Ausländische Pilotenscheine, auch EU-Kompetenznachweise, werden in Serbien nicht anerkannt: Als Tourist oder Geschäftsreisender brauchst du eine gesonderte Flugfreigabe der CAD, für Luftaufnahmen zusätzlich eine Genehmigung des Verteidigungsministeriums – rechne mit rund drei bis vier Wochen Vorlauf.", "In der offenen Kategorie liegt die maximale Flughöhe bei 100 Metern über Grund – niedriger als der EU-Standard von 120 Metern, höhere Flüge brauchen eine gesonderte Freigabe der CAD."] },
  { code: "SC", name: "Seychellen", maxAltitude: 120, registrationRequired: true, insuranceRequired: false, sourceUrl: "https://www.seyvillas.com/en/guide/travel-info/on-site/drone-usage", rules: ["Auf den Seychellen muss jede Drohne ab 200 Gramm bei der Luftfahrtbehörde SCAA registriert werden – bequem online über ein Portal, mit Passfoto, Foto der Drohne und Seriennummer. Das lässt sich auch noch kurzfristig vor oder direkt bei der Ankunft erledigen.", "Zu einer gesetzlichen Versicherungspflicht liegen keine belastbaren Angaben vor.", "Die maximale Flughöhe liegt bei 120 Metern (400 Fuß).", "Geschützte Gebiete wie das Vallée de Mai, der Morne-Seychellois-Nationalpark oder die Inseln Cousin, Curieuse und Aride dürfen nur mit gesonderter Genehmigung überflogen werden, ebenso die Bereiche um die Flughäfen von Mahé und Praslin sowie Hubschrauberlandeplätze. Für Privatgrundstücke braucht es die Erlaubnis des Eigentümers, und viele Hotels untersagen Drohnennutzung auf ihrem Gelände zum Schutz der Privatsphäre ihrer Gäste – das lohnt sich, vor Ort direkt zu erfragen.", "Von den 23 in diesem Batch recherchierten afrikanischen Ländern sind die Seychellen für Kurzzeit-Touristen das mit Abstand unkomplizierteste: Die Online-Registrierung ist auch spontan machbar."] },
  { code: "ZW", name: "Simbabwe", maxAltitude: 120, registrationRequired: true, insuranceRequired: false, sourceUrl: "https://drone-laws.com/drone-laws-in-zimbabwe/", rules: ["In Simbabwe muss jede Drohne bei der Luftfahrtbehörde CAAZ registriert werden – auch als Hobbyflieger oder Besucher. Zur Versicherungspflicht sind die verfügbaren Quellen nicht eindeutig; im Zweifel eher als empfohlen statt als Pflicht einordnen.", "Die reguläre Flughöhengrenze liegt bei 120 Metern (400 Fuß), die Reichweite bei 500 Metern; mit Sondergenehmigung sind bis zu 1.000 Meter Höhe möglich.", "Um Flughäfen und Flugplätze gilt eine 5-Kilometer-Sperrzone. Zu beliebten Nationalparks wie den Victoriafällen oder Hwange gibt es keine offiziell dokumentierte Detailregelung – nur unbestätigte Reiseforenberichte, vor Ort direkt nachfragen ist hier sinnvoller als sich auf eine bestimmte Regel zu verlassen.", "Besucher müssen sich mindestens 30 Tage vor der Reise bei der CAAZ anmelden und zusätzlich eine befristete Einfuhrgenehmigung der Steuerbehörde beantragen.", "Für Kurzzeit-Touristen ohne diesen Vorlauf ist das kaum praktikabel – wer flexibel reisen will, sollte eher auf eine Drohne verzichten oder frühzeitig planen."] },
  { code: "SG", name: "Singapur", maxAltitude: 61, registrationRequired: true, insuranceRequired: false, sourceUrl: "https://www.caas.gov.sg/unmanned-aircraft/requirements-for-flying-ua/", rules: ["Drohnen mit einem Gewicht von mehr als 250 Gramm müssen bei der Civil Aviation Authority of Singapore über das Online-Portal registriert werden, das Gerät erhält dabei eine eindeutige Kennnummer, die auf eine bei SingPost erhältliche Plakette am Drohnenkörper angebracht werden muss.", "Ausländische Besucher ohne Singpass-Konto nutzen für die Registrierung das sogenannte UAPass-Verfahren, dessen Bearbeitung bis zu fünf Werktage dauert, weshalb es sich empfiehlt, das Konto bereits vor der Einreise nach Singapur anzulegen.", "Ohne gesonderte Genehmigung ist das Fliegen bis zu einer Höhe von 200 Fuß, umgerechnet rund 61 Meter, über mittlerem Meeresspiegel erlaubt, darüber hinaus sowie innerhalb von 5 Kilometern um Flughäfen wie Changi oder den Militärflugplatz Paya Lebar und über dem Central Business District ist eine gesonderte Genehmigung zwingend erforderlich oder das Fliegen ganz untersagt.", "Ab einem Gewicht zwischen 1,5 und 7 Kilogramm ist für den privaten oder schulischen Einsatz zusätzlich ein Basic Training Certificate nachzuweisen, oberhalb von 7 Kilogramm sowie für jede gewerbliche Nutzung ist eine vollständige Fernpilotenlizenz Pflicht.", "Eine allgemeine gesetzliche Versicherungspflicht für die private Freizeitkategorie ist auf den offiziellen Seiten der Behörde nicht dokumentiert, für gewerbliche Betreiber mit Operator-Genehmigung können im Einzelfall abweichende Anforderungen gelten.", "Verstöße, etwa das Fliegen einer unregistrierten Drohne über 250 Gramm oder das Missachten von Sperrzonen, können bei Erstverstößen mit Geldstrafen bis 50.000 Singapur-Dollar und bis zu zwei Jahren Haft geahndet werden, bei wiederholten Verstößen mit bis zu 100.000 Singapur-Dollar und bis zu fünf Jahren Haft."] },
  { code: "SK", name: "Slowakei", maxAltitude: 120, registrationRequired: true, insuranceRequired: true, sourceUrl: "https://letectvo.nsat.sk/bezpilotne-letectvo/", rules: ["In der Slowakei registrierst du dich als Drohnenbetreiber über das E-Government-Portal slovensko.sk beim Verkehrsamt (Dopravný úrad) – die Erstregistrierung kostet 35 Euro, spätere Änderungen 10 (elektronisch 5) Euro. Die Bearbeitung dauert in der Regel bis zu 30 Tage.", "Registriert wird nur einmal, und zwar in dem EASA-Staat, in dem du deinen Wohnsitz hast – zum EASA-Raum gehören die EU-Länder plus Island, Liechtenstein, Norwegen und die Schweiz. Die Betreibernummer gilt dann im gesamten EASA-Raum: Wer bereits in einem anderen EASA-Land registriert ist, braucht in der Slowakei keine zweite Registrierung. Nur wer außerhalb des EASA-Raums wohnt, registriert sich in dem EASA-Staat, in dem er zuerst fliegt.", "Eine Haftpflichtversicherung ist in der Slowakei für die Unterkategorien A2, A3 sowie die spezifische und die zertifizierte Kategorie vorgeschrieben – ausgenommen sind nur Drohnen der Kategorie A1 unter 250 Gramm ohne Kamera. Der Versicherungsnachweis muss bereits bei der Registrierung vorgelegt werden.", "Seit Januar 2024 ist aktives Remote-ID für registrierungspflichtige Drohnen verpflichtend, ebenso wie ein blinkendes grünes Licht bei Nachtflügen.", "In der offenen Kategorie gilt eine maximale Flughöhe von 120 Metern über Grund, wie EU-weit einheitlich geregelt."] },
  { code: "SI", name: "Slowenien", maxAltitude: 120, registrationRequired: true, insuranceRequired: false, sourceUrl: "https://www.caa.si/en/unmanned-aircraft-system.html", rules: ["In Slowenien registrierst du dich als Drohnenbetreiber über uas.caa.si bei der Zivilluftfahrtbehörde CAA – Pflicht ab 250 Gramm Startgewicht, bei mehr als 80 Joule Aufprallenergie oder bei jeder Drohne mit Kamera. Familienmitglieder können sich eine Betreibernummer teilen, müssen aber jeweils einzeln die Kompetenzprüfung ablegen.", "Registriert wird nur einmal, und zwar in dem EASA-Staat, in dem du deinen Wohnsitz hast – zum EASA-Raum gehören die EU-Länder plus Island, Liechtenstein, Norwegen und die Schweiz. Die Betreibernummer gilt dann im gesamten EASA-Raum: Wer bereits in einem anderen EASA-Land registriert ist, braucht in Slowenien keine zweite Registrierung. Nur wer außerhalb des EASA-Raums wohnt, registriert sich in dem EASA-Staat, in dem er zuerst fliegt.", "Eine Haftpflichtversicherung ist in Slowenien nach der EU-Grundregel erst ab einem Startgewicht von 20 Kilogramm gesetzlich vorgeschrieben.", "Im Triglav-Nationalpark sind Drohnenflüge unterhalb von rund 305 Metern über Grund ohne vorherige Genehmigung der Parkverwaltung verboten.", "In der offenen Kategorie gilt eine maximale Flughöhe von 120 Metern über Grund, wie EU-weit einheitlich geregelt."] },
  { code: "ES", name: "Spanien", maxAltitude: 120, registrationRequired: true, insuranceRequired: true, sourceUrl: "https://www.seguridadaerea.gob.es/en/ambitos/drones", rules: ["Wer in Spanien wohnt, muss sich als Drohnenbetreiber bei der Luftfahrtbehörde AESA registrieren (elektronisches Amt sede.seguridadaerea.gob.es) – Pflicht ab 250 Gramm Startgewicht, bei mehr als 80 Joule Aufprallenergie oder wenn ein Sensor personenbezogene Daten erfassen kann.", "Registriert wird nur einmal, und zwar in dem EASA-Staat, in dem du deinen Wohnsitz hast – zum EASA-Raum gehören die EU-Länder plus Island, Liechtenstein, Norwegen und die Schweiz. Die Betreibernummer gilt dann im gesamten EASA-Raum: Wer bereits in einem anderen EASA-Land registriert ist, braucht in Spanien keine zweite Registrierung. Nur wer außerhalb des EASA-Raums wohnt, registriert sich in dem EASA-Staat, in dem er zuerst fliegt.", "Eine Haftpflichtversicherung ist in Spanien für jede Drohne vorgeschrieben, unabhängig von Gewicht oder Kategorie – eine der strengsten Regelungen in der EU.", "Für bestimmte anspruchsvolle Einsätze, etwa Flüge außer Sichtweite über Städten, verlangt Spanien zusätzlich zu den EU-Kompetenznachweisen eigene, nationale STS-ES-Nachweise.", "In der offenen Kategorie liegt die maximale Flughöhe bei 120 Metern über Grund. Für die Flugplanung stellt die spanische Flugsicherung ENAIRE mit Drone Space eine offizielle Geozonen-Karte bereit."] },
  { code: "LK", name: "Sri Lanka", maxAltitude: null, registrationRequired: true, insuranceRequired: false, sourceUrl: "https://www.caa.lk/en/drones", rules: ["Zur maximal zulässigen Flughöhe finden sich in unterschiedlichen Quellen widersprüchliche Angaben (unter anderem 45 Meter und 120 Meter, teils auch keine explizite Höhengrenze), weshalb hier bewusst kein Zahlenwert übernommen wird; unstrittig ist dagegen, dass ständiger Sichtkontakt (VLOS) und eine Mindestsichtweite von 5 Kilometern einzuhalten sind.", "Drohnen werden nach Gewicht in vier Kategorien eingeteilt (A ab 25 Kilogramm, B über 1 bis unter 25 Kilogramm, C über 200 Gramm bis 1 Kilogramm, D bis 200 Gramm); die Kategorien A bis C mit Aufnahmesensorik müssen bei der Civil Aviation Authority of Sri Lanka (CAASL) registriert werden, während sehr kleine Kategorie-D-Geräte ohne Sensorik von der Registrierung ausgenommen sind.", "Eine Versicherungspflicht wird in mehreren Quellen für die Kategorien A bis C genannt, während Kategorie-D-Drohnen ausgenommen sind; da gängige Freizeitdrohnen wie kompakte DJI-Modelle unter 250 Gramm häufig bereits in Kategorie C fallen, kann im Einzelfall eine Versicherung nötig werden, eine pauschale gesetzliche Pflicht für jede private Nutzung lässt sich aus den verfügbaren Quellen jedoch nicht eindeutig belegen.", "Ausländische Touristen benötigen über das CAASL-Registrierungsportal eine gesonderte, häufig als temporäre Registrierung bezeichnete Anmeldung mit Pass- und Reisedaten, Kaufbeleg und Gerätefotos, da die reguläre Vollregistrierung Staatsangehörigen vorbehalten ist; die Bearbeitung dauert nach Erfahrungsberichten oft mehrere Wochen und kann zusätzliche Freigaben von Verteidigungsministerium und Telekommunikationsbehörde erfordern.", "Flugverbote gelten unter anderem für Nationalparks, archäologische und religiöse Stätten, Militärgelände sowie einen Sicherheitsabstand von mehreren Kilometern zu Flughäfen; Nachtflüge sind ohne gesonderte CAASL-Genehmigung untersagt.", "Offiziell veröffentlichte, konkrete Bußgeldbeträge für Verstöße sind nicht dokumentiert; in Erfahrungsberichten werden jedoch Beschlagnahmung der Drohne und im Einzelfall strafrechtliche Konsequenzen genannt."] },
  { code: "LC", name: "St. Lucia", maxAltitude: null, registrationRequired: false, insuranceRequired: false, sourceUrl: "https://www.govt.lc/ministries/physical-development/civil-aviation-department", rules: ["Für St. Lucia ist über die zuständige Behörde (die regionale ECCAA sowie das Ministerium für Physische Entwicklung) kein einheitliches, öffentlich dokumentiertes Registrierungs- oder Versicherungsverfahren für Drohnen auffindbar – wende dich im Zweifel direkt an die dortige Zivilluftfahrtabteilung, bevor du fliegst.", "Klar dokumentiert sind dagegen dauerhafte Sperrzonen im Umkreis von 2,5 nautischen Meilen um die Flughäfen Hewanorra und George F. L. Charles, sowie zusätzliche Einschränkungen während des Carnival.", "Gewerbliche Nutzung braucht in jedem Fall eine Einzelfall-Genehmigung des Ministeriums."] },
  { code: "ZA", name: "Südafrika", maxAltitude: 120, registrationRequired: false, insuranceRequired: false, sourceUrl: "https://www.cliffedekkerhofmeyr.com/en/news/publications/2024/Practice/Corporate/corporate-commercial-alert-19-June-2024-drone-operations-in-south-africa-an-overview-of-the-legal-landscape", rules: ["In Südafrika ist reine private Freizeitnutzung im Vergleich zu vielen Nachbarländern unkompliziert geregelt: Eine Registrierungspflicht besteht nach der einschlägigen Vorschrift (Teil 101.02.4(1) der Luftfahrtvorschriften) nur für kommerzielle Betreiber, nicht für Hobbyflieger.", "Eine gesetzliche Versicherungspflicht für private Nutzung ist ebenfalls nicht dokumentiert; wer im Verband SAMAA Mitglied wird, kann dort eine freiwillige Haftpflichtdeckung mitversichert bekommen.", "Bei der maximalen Flughöhe gibt es unterschiedliche Angaben: Für ausgewiesene \"Park Flier\"-Freizeitzonen des Verbands gelten 45 Meter, als allgemeine private Obergrenze werden meist 120 Meter (400 Fuß) genannt.", "Der große Vorbehalt: In Nationalparks und Schutzgebieten – darunter der bei Touristen beliebte Krüger-Nationalpark – ist Drohnenbetrieb ohne gesonderte Genehmigung der zuständigen Parkverwaltung ausdrücklich verboten. Verstöße gegen dieses Verbot werden nach dem Gesetz zu Schutzgebieten hart geahndet: bis zu 10 Jahre Haft und/oder umgerechnet mehrere tausend Euro Bußgeld.", "Kurz gesagt: außerhalb von Nationalparks vergleichsweise einfach, innerhalb von ihnen strikt verboten – gerade bei einer Safari-Reise unbedingt vorher prüfen, ob das jeweilige Gebiet ein Schutzgebiet ist."] },
  { code: "KR", name: "Südkorea", maxAltitude: 150, registrationRequired: true, insuranceRequired: false, sourceUrl: "https://easylaw.go.kr/CSP/CnpClsMain.laf?popMenu=ov&csmSeq=1814&ccfNo=2&cciNo=1&cnpClsNo=1", rules: ["In Südkorea besteht grundsätzlich eine Registrierungspflicht für Drohnen: Gewerblich genutzte Geräte müssen unabhängig vom Gewicht angemeldet werden, private Freizeitdrohnen dagegen erst ab einem Startgewicht von 2 Kilogramm; die Meldung muss innerhalb von 30 Tagen nach Erwerb bei der Korea Transportation Safety Authority erfolgen.", "Flüge ab einer Höhe von 150 Metern über Grund sowie generell innerhalb von Flughafen-Kontrollzonen mit rund 9,3 Kilometern Radius und in ausgewiesenen Flugverbotszonen erfordern eine gesonderte Freigabe über das Online-Portal Drone One-Stop des Ministeriums für Land, Infrastruktur und Verkehr.", "Eine gesetzliche Versicherungspflicht gilt nur für gewerbliche Anbieter, Vermietungsunternehmen, Freizeitsportbetriebe und Behördendrohnen, nicht für private Hobbypiloten ohne kommerzielle Nutzung.", "Ausländische Touristen dürfen Drohnen grundsätzlich einführen und fliegen, benötigen für Flüge in sensiblen Bereichen wie nahe der innerkoreanischen Grenze, Militäranlagen oder Flughäfen aber eine vorherige Online-Genehmigung; eine fehlende lokale Meldeadresse erschwert in der Praxis mitunter die Registrierung größerer Fluggeräte.", "Unregistrierte Flüge können mit bis zu sechs Monaten Freiheitsstrafe oder einer Geldstrafe von bis zu 5 Millionen Won geahndet werden, unerlaubte Flüge in Sperrgebieten oder oberhalb von 150 Metern mit Bußgeldern von bis zu 5 beziehungsweise 3 Millionen Won."] },
  { code: "TJ", name: "Tadschikistan", maxAltitude: null, registrationRequired: false, insuranceRequired: false, sourceUrl: "https://fitcationhq.com/tajikistan-drone-regulations-for-tourists-2026-guide/", rules: ["Wichtiger Hinweis: In Tadschikistan gibt es kein funktionierendes Registrierungsverfahren für private oder touristische Drohnennutzung. Formal wäre neben der Zivilluftfahrtbehörde auch eine Zustimmung des Staatskomitees für Nationale Sicherheit nötig, in der Praxis wird eine Genehmigung fast ausschließlich an registrierte Firmen, Hochzeitsfotografen oder staatliche Filmteams vergeben.", "Eine solche Genehmigung muss bereits vor der Einreise vorliegen; ohne sie gilt die Einfuhr als eindeutig illegal, mit entsprechend hohem Risiko einer Beschlagnahmung am Zoll.", "Sperrzonen betreffen unter anderem Flughäfen, Militäranlagen, Polizeistationen, Grenzübergänge und Regierungsgebäude – schon das Fotografieren dieser Bereiche kann zu einer sofortigen Festnahme führen.", "Erfahrungsberichten von Reisenden zufolge sind Drohnen faktisch zu hundert Prozent illegal, sofern sie nicht behördlich registriert wurden; die tatsächliche Durchsetzung ist zwar uneinheitlich, das Risiko bleibt aber real.", "Für die Tadschikistan-Reise gilt daher: Drohne besser gar nicht mitnehmen. Ein praktikabler legaler Weg für Kurzzeit-Touristen existiert nicht."] },
  { code: "TW", name: "Taiwan", maxAltitude: 122, registrationRequired: true, insuranceRequired: false, sourceUrl: "https://www.caa.gov.tw/Article.aspx?a=2425&lang=1", rules: ["Drohnen ab 250 Gramm Startgewicht müssen bei der Civil Aeronautics Administration registriert werden; nur Privatpersonen mit Fluggeräten unter 250 Gramm sind ausgenommen, während Behörden, Schulen und juristische Personen unabhängig vom Gewicht immer registrieren müssen, die Registrierung gilt jeweils zwei Jahre.", "Ab 2 Kilogramm Startgewicht mit Navigationsausrüstung ist zusätzlich ein gestaffelter Pilotenschein mit theoretischer und praktischer Prüfung erforderlich, Fluggeräte unter dieser Grenze sind davon befreit.", "Die maximale Flughöhe liegt bei 400 Fuß, umgerechnet rund 122 Metern, über Grund oder Wasser; das Land ist zudem in grüne, gelbe und rote Zonen mit gestaffelten Beschränkungen bis hin zu vollständigen Flugverboten eingeteilt.", "Eine gesetzliche Versicherungspflicht besteht nur für Behörden und für Betreiber mit beantragten Ausnahmegenehmigungen; private Freizeitpiloten sind nicht zum Abschluss einer Haftpflichtversicherung verpflichtet, eine Absicherung wird aber empfohlen, da die Halter grundsätzlich für Personen- und Sachschäden haften.", "Verstöße werden gestaffelt geahndet: unregistrierte Flüge mit umgerechnet mehreren tausend Euro, konkret NT$30.000 bis 150.000, Flüge ohne erforderlichen Pilotenschein mit NT$60.000 bis 300.000, und Flüge in Sperrzonen oder oberhalb der Höhengrenze mit NT$300.000 bis 1.500.000.", "Für ausländische Touristen ist die Online-Registrierung grundsätzlich möglich, in der Praxis erleichtern eine taiwanesische Telefonnummer oder Unterstützung durch Vermieter oder lokale Fotografie-Agenturen den Prozess aber deutlich."] },
  { code: "TZ", name: "Tansania", maxAltitude: 121, registrationRequired: true, insuranceRequired: false, sourceUrl: "https://drone-laws.com/drone-laws-in-tanzania/", rules: ["In Tansania muss jede Drohne bei der Luftfahrtbehörde TCAA registriert werden (einmalige Gebühr, unbefristet gültig), zusätzlich ist eine Freigabe von Verteidigungsministerium und Nachrichtendienst nötig.", "Für jeden einzelnen Einsatz brauchst du außerdem ein gesondertes Betriebs-Permit – die Registrierung allein reicht nicht. Touristen benötigen zudem einen gültigen Pilotenschein aus dem Heimatland.", "Eine Versicherung ist gesetzlich nicht vorgeschrieben, wird aber empfohlen. Die maximale Flughöhe liegt bei 121 Metern (400 Fuß).", "Sperrzonen gelten in 3 bis 5 Kilometern um Flughäfen sowie über Nationalparks; Nachtflüge sind grundsätzlich nicht erlaubt.", "Wer ohne Registrierung fliegt, riskiert eine Geldstrafe bis umgerechnet mehreren hundert Euro oder bis zu sechs Monate Haft.", "Für Touristen ist ein legaler Flug möglich, aber nur mit ordentlichem Vorlauf vor der Reise – spontan fliegen geht in Tansania nicht."] },
  { code: "TH", name: "Thailand", maxAltitude: 90, registrationRequired: true, insuranceRequired: true, sourceUrl: "https://www.tatnews.org/2026/06/flying-a-drone-in-thailand-updated-guide-for-tourists/", rules: ["Drohnen müssen in Thailand grundsätzlich sowohl bei der Telekommunikationsbehörde NBTC als auch – bei Kameradrohnen, Geräten über 2 Kilogramm oder ab 25 Kilogramm zusätzlich mit ministerieller Genehmigung – bei der Luftfahrtbehörde CAAT registriert werden.", "Flüge sind nur bei Tageslicht, gutem Wetter und in ständiger Sichtweite der steuernden Person erlaubt; für Nachtflüge sowie für Flughöhen über 90 Metern ist eine gesonderte schriftliche Genehmigung der CAAT erforderlich.", "Seit die CAAT die während des Grenzkonflikts mit Kambodscha 2025 verhängten landesweiten Beschränkungen 2026 wieder gelockert hat, ist vor jedem Flug zusätzlich eine Freigabe über das UAS-Portal der Behörde einzuholen.", "In sieben an Kambodscha angrenzenden Provinzen – Ubon Ratchathani, Si Sa Ket, Surin, Buri Ram, Sa Kaeo, Chanthaburi und Trat – bleiben Drohnenflüge weiterhin grundsätzlich untersagt und werden nur im Einzelfall etwa für Landwirtschaft, Katastrophenhilfe oder Rettungseinsätze genehmigt.", "Eine Haftpflichtversicherung mit einer Mindestdeckungssumme von einer Million Thai Baht ist vor jedem Betrieb verpflichtend nachzuweisen.", "Zu Personen und Gebäuden ist bei Drohnen unter 2 Kilogramm ein Mindestabstand von 30 Metern einzuhalten, bei schwereren Geräten bis 25 Kilogramm sind es 50 Meter; zusätzlich gilt ein Sicherheitsabstand von 9 Kilometern zu Flughäfen.", "Verstöße können mit bis zu einem Jahr Haft, einer Geldstrafe von bis zu 40.000 Baht oder beidem geahndet werden, und Sicherheitskräfte sind befugt, als Bedrohung eingestufte Drohnen unschädlich zu machen."] },
  { code: "TO", name: "Tonga", maxAltitude: 120, registrationRequired: true, insuranceRequired: false, sourceUrl: "https://drone-laws.com/drone-laws-in-tonga/", rules: ["In Tonga muss jede Drohne bei der Civil Aviation Division registriert werden – ohne Registrierung ist das Fliegen ausdrücklich untersagt. Die Behörde nutzt, ähnlich wie mehrere andere Pazifikstaaten, ein an neuseeländisches Recht angelehntes Regelwerk (Part 101/102) über das regionale Pacific Aviation Safety Office.", "Eine Versicherung ist nicht vorgeschrieben, wird aber empfohlen. Die maximale Flughöhe liegt bei 120 Metern (400 Fuß) oder der Wolkenuntergrenze, falls diese niedriger liegt.", "Zur genauen Gewichtsgrenze für genehmigungsfreien Betrieb widersprechen sich die verfügbaren Quellen (einmal 15, einmal 25 Kilogramm) – eine eindeutige Zahl war nicht zu bestätigen.", "Sperrzonen gelten in 4 Kilometern um die sechs Flughäfen des Landes sowie um den Königspalast, königliche Residenzen und Gräber, Botschaften und Militäreinrichtungen. Für Flüge über Privatgrundstücke brauchst du die Zustimmung der Eigentümer.", "Für Touristen ist ein legaler Flug möglich, sollte aber wegen der vorab nötigen Registrierung (je nach Quelle wenige Tage bis rund zwei Wochen Bearbeitungszeit) schon vor der Reise angestoßen werden."] },
  { code: "TT", name: "Trinidad und Tobago", maxAltitude: 120, registrationRequired: true, insuranceRequired: false, sourceUrl: "https://caa.gov.tt/licensing-certification/unmanned-aircraft-systems-uas-drones/", rules: ["In Trinidad und Tobago musst du deine Drohne ab 750 Gramm bei der Luftfahrtbehörde TTCAA registrieren – als Besucher solltest du dich schon vor der Reise per E-Mail bei der TTCAA melden.", "Eine Versicherungspflicht besteht nur für gewerbliche Betreiber. Wichtig ist zusätzlich eine gesonderte Einfuhrgenehmigung der Telekommunikationsbehörde TATT, ohne die eine importierte Drohne beim Zoll einbehalten wird.", "Für die leichteste Kategorie unter 750 Gramm liegt die maximale Flughöhe bei nur 30 Metern über Grund, für schwerere Drohnen bei 120 Metern."] },
  { code: "CZ", name: "Tschechien", maxAltitude: 120, registrationRequired: true, insuranceRequired: true, sourceUrl: "https://www.caa.cz/provoz/bezpilotni-letadla/", rules: ["In Tschechien registrierst du dich als Drohnenbetreiber über das Portal der Zivilluftfahrtbehörde ÚCL (dron.caa.cz) – Pflicht ab 250 Gramm Startgewicht oder bei jeder Drohne mit Kamera bzw. anderem Datenerfassungs-Sensor.", "Registriert wird nur einmal, und zwar in dem EASA-Staat, in dem du deinen Wohnsitz hast – zum EASA-Raum gehören die EU-Länder plus Island, Liechtenstein, Norwegen und die Schweiz. Die Betreibernummer gilt dann im gesamten EASA-Raum: Wer bereits in einem anderen EASA-Land registriert ist, braucht in Tschechien keine zweite Registrierung. Nur wer außerhalb des EASA-Raums wohnt, registriert sich in dem EASA-Staat, in dem er zuerst fliegt.", "Eine Haftpflichtversicherung ist in Tschechien für jede gewerbliche oder sonstige nicht-private Nutzung Pflicht, unabhängig vom Gewicht. Ausschließlich privates Freizeitfliegen mit Drohnen bis 20 Kilogramm ist davon ausgenommen.", "In der offenen Kategorie gilt eine maximale Flughöhe von 120 Metern über Grund; bei Hindernissen über 120 Metern ist mit Zustimmung des Eigentümers ein Zuschlag von bis zu 15 Metern erlaubt, wie EU-weit einheitlich geregelt."] },
  { code: "TN", name: "Tunesien", maxAltitude: null, registrationRequired: false, insuranceRequired: false, sourceUrl: "https://drone-laws.com/drone-laws-in-tunisia/", rules: ["Wichtiger Hinweis: Auch Tunesien reguliert Drohnen für Freizeitpiloten offiziell nicht – die Luftfahrtbehörde OACA hat den Bereich nach verfügbaren Quellen bislang nicht kodifiziert.", "Trotzdem wurden mehrfach Konfiszierungen berichtet, teils obwohl sich Reisende an alle allgemein bekannten Regeln gehalten hatten – offenbar entscheiden hier einzelne Beamte oder mehrere Ministerien im Einzelfall.", "Eine feste Angabe zu Flughöhe oder Versicherungspflicht existiert mangels Regelwerk nicht.", "Für die Tunesien-Reise gilt daher: praktisch ein de-facto-Verbot, auch wenn formal keine Vorschrift existiert. Besser die Drohne zu Hause lassen, statt auf gut Glück am Zoll vorbeizukommen."] },
  { code: "TR", name: "Türkei", maxAltitude: 120, registrationRequired: true, insuranceRequired: true, sourceUrl: "https://iha.shgm.gov.tr", rules: ["In der Türkei musst du deine Drohne ab 500 Gramm bei der Luftfahrtbehörde SHGM registrieren – über das Portal iha.shgm.gov.tr. Im Ausland gekaufte oder mitgebrachte Drohnen musst du innerhalb von drei Tagen nach Einreise selbst registrieren.", "Eine Haftpflichtversicherung ist in der Türkei für Drohnen über 25 Kilogramm sowie für jede gewerbliche Nutzung Pflicht, unabhängig vom Gewicht.", "Wichtig für den Türkei-Urlaub: Als ausländischer Pilot brauchst du für Drohnenflüge eine Genehmigung, die mindestens 20 Werktage vorab über den diplomatischen Weg beantragt werden muss, und musst von einem lizenzierten türkischen Piloten begleitet werden. Plane das frühzeitig, sonst bleibt die Drohne im Koffer.", "In der offenen Kategorie gilt eine maximale Flughöhe von 120 Metern über Grund, bei einer Sichtweite von maximal 500 Metern zum Piloten."] },
  { code: "US", name: "USA", maxAltitude: 122, registrationRequired: true, insuranceRequired: false, sourceUrl: "https://www.faa.gov/uas/recreational_flyers", rules: ["In den USA musst du deine Drohne ab 250 Gramm bei der Luftfahrtbehörde FAA registrieren (FAADroneZone) und zusätzlich die kostenlose TRUST-Prüfung ablegen – das gilt ausdrücklich auch für ausländische Besucher, ein deutscher Kompetenznachweis wird nicht anerkannt.", "Eine bundesweite Versicherungspflicht gibt es in den USA nicht; einzelne Bundesstaaten oder Orte können aber eigene Vorgaben haben.", "Seit September 2023 ist für die meisten Drohnen eine aktive Remote-ID-Kennung Pflicht, die deinen Standort während des Flugs überträgt.", "Die maximale Flughöhe liegt bei 400 Fuß (rund 122 Metern) über Grund im unkontrollierten Luftraum; für kontrollierten Luftraum brauchst du vorab eine Freigabe über LAANC."] },
  { code: "UG", name: "Uganda", maxAltitude: 120, registrationRequired: true, insuranceRequired: false, sourceUrl: "https://drone-laws.com/drone-laws-in-uganda/", rules: ["In Uganda muss jede Drohne bis 25 Kilogramm Startgewicht (inklusive Zuladung) bei der Luftfahrtbehörde UCAA registriert werden. Eine Versicherung ist nicht vorgeschrieben, wird aber empfohlen.", "Für Touristen ist der Weg besonders aufwendig: Vor der Einreise müssen \"No Objection Letters\" von Tourismus- und Verteidigungsministerium sowie eine Freigabe der Steuerbehörde eingeholt werden, dazu ein UCAA-Permit. Dieser Prozess sollte Monate vor der Reise beginnen.", "Die maximale Flughöhe liegt bei 120 Metern (400 Fuß).", "Ohne diese Vorab-Genehmigung wird die Drohne bei der Einreise am Flughafen einbehalten und erst bei der Ausreise zurückgegeben – das ist der dokumentierte Normalfall, nicht die Ausnahme.", "Für kurzfristig geplante Reisen ohne mehrmonatigen Vorlauf ist Uganda damit faktisch nicht praktikabel; wer die eigene Drohne wirklich nutzen möchte, muss den Antrag deutlich vor Reisebeginn stellen."] },
  { code: "UA", name: "Ukraine", maxAltitude: 120, registrationRequired: true, insuranceRequired: false, sourceUrl: "https://avia.gov.ua", rules: ["Wichtiger Hinweis: Der zivile Luftraum der Ukraine ist seit Februar 2022 durchgehend gesperrt. Ziviles Drohnenfliegen ist landesweit praktisch verboten, unautorisierte Flüge können als Sicherheitsbedrohung eingestuft werden. Von Freizeitflügen wird derzeit dringend abgeraten.", "Die regulären Regeln aus Friedenszeiten (Registrierung bei der Staatlichen Luftfahrtbehörde SAAU, maximale Flughöhe von rund 120 Metern) sind während des Kriegsrechts ausgesetzt und aktuell nicht anwendbar.", "Aktuelle, verlässliche Informationen bekommst du am ehesten direkt bei der SAAU oder den örtlichen Behörden vor Ort."] },
  { code: "HU", name: "Ungarn", maxAltitude: 120, registrationRequired: true, insuranceRequired: true, sourceUrl: "https://kozlekedesihatosag.kormany.hu", rules: ["In Ungarn registrierst du dich und deine Drohne getrennt bei der Verkehrsbehörde (Közlekedési Hatóság) – da es kein eigenes Online-Portal gibt, läuft die Anmeldung über das E-Government-System e-Papír, jeweils gegen eine Gebühr von 2.000 Forint.", "Registriert wird nur einmal, und zwar in dem EASA-Staat, in dem du deinen Wohnsitz hast – zum EASA-Raum gehören die EU-Länder plus Island, Liechtenstein, Norwegen und die Schweiz. Die Betreibernummer gilt dann im gesamten EASA-Raum: Wer bereits in einem anderen EASA-Land registriert ist, braucht in Ungarn keine zweite Registrierung. Nur wer außerhalb des EASA-Raums wohnt, registriert sich in dem EASA-Staat, in dem er zuerst fliegt.", "Eine Haftpflichtversicherung ist in Ungarn bereits ab 250 Gramm Startgewicht gesetzlich vorgeschrieben – eine deutliche Verschärfung gegenüber der EU-Grundregel, die Versicherung erst ab 20 Kilogramm verlangt.", "Für jeden Flug ist die Nutzung der offiziellen Geozonen-App MyDroneSpace vorgeschrieben, um Sperrgebiete in Echtzeit zu prüfen.", "In der offenen Kategorie gilt eine maximale Flughöhe von 120 Metern über Grund, wie EU-weit einheitlich geregelt."] },
  { code: "UY", name: "Uruguay", maxAltitude: 120, registrationRequired: true, insuranceRequired: false, sourceUrl: "https://www.dinacia.gub.uy/servicio/registro-de-drones", rules: ["In Uruguay ist die Dirección Nacional de Aviación Civil e Infraestructura Aeronáutica (DINACIA) für die Regulierung und Registrierung von Drohnen zuständig; die Anmeldung erfolgt online über das Portal utm.dinacia.gub.uy.", "Drohnen werden nach Startgewicht in drei Klassen eingeteilt: 'Menores' bis 25 Kilogramm, 'Medianos' zwischen 25 und 260 Kilogramm sowie 'Mayores' über 260 Kilogramm; ab der mittleren Kategorie ist eine formelle Registrierung samt Unterlagen erforderlich, während kleinere Freizeitdrohnen ohne gewerblichen Zweck davon in der Regel ausgenommen sind.", "Für den privaten Flug außerhalb von Flugplatzbereichen und dicht besiedelten Gebieten gilt eine Höhenobergrenze von 120 Metern über Grund; für eigens ausgewiesene innerstädtische Freizeitzonen legt DINACIA per gesonderter Resolution abweichend nur 30 Meter fest.", "Kommerzielle Einsätze gelten als Luftarbeit ('trabajo aéreo') und benötigen neben einer gesonderten Genehmigung auch eine Haftpflichtversicherung, während für rein private Freizeitflüge keine Versicherungspflicht besteht.", "Ausländische Piloten sollten vor der Reise direkten Kontakt zu DINACIA aufnehmen, da temporäre Genehmigungen für Besucher zwar möglich sind, viele kommerzielle Freigaben in der Praxis aber vorrangig für in Uruguay registrierte Unternehmen vorgesehen sind."] },
  { code: "UZ", name: "Usbekistan", maxAltitude: null, registrationRequired: false, insuranceRequired: false, sourceUrl: "https://gov.uz/en/uzcaa/pages/dronlar-uua", rules: ["Wichtiger Hinweis: Seit dem 1. Januar 2015 sind Einfuhr, Besitz und Betrieb von Drohnen durch Privatpersonen in Usbekistan grundsätzlich verboten. Eine Ausnahme gilt nur für reine Spielzeug-Fluggeräte bis maximal 50 Meter Flughöhe mit mindestens 150 Metern Abstand zu Flughafen-Anflugschneisen, die ohne Genehmigung geflogen werden dürfen.", "Reguläre Drohnen benötigen eine Genehmigung des Kabinetts, eine Freigabe des Ministeriums für Informationstechnologien (wegen der Funkfrequenz) sowie eine Registrierung bei der Luftfahrtbehörde Uzaviation – ein Verfahren, das praktisch nur registrierten Firmen, Filmteams oder staatlich beauftragten Projekten offensteht, nicht Freizeitpiloten oder Touristen.", "Verstöße werden nach dem usbekischen Strafgesetzbuch geahndet: Berichten zufolge mit Geldstrafen und teils auch mit Haftstrafen, wobei einzelne Quellen für Ersttäter zuletzt eine Milderung hin zu Geldstrafe plus Einziehung des Geräts beschreiben. Am Zoll werden unangemeldete Drohnen bei der Röntgenkontrolle zuverlässig erkannt.", "Eine für Ende 2026 angekündigte Lockerung betrifft ausdrücklich nur juristische Personen (Unternehmen), nicht Privatpersonen oder Touristen.", "Für die Usbekistan-Reise gilt daher: Drohne besser gar nicht mitnehmen. Für Kurzzeit-Touristen gibt es keinen praktikablen legalen Weg, dort zu fliegen."] },
  { code: "VU", name: "Vanuatu", maxAltitude: 120, registrationRequired: true, insuranceRequired: false, sourceUrl: "https://caav.vu/fligth-safety/drones/", rules: ["In Vanuatu muss jede Drohne unabhängig vom Gewicht bei der Luftfahrtbehörde CAAV registriert werden – bei ausländischen Piloten idealerweise schon vor der Anreise. Zusätzlich zur Registrierung ist für jeden einzelnen Flug ein gesonderter Antrag mit Flugplan, Koordinaten sowie Datum und Uhrzeit nötig, dessen Bearbeitung rund fünf Werktage dauert.", "Eine Versicherung ist nicht vorgeschrieben, wird aber empfohlen. Die maximale Flughöhe liegt bei 120 Metern (400 Fuß), das maximale Abfluggewicht bei 25 Kilogramm.", "Sperrzonen gelten in 4 Kilometern um Flughäfen, Landebahnen und Hubschrauberlandeplätze, über Wohngebieten und Dörfern sowie über Kulturstätten. Der Hafen von Port Vila braucht eine zusätzliche Genehmigung der Hafenbehörde, die kleine Insel Mystery Island gilt komplett als Flughafengelände und ist damit tabu. Für Flüge über Privatgrundstücke ist die Zustimmung des Landbesitzers nötig.", "Bei Verstößen können Drohnen von Behörde und Polizei beschlagnahmt werden; zu den genauen Bußgeldhöhen widersprechen sich die verfügbaren Quellen deutlich, sodass hier keine verlässliche Zahl genannt werden kann.", "Für Touristen ist ein legaler Flug machbar, aber wegen der zusätzlichen Einzelgenehmigung pro Flug nicht spontan – am besten Registrierung und ersten Flugantrag schon vor der Reise in die Wege leiten."] },
  { code: "VE", name: "Venezuela", maxAltitude: null, registrationRequired: false, insuranceRequired: false, sourceUrl: "https://www.inac.gob.ve/", rules: ["Wichtiger Hinweis: Seit einem Dekret vom 18. August 2025 (Gaceta Oficial Nr. 6.927) sind in Venezuela Kauf, Verkauf, Herstellung, Einfuhr, Ausbildung, Registrierung und jeder Flugbetrieb von Drohnen durch Privatpersonen grundsätzlich verboten – ausgenommen sind ausschließlich staatliche Sicherheits- und Verteidigungsbehörden. Die Maßnahme wurde zunächst für ein Jahr angekündigt und mit der angespannten Sicherheitslage begründet.", "Nach mehreren übereinstimmenden, aber nicht vollständig amtlich bestätigten Berichten wurde die Beschränkung im Laufe des Verbotszeitraums mindestens einmal erneuert bzw. bekräftigt; ob sie zum jetzigen Zeitpunkt noch in vollem Umfang gilt, lässt sich öffentlich nicht abschließend verifizieren – angesichts der politischen Lage ist aber eher von einer Fortdauer als von einer stillschweigenden Aufhebung auszugehen.", "Ein reguläres Registrierungsverfahren für private oder touristische Nutzer existiert unter diesen Umständen faktisch nicht, auch wenn die Luftfahrtbehörde INAC vor dem Verbot ein eigenes Register (RAN) für Drohnen führte.", "Für die Venezuela-Reise gilt daher: besser keine eigene Drohne mitnehmen. Es gibt aktuell keinen legalen Weg für Touristen, dort zu fliegen, und angesichts der angespannten Sicherheitslage besteht zusätzlich das Risiko, dass ein Gerät bei der Einreise als Sicherheitsrisiko eingestuft und einbehalten wird."] },
  { code: "AE", name: "Vereinigte Arabische Emirate", maxAltitude: 120, registrationRequired: true, insuranceRequired: false, sourceUrl: "https://www.gcaa.gov.ae/en/pages/UASRegistration.aspx/", rules: ["In den Vereinigten Arabischen Emiraten muss jede Drohne unabhängig vom Gewicht bei der Luftfahrtbehörde GCAA registriert werden, für Freizeitpiloten über die App MyDroneHub. Eine Haftpflichtversicherung ist für Hobbynutzer nicht vorgeschrieben, wird aber empfohlen.", "Geflogen werden darf grundsätzlich nur in von der GCAA freigegebenen Zonen (bis 5 Kilogramm Startgewicht); schwerere oder gasbetriebene Modelle sind nur in zugelassenen Flugclubs erlaubt. Die maximale Flughöhe liegt bei 120 Metern über Grund, immer mit direkter Sichtverbindung zur Drohne.", "Sperrzonen gelten unter anderem rund um Flughäfen, Regierungs- und Militärgebäude sowie Wohngebiete; Nachtflüge brauchen eine Sondergenehmigung. In Dubai existiert für Touristen zusätzlich ein eigenes Kurzzeit-Permit-Verfahren, dessen genaue Kosten und Bearbeitungsdauer in den verfügbaren Quellen nicht einheitlich und nicht amtlich bestätigt sind – vor der Reise direkt bei der lokalen Behörde nachfragen ist hier sinnvoller als sich auf eine bestimmte Zahl zu verlassen.", "Die Strafen bei Verstößen sind empfindlich: Bis zu einem Jahr Haft und/oder 50.000 AED für unautorisierte Flüge, bis zu drei Jahre Haft und/oder 100.000 AED für Flüge über Sperrzonen.", "Gerade in touristisch beliebten Bereichen (z. B. rund um Burj Khalifa, Marina, Downtown Dubai) ist häufig Sperrgebiet – wer dort ohne Permit fliegt, riskiert genau diese Strafen."] },
  { code: "GB", name: "Vereinigtes Königreich", maxAltitude: 120, registrationRequired: true, insuranceRequired: true, sourceUrl: "https://www.caa.co.uk/drones/", rules: ["Im Vereinigten Königreich brauchst du für Drohnen ab 250 Gramm sowie für jede leichtere Drohne mit Kamera (ab 100 Gramm) eine Flyer-ID (Kompetenznachweis) und eine Operator-ID – Registrierung über die Website der britischen Luftfahrtbehörde CAA.", "Eine Haftpflichtversicherung ist im Vereinigten Königreich für jede gewerbliche Nutzung Pflicht, unabhängig vom Gewicht. Rein privates Freizeitfliegen ist gesetzlich nicht versicherungspflichtig, du haftest im Schadensfall aber trotzdem.", "Rund um Flughäfen, Gefängnisse, Militäranlagen und Regierungsgebäude gelten Flugbeschränkungszonen (Flight Restriction Zones) – ein Verstoß, der andere Luftfahrzeuge gefährdet, kann mit bis zu fünf Jahren Haft geahndet werden.", "In der offenen Kategorie gilt eine maximale Flughöhe von 120 Metern über Grund – wie in der EU, auch wenn das Vereinigte Königreich die Regeln seit dem Brexit eigenständig im nationalen Recht führt."] },
  { code: "VN", name: "Vietnam", maxAltitude: 120, registrationRequired: true, insuranceRequired: false, sourceUrl: "https://vietanlaw.com/drone-uav-management-decree-288-2025-compliance-in-vietnam/", rules: ["Seit Inkrafttreten des Dekrets 288/2025 gilt in Vietnam ein Genehmigungssystem für unbemannte Luftfahrzeuge, das nahezu jeden Flug außerhalb einer engen Ausnahme für Kleinstdrohnen erfasst.", "Nur Drohnen unter 250 Gramm dürfen außerhalb von Sperrzonen ohne gesonderte Flugerlaubnis betrieben werden, sofern Sichtflug, die Höhenbegrenzung und bestehende Flugverbotszonen eingehalten werden.", "Für alle anderen Drohnen ist ein Antrag über das nationale Verwaltungsportal sowie bei den zuständigen Militär- und Sicherheitsbehörden erforderlich, der in der Regel mindestens sieben, bei Bedarf eines NOTAM sogar zwölf Arbeitstage vor dem geplanten Flug eingereicht werden muss.", "Ausländische Reisende benötigen für diesen Antrag üblicherweise eine vietnamesische Kontakt- oder Bürgschaftsperson, etwa ein Reiseunternehmen oder eine gastgebende Institution vor Ort.", "Seit Juli 2026 müssen Drohnen zusätzlich individuell registriert und mit einer Kennung beziehungsweise einem Flugüberwachungsgerät ausgestattet werden.", "Die Standardhöhengrenze für genehmigte Flüge liegt bei 120 Metern über Grund, in sensiblen Gebieten kann die zulässige Höhe deutlich niedriger liegen oder vollständig entfallen.", "Flugverbote gelten grundsätzlich rund um Flughäfen, Grenzgebiete, militärische Einrichtungen sowie Regierungs- und andere kritische Infrastruktur; eine amtliche Karte der Sperrzonen wird vom Verteidigungsministerium veröffentlicht.", "Verstöße werden je nach Schwere mit Geldstrafen von umgerechnet rund 40 bis zu mehreren tausend US-Dollar sowie mit der Beschlagnahmung der Ausrüstung geahndet.", "Eine gesetzliche Versicherungspflicht für private Hobbyflüge besteht nicht, wird von lokalen Anbietern aber empfohlen; bei gewerblichen Genehmigungen wird ein Versicherungsnachweis in der Praxis regelmäßig verlangt."] },
  { code: "BY", name: "Weißrussland (Belarus)", maxAltitude: null, registrationRequired: true, insuranceRequired: false, sourceUrl: "https://caa.gov.by/ru/generalavia-ru/", rules: ["Wichtiger Hinweis: Privatpersonen ist der Besitz und Betrieb von Drohnen in Belarus seit einem Präsidialdekret von September 2023 grundsätzlich verboten – erlaubt sind nur nicht ferngesteuerte Spielzeuge wie Ballons oder Drachen.", "Nur Unternehmen und eingetragene Betreiber dürfen Drohnen unter behördlicher Registrierung nutzen; seit 2026 gilt dafür ein neues elektronisches Registrierungssystem mit verschärften Strafen bei Verstößen.", "Für Reisende und Freizeitpiloten heißt das in der Praxis: Eine private Drohne solltest du gar nicht erst nach Belarus mitnehmen."] },
  { code: "CY", name: "Zypern", maxAltitude: 120, registrationRequired: true, insuranceRequired: false, sourceUrl: "https://drones.gov.cy/", rules: ["In Zypern registrierst du dich als Drohnenbetreiber über das offizielle Portal der Zivilluftfahrtbehörde (uas.drones.gov.cy) – Pflicht ab 250 Gramm Startgewicht oder bei jeder Drohne mit Kamera bzw. anderem Datenerfassungs-Sensor. Die Registrierung gilt drei Jahre, der Online-Kompetenznachweis fünf Jahre.", "Registriert wird nur einmal, und zwar in dem EASA-Staat, in dem du deinen Wohnsitz hast – zum EASA-Raum gehören die EU-Länder plus Island, Liechtenstein, Norwegen und die Schweiz. Die Betreibernummer gilt dann im gesamten EASA-Raum: Wer bereits in einem anderen EASA-Land registriert ist, braucht in Zypern keine zweite Registrierung. Nur wer außerhalb des EASA-Raums wohnt, registriert sich in dem EASA-Staat, in dem er zuerst fliegt.", "Eine über die EU-Grundregel hinausgehende nationale Versicherungspflicht ist für Zypern nicht dokumentiert – es gilt die EU-weite Vorgabe, wonach eine Haftpflichtversicherung erst ab 20 Kilogramm Startgewicht Pflicht ist.", "Drohnen, die seit Januar 2024 gekauft wurden und kein EU-Klassenkennzeichen (C0–C4) tragen, dürfen in Zypern nur noch in der spezifischen Kategorie mit gesonderter Genehmigung betrieben werden.", "In der offenen Kategorie gilt eine maximale Flughöhe von 120 Metern über Grund, wie EU-weit einheitlich geregelt."] },
  { code: "EG", name: "Ägypten", maxAltitude: null, registrationRequired: true, insuranceRequired: true, sourceUrl: "https://drone-laws.com/drone-laws-in-egypt/", rules: ["Wichtiger Hinweis: In Ägypten kann eine Drohnen-Genehmigung nur über eine registrierte Institution beantragt werden – ein Unternehmen, eine Forschungseinrichtung oder einen Verein. Einzelpersonen und Touristen können selbst keinen Antrag stellen, ein Genehmigungsverfahren für Privatreisende existiert schlicht nicht.", "Zusätzlich prüft das Verteidigungsministerium jeden Antrag sicherheitsrechtlich, mit einer Bearbeitungsfrist von 30 Tagen – bleibt eine Antwort aus, gilt das als Ablehnung.", "Die reguläre Flughöhengrenze liegt bei 122 Metern (400 Fuß), ist für Touristen aber ohnehin nicht relevant, da der legale Weg fehlt. Ausgenommen von jeder Genehmigungspflicht sind lediglich reine Spielzeugdrohnen bis 150 Gramm ohne Kamera und ohne GPS.", "Der Zoll konfisziert Drohnen ohne Vorabgenehmigung nach übereinstimmenden Berichten routinemäßig, auch an den Pyramiden von Gizeh, wo Drohnenaufnahmen bei Touristen besonders beliebt wären. Nach dem ägyptischen Gesetz Nr. 216/2017 drohen bei unerlaubtem Betrieb Geldstrafen zwischen 5.000 und 50.000 EGP oder ein bis sieben Jahre Haft, in Fällen mit Terrorismusbezug im Extremfall noch deutlich mehr.", "Für die Ägypten-Reise gilt daher klar: Es gibt für normale Touristen keinen praktikablen legalen Weg, dort mit der eigenen Drohne zu fliegen. Am besten zu Hause lassen."] },
  { code: "ET", name: "Äthiopien", maxAltitude: null, registrationRequired: true, insuranceRequired: false, sourceUrl: "https://drone-laws.com/drone-laws-in-ethiopia/", rules: ["Wichtiger Hinweis: Äthiopien hat seit September 2020 ein Registrierungsprogramm der Luftfahrtbehörde ECAA, das gemeinsam mit dem Nachrichtendienst INSA betrieben wird und formal auch für ausländische Besucher gilt – inklusive einer Art Piloten-Nachweis mit Grundlagenwissen.", "In der Praxis berichten Reisende jedoch von Konfiszierungen am Flughafen, selbst wenn die bekannten Regeln befolgt wurden, was auf eine insgesamt unsichere und uneinheitliche Rechtslage hindeutet.", "Eine offizielle Angabe zur maximalen Flughöhe war nicht auffindbar. Sperrzonen bestehen unter anderem rund um Parlament und Palast, Brücken, Dämme und Treibstoffanlagen.", "Dazu kommt die Sicherheitslage: Mehrere Regionen Äthiopiens galten zuletzt als Reisewarngebiet mit expliziter Reisewarnung, in denen ohnehin an keinen normalen Drohnenbetrieb zu denken ist.", "Für die Äthiopien-Reise gilt daher: Auch außerhalb der Krisenregionen ist die Rechtslage zu unsicher und die Konfiszierungsgefahr zu hoch, um guten Gewissens zu einer Mitnahme zu raten."] },
  { code: "AT", name: "Österreich", maxAltitude: 120, registrationRequired: true, insuranceRequired: true, sourceUrl: "https://www.dronespace.at/", rules: ["Jeder Drohnenbetreiber mit Wohnsitz in Österreich muss sich einmalig bei Austro Control registrieren – die Registrierung gilt für alle eigenen Drohnen, kostet aktuell 46,80 Euro und ist drei Jahre gültig. Die vergebene 16-stellige Kennung muss sichtbar an jeder Drohne angebracht werden.", "Registriert wird nur einmal, und zwar in dem EASA-Staat, in dem du deinen Wohnsitz hast – zum EASA-Raum gehören die EU-Länder plus Island, Liechtenstein, Norwegen und die Schweiz. Die Betreibernummer gilt dann im gesamten EASA-Raum: Wer bereits in einem anderen EASA-Land registriert ist, braucht in Österreich keine zweite Registrierung. Nur wer außerhalb des EASA-Raums wohnt, registriert sich in dem EASA-Staat, in dem er zuerst fliegt.", "Für den Drohnenbetrieb ist in Österreich eine eigene Luftfahrt-Haftpflichtversicherung vorgeschrieben, unabhängig vom Gewicht der Drohne – eine private Haftpflicht- oder Haushaltsversicherung reicht in der Regel nicht. Die Mindestdeckung liegt bei 750.000 Sonderziehungsrechten, die Polizzennummer gibst du bei der Registrierung an. Viele Versicherer binden die Polizze an bestimmte Geräte (Seriennummer): Prüf, ob jede Drohne, mit der du fliegst, darauf steht.", "Österreich setzt die EU-Drohnenverordnung vollständig um: In der offenen Kategorie liegt die maximale Flughöhe bei 120 Metern, unterteilt in die Unterkategorien A1, A2 und A3 je nach zulässigem Abstand zu Personen.", "In österreichischen Nationalparks wie den Hohen Tauern lehnen Parkverwaltung und Naturschutzbehörden private Drohnenflüge ab. Wer dort fliegen will, braucht vorab eine naturschutzrechtliche Bewilligung der zuständigen Bezirkshauptmannschaft – ohne Bewilligung dort nicht fliegen. Das gilt auch für viele Natur- und Vogelschutzgebiete.", "Wo du fliegen darfst, zeigt die Karte von Austro Control auf dronespace.at und in der App „Dronespace“; dort beantragst du als registrierter Betreiber auch Fluggenehmigungen. Ohne Registrierung nutzbar ist die kostenlose App „Drohnen-Info“ des ÖAMTC."] },
];

export function getCountryDroneRule(code: string): CountryDroneRule | undefined {
  const c = code.toUpperCase();
  return COUNTRY_DRONE_RULES.find((r) => r.code === c);
}
